def has_perm(uid: int, perm: str) -> bool:
    """صاحب‌ها همه‌چیز دارن؛ پشتیبان‌ها فقط دسترسی‌هایی که بهشون داده شده."""
    return uid in OWNER_IDS or perm in STAFF.get(uid, ())


def perms_of(uid: int) -> set:
    """همه‌ی دسترسی‌های فعالِ یه کاربر (صاحب‌ها همه‌چیز)."""
    return set(SUPPORT_PERMS) if uid in OWNER_IDS else set(STAFF.get(uid, ()))


# ───────── استخراج کد ایموجی پرمیوم با همان اکانت پشتیبان (Telethon Userbot) ─────────
# برای امنیت، نشست اکانت فقط از Railway Variable خوانده می‌شود و داخل کد ذخیره نمی‌شود.
USERBOT_CLIENT = None

async def start_support_userbot():
    """یوزربات را با اکانت پشتیبان مجاز بالا می‌آورد؛ نیازمند TELEGRAM_API_ID/API_HASH/USERBOT_SESSION است."""
    global USERBOT_CLIENT
    api_id = os.environ.get("TELEGRAM_API_ID", "").strip()
    api_hash = os.environ.get("TELEGRAM_API_HASH", "").strip()
    session = os.environ.get("USERBOT_SESSION", "").strip()
    if not (api_id and api_hash and session):
        log.warning("Support userbot disabled: TELEGRAM_API_ID, TELEGRAM_API_HASH or USERBOT_SESSION is missing")
        return
    try:
        from telethon import TelegramClient, events
        from telethon.sessions import StringSession
        client = TelegramClient(StringSession(session), int(api_id), api_hash)
        await client.connect()
        if not await client.is_user_authorized():
            await client.disconnect()
            log.error("Support userbot session is not authorized; create a fresh StringSession")
            return
        me = await client.get_me()
        uid = int(me.id)
        if not (has_perm(uid, "panel") and has_perm(uid, "miniapp")):
            await client.disconnect()
            log.error("Support userbot account %s does not have both panel and miniapp permissions", uid)
            return

        @client.on(events.NewMessage(outgoing=True, pattern=r"^\s*\.?کدشو\s+میخوام\s*$"))
        async def _premium_emoji_code_handler(event):
            try:
                # فقط پیام‌های خود اکانت پشتیبان؛ در پی‌وی و گروه کار می‌کند.
                if int(event.sender_id or 0) != uid:
                    return
                if not (has_perm(uid, "panel") and has_perm(uid, "miniapp")):
                    return
                target = await event.get_reply_message()
                if target is None:
                    await event.reply("برای گرفتن کد، روی پیام دارای ایموجی پرمیوم ریپلای کن و بنویس: .کدشو میخوام")
                    return
                ids = []
                for entity in (getattr(target, "entities", None) or []):
                    if entity.__class__.__name__ == "MessageEntityCustomEmoji":
                        emoji_id = getattr(entity, "document_id", None)
                        if emoji_id is not None and str(emoji_id) not in ids:
                            ids.append(str(emoji_id))
                if not ids:
                    await event.reply("در پیام ریپلای‌شده ایموجی پرمیوم پیدا نکردم. روی پیام اصلی ریپلای کن و دوباره امتحان کن.")
                    return
                result = "🧩 کد ایموجی پرمیوم:\n" + "\n".join(f"{i}. <code>{html.escape(eid)}</code>" for i, eid in enumerate(ids[:40], 1))
                await client.send_message(event.chat_id, result, reply_to=event.id, parse_mode="html")
            except Exception:
                log.exception("support userbot emoji extraction failed")
                try:
                    await event.reply("❌ هنگام استخراج کد خطایی رخ داد. دوباره امتحان کن.")
                except Exception:
                    pass

        # ── گرفتنِ خودکارِ کد هدیه از چنل و فرستادنش به پی‌وی یه ربات دیگه ──
        # تنظیمات از Railway Variables: GIFT_CHANNELS (مثلا @chan1,-1001234567890)، GIFT_TARGET_BOT (مثلا @somebot)،
        # GIFT_SEND_TEMPLATE (پیش‌فرض {code}؛ مثلا "/redeem {code}")، GIFT_CODE_REGEX (اختیاری؛ گروه اول = کد)
        gift_chats = [(int(x) if x.lstrip("-").isdigit() else x) for x in
                      (c.strip() for c in os.environ.get("GIFT_CHANNELS", "").split(",")) if x]
        gift_target = os.environ.get("GIFT_TARGET_BOT", "").strip()
        if gift_chats and gift_target:
            gift_tpl = os.environ.get("GIFT_SEND_TEMPLATE", "{code}")
            gift_rx = None
            if os.environ.get("GIFT_CODE_REGEX", "").strip():
                try:
                    gift_rx = re.compile(os.environ["GIFT_CODE_REGEX"].strip())
                except re.error:
                    log.error("GIFT_CODE_REGEX is invalid; falling back to monospace detection")
            # الگوی پیش‌فرض: کدِ ۱۰ حرفیِ انگلیسیِ بزرگ + عدد که هم حرف داره هم عدد (مثل 4WBB4E88EP)
            gift_default_rx = re.compile(r"(?<![A-Za-z0-9])(?=[A-Z0-9]*\d)(?=[A-Z0-9]*[A-Z])([A-Z0-9]{10})(?![A-Za-z0-9])")
            gift_seen: list = []
            gift_peer = gift_target
            try:   # قبلِ شروع آدرسِ ربات مقصد رو حل می‌کنیم تا موقع فرستادن یه رفت‌وبرگشت کمتر داشته باشیم
                gift_peer = await client.get_input_entity(gift_target)
            except Exception:
                log.warning("could not pre-resolve %s; will resolve on first send", gift_target)

            @client.on(events.NewMessage(chats=gift_chats, incoming=True))
            async def _gift_code_handler(event):
                try:
                    raw = event.raw_text or ""
                    code = None
                    if gift_rx is not None:
                        m = gift_rx.search(raw)
                        if m:
                            code = (m.group(1) if m.groups() else m.group(0)).strip()
                    else:   # کدِ مونواسپیس (همونی که با یه تپ کپی میشه)
                        from telethon.tl.types import MessageEntityCode, MessageEntityPre
                        found = event.message.get_entities_text((MessageEntityCode, MessageEntityPre))
                        if found:
                            code = found[0][1].strip()
                        if not code:
                            m = gift_default_rx.search(raw)
                            if m:
                                code = m.group(1)
                    if not code or code in gift_seen:
                        return
                    gift_seen.append(code)
                    del gift_seen[:-200]
                    await client.send_message(gift_peer, gift_tpl.replace("{code}", code), parse_mode=None)
                    log.info("gift code %r sent to %s", code, gift_target)
                except Exception:
                    log.exception("gift code forward failed")

            log.info("Gift-code forwarder active: %s -> %s", gift_chats, gift_target)

        # ── بتِ خودکار (برای بازیِ پول‌مجازیِ یه ربات دیگه) ──
        # Variables: AUTOBET_TARGET (مثلا @somebot)، AUTOBET_TEMPLATE (متنی که هر بار فرستاده میشه؛ مثلا "/bet 1000")،
        # AUTOBET_INTERVAL (ثانیه؛ پیش‌فرض ۲۰، حداقل ۵)، AUTOBET_MAX (سقف تعداد؛ پیش‌فرض ۱۰۰).
        # کنترل: تو «پیام‌های ذخیره‌شده»ی همین اکانت بنویس «شروع بت» یا «توقف بت». نتیجه‌ی بت دست اون رباته؛ برد تضمین نیست.
        ab_target = os.environ.get("AUTOBET_TARGET", "").strip()
        ab_tpl = os.environ.get("AUTOBET_TEMPLATE", "").strip()
        if ab_target and ab_tpl:
            ab_every = max(5.0, float(os.environ.get("AUTOBET_INTERVAL", "20")))
            ab_max = max(1, int(os.environ.get("AUTOBET_MAX", "100")))
            ab_state = {"task": None}

            async def _autobet_loop():
                n = 0
                try:
                    while n < ab_max:
                        await client.send_message(ab_target, ab_tpl, parse_mode=None)
                        n += 1
                        await asyncio.sleep(ab_every)
                except asyncio.CancelledError:
                    raise
                except Exception:
                    log.exception("autobet loop failed")
                finally:
                    ab_state["task"] = None

            @client.on(events.NewMessage(chats="me", outgoing=True))
            async def _autobet_ctl(event):
                t = (event.raw_text or "").strip()
                tk = ab_state["task"]
                if t in ("شروع بت", "بت شروع"):
                    if tk is not None and not tk.done():
                        await event.reply("بت خودکار از قبل روشنه.")
                    else:
                        ab_state["task"] = asyncio.create_task(_autobet_loop())
                        await event.reply(f"بت خودکار روشن شد؛ هر {ab_every:g} ثانیه، حداکثر {ab_max} بار.")
                elif t in ("توقف بت", "بت توقف"):
                    if tk is not None and not tk.done():
                        tk.cancel()
                        await event.reply("بت خودکار متوقف شد.")
                    else:
                        await event.reply("بت خودکار روشن نبود.")

            log.info("Autobet ready: %r -> %s every %ss (max %s)", ab_tpl, ab_target, ab_every, ab_max)

        USERBOT_CLIENT = client
        log.info("Support userbot connected as account %s", uid)
    except ImportError:
        log.error("Telethon is not installed; add 'Telethon' to requirements.txt")
    except Exception:
        log.exception("Could not start support userbot")

async def stop_support_userbot():
    global USERBOT_CLIENT
    if USERBOT_CLIENT is not None:
        try:
            await USERBOT_CLIENT.disconnect()
        finally:
            USERBOT_CLIENT = None

