# ───────────────────────── دیتابیس (PostgreSQL) ─────────────────────────
async def init_db(app: Application):
    global pool
    pool = await asyncpg.create_pool(DATABASE_URL, min_size=2, max_size=20)   # قبلاً max=5 بود و با کار همزمان صف می‌خورد
    await pool.execute("CREATE TABLE IF NOT EXISTS wordfinder_used_words (word TEXT PRIMARY KEY, used_at DOUBLE PRECISION NOT NULL DEFAULT 0)")
    async with pool.acquire() as c:
        await c.execute(
            """CREATE TABLE IF NOT EXISTS users (
                user_id  BIGINT PRIMARY KEY,
                name     TEXT,
                balance  BIGINT NOT NULL DEFAULT 0,
                last_ts  DOUBLE PRECISION NOT NULL DEFAULT 0,
                started  BOOLEAN NOT NULL DEFAULT FALSE
            )"""
        )
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS bank_balance BIGINT NOT NULL DEFAULT 0")
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS hand_level INT NOT NULL DEFAULT 0")
        await c.execute("CREATE TABLE IF NOT EXISTS user_house (user_id BIGINT PRIMARY KEY REFERENCES users(user_id) ON DELETE CASCADE, repair_done_at DOUBLE PRECISION NOT NULL DEFAULT 0, last_claim DOUBLE PRECISION NOT NULL DEFAULT 0, stored_income BIGINT NOT NULL DEFAULT 0, items TEXT NOT NULL DEFAULT '')")
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS condoms INT NOT NULL DEFAULT 0")
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS pills INT NOT NULL DEFAULT 0")
        await c.execute("CREATE TABLE IF NOT EXISTS couple_relation (pair_key TEXT PRIMARY KEY, relation INT NOT NULL DEFAULT 0, last_sex DOUBLE PRECISION NOT NULL DEFAULT 0)")
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS gender TEXT")
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS username TEXT")
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS banned_until DOUBLE PRECISION NOT NULL DEFAULT 0")
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS jaghs BIGINT NOT NULL DEFAULT 0")
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS last_shift DOUBLE PRECISION NOT NULL DEFAULT 0")
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS shift_seen TEXT NOT NULL DEFAULT ''")
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS work_count BIGINT NOT NULL DEFAULT 0")
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS job_level INT NOT NULL DEFAULT 0")       # تعداد شغل‌های گرفته‌شده (۰ = بیکار)
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS edu_units INT NOT NULL DEFAULT 0")       # مجموع واحدهای درسی
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS edu_degree INT NOT NULL DEFAULT 0")      # ۰ بدون مدرک، ۱ دیپلم ... ۵ پروفسوری
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS edu_last DOUBLE PRECISION NOT NULL DEFAULT 0")
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS edu_pending TEXT NOT NULL DEFAULT ''")
        await c.execute("CREATE TABLE IF NOT EXISTS edu_custom_q (id SERIAL PRIMARY KEY, subj TEXT NOT NULL, question TEXT NOT NULL, options TEXT NOT NULL, right_idx INT NOT NULL, units INT NOT NULL, created_by BIGINT, created_at DOUBLE PRECISION NOT NULL DEFAULT 0)")
        try:   # سوال‌هایی که پشتیبان‌ها طرح کردن میرن تو چرخه‌ی همون درس (قبل از اولین استفاده از EDU_SUBJECTS)
            for r in await c.fetch("SELECT subj, question, options, right_idx, units FROM edu_custom_q ORDER BY id"):
                if r["subj"] in EDU_SUBJECTS:
                    EDU_SUBJECTS[r["subj"]][1].append((r["question"], json.loads(r["options"]), int(r["right_idx"]), int(r["units"])))
        except Exception:
            log.exception("custom edu questions load failed")
        # مهاجرت یک‌باره: شغل فعلی کاربرهای قبلی (که با امتیاز باز شده بود) ریست نشه.
        # سطح قدیمی = level_for(امتیاز)؛ پله‌ی آخر (۱۰) فقط با ۱۲۰۰ کار. فقط کسانی که هنوز با سیستم جدید کاری نکردن عوض میشن.
        await c.execute("CREATE TABLE IF NOT EXISTS bot_migrations (name TEXT PRIMARY KEY)")
        if not await c.fetchval("SELECT 1 FROM bot_migrations WHERE name='job_level_from_jaghs'"):
            _n_jobs = len(LEVEL_THRESHOLDS)
            await c.execute(
                """UPDATE users SET job_level = LEAST($1::int, GREATEST(1, (
                        SELECT COALESCE(MAX(t.ord), 1) FROM unnest($2::int[]) WITH ORDINALITY AS t(th, ord)
                        WHERE users.jaghs >= t.th)))
                   WHERE gender IS NOT NULL AND job_level = 0 AND edu_degree = 0 AND edu_units = 0""",
                _n_jobs, LEVEL_THRESHOLDS)
            await c.execute(
                "UPDATE users SET job_level = $1::int - 1 WHERE job_level = $1::int AND work_count < 1200 AND jaghs >= $2::int AND edu_degree = 0 AND edu_units = 0",
                _n_jobs, LEVEL_THRESHOLDS[-1])
            await c.execute("INSERT INTO bot_migrations(name) VALUES('job_level_from_jaghs') ON CONFLICT DO NOTHING")
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS job_sel INT NOT NULL DEFAULT 0")          # شغل فعالِ انتخاب‌شده (۰ = بالاترین شغل)
        # مهاجرت یک‌باره: کسی که قبلاً با امتیاز به شغلی رسیده، مدرک (و واحد) همون شغل رو هم داره و باید شغل‌های پایین‌ترش هم باز بمونه.
        if not await c.fetchval("SELECT 1 FROM bot_migrations WHERE name='degree_from_jobs'"):
            await c.execute(
                """UPDATE users SET
                       edu_degree = GREATEST(edu_degree, ($1::int[])[job_level]),
                       edu_units  = GREATEST(edu_units, COALESCE(($2::int[])[($1::int[])[job_level]], 0))
                   WHERE job_level BETWEEN 1 AND $3::int""",
                JOB_DEGREE_NEED, [u for _n, u, _f in EDU_DEGREES], len(JOB_DEGREE_NEED))
            await c.execute("INSERT INTO bot_migrations(name) VALUES('degree_from_jobs') ON CONFLICT DO NOTHING")
        await c.execute(f"ALTER TABLE users ADD COLUMN IF NOT EXISTS energy DOUBLE PRECISION NOT NULL DEFAULT {ENERGY_START}")
        await c.execute(f"ALTER TABLE users ALTER COLUMN energy SET DEFAULT {ENERGY_START}")
        await c.execute("CREATE TABLE IF NOT EXISTS rifts (user_lo BIGINT NOT NULL, user_hi BIGINT NOT NULL, ends_at DOUBLE PRECISION NOT NULL, PRIMARY KEY (user_lo, user_hi))")
        await c.execute("CREATE TABLE IF NOT EXISTS rift_log (initiator BIGINT NOT NULL, target BIGINT NOT NULL, day TEXT NOT NULL, cnt INT NOT NULL DEFAULT 0, PRIMARY KEY (initiator, target, day))")
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS last_hug DOUBLE PRECISION NOT NULL DEFAULT 0")
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS jagh_machine BIGINT NOT NULL DEFAULT 0")
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS last_steal DOUBLE PRECISION NOT NULL DEFAULT 0")
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS spouse_id BIGINT")
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS spy_owned BOOLEAN NOT NULL DEFAULT FALSE")
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS msg_total BIGINT NOT NULL DEFAULT 0")
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS pets_owned INT NOT NULL DEFAULT 0")
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS pet_active INT NOT NULL DEFAULT 1")
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS pet_names TEXT NOT NULL DEFAULT '{}'")
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS pet_t_pet DOUBLE PRECISION NOT NULL DEFAULT 0")
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS pet_t_feed DOUBLE PRECISION NOT NULL DEFAULT 0")
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS pet_t_walk DOUBLE PRECISION NOT NULL DEFAULT 0")
        await c.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS pet_acts INT NOT NULL DEFAULT 0")
