async def _social_room(qs, user):
    after = _int(qs.get("after"), 0, 0)
    rows = await pool.fetch(
        "SELECT m.message_id,m.user_id,m.text,m.reply_to,m.premium_emoji_id,m.created_at,sp.username,sp.display_name,u.name AS uname, "
        "EXISTS(SELECT 1 FROM mini_subscriptions ms WHERE ms.user_id=m.user_id AND ms.expires_at>$3) AS premium, "
        "(SELECT json_agg(json_build_object('emoji',r.emoji,'n',r.n,'mine',r.mine)) FROM (SELECT emoji,count(*)::int n,bool_or(user_id=$2) mine FROM social_room_reactions WHERE message_id=m.message_id GROUP BY emoji) r) reactions, "
        "(SELECT text FROM social_room_messages x WHERE x.message_id=m.reply_to) reply_text, "
        "(SELECT COALESCE(sp2.display_name,sp2.username,u2.name,x.user_id::text) FROM social_room_messages x LEFT JOIN social_profiles sp2 ON sp2.user_id=x.user_id LEFT JOIN users u2 ON u2.user_id=x.user_id WHERE x.message_id=m.reply_to) reply_name, "
        "(SELECT count(*)::int FROM social_room_reads rr WHERE rr.user_id<>m.user_id AND rr.last_read_message_id>=m.message_id) read_count "
        "FROM social_room_messages m LEFT JOIN social_profiles sp ON sp.user_id=m.user_id LEFT JOIN users u ON u.user_id=m.user_id "
        "WHERE ($1=0 OR m.message_id>$1) ORDER BY m.message_id DESC LIMIT 100", after, int(user["id"]), time.time())
    out = []
    bot = await _rp_bot()
    for r in reversed(rows):
        d = dict(r)
        rx = d.get("reactions")
        if isinstance(rx, str):   # json_agg بدون codec به‌صورت متن برمی‌گرده؛ باید به لیست تبدیل بشه
            try: rx = json.loads(rx)
            except Exception: rx = []
        d["reactions"] = rx or []
        if int(d["user_id"]) == int(bot["id"]):
            d["display_name"] = bot["name"]
            d["is_bot"] = True
            d["name_ce"] = RP_BOT_EMOJI
        out.append(d)
    return _j(out)


async def _social_room_read(b,user):
    uid = int(user["id"])
    last_id = _int(b.get("last_read_message_id"), 0, 0)
    if last_id:
        # Only acknowledge messages that actually exist; never move a receipt backwards.
        last_id = int(await pool.fetchval(
            "SELECT COALESCE(max(message_id),0) FROM social_room_messages WHERE message_id<=$1",
            last_id) or 0)
        await pool.execute(
            "INSERT INTO social_room_reads(user_id,last_read_message_id,updated_at) VALUES($1,$2,$3) "
            "ON CONFLICT(user_id) DO UPDATE SET "
            "last_read_message_id=GREATEST(social_room_reads.last_read_message_id,EXCLUDED.last_read_message_id), "
            "updated_at=EXCLUDED.updated_at",
            uid, last_id, time.time())
    return _j({"ok": True, "last_read_message_id": last_id})


async def _social_room_send(b,user):
    uid=int(user["id"]); txt=(b.get("text") or "").strip(); reply=_int(b.get("reply_to")); pe=(str(b.get("premium_emoji_id") or "").strip() or None)
    # ایموجی پرمیوم وسط متن به شکل {ce:شناسه} ذخیره میشه؛ هر ایموجی تو شمارش طول یه کاراکتره
    if len(_CE_TOKEN_RE.sub("•", txt)) > 1200: raise _ApiError("پیام خیلی طولانیه (حداکثر ۱۲۰۰ کاراکتر)")
    if len(_CE_TOKEN_RE.findall(txt)) > 60: raise _ApiError("تو یه پیام حداکثر ۶۰ ایموجی پرمیوم می‌تونی بذاری")
    if not txt and not pe: raise _ApiError("پیام خالیه")
    if pe and not pe.isdigit(): raise _ApiError("شناسه ایموجی پرمیوم معتبر نیست")
    if pe or _CE_TOKEN_RE.search(txt):
        exp = await pool.fetchval("SELECT expires_at FROM mini_subscriptions WHERE user_id=$1", uid)
        if not (exp and float(exp) > time.time()) and not _social_emoji_staff(user):
            raise _ApiError("ارسال ایموجی پرمیوم فقط با اشتراک ویژه فعاله.", 403)
    if reply and not await pool.fetchval("SELECT 1 FROM social_room_messages WHERE message_id=$1",reply): reply=None
    mid=await pool.fetchval("INSERT INTO social_room_messages(user_id,text,reply_to,premium_emoji_id,created_at) VALUES($1,$2,$3,$4,$5) RETURNING message_id",uid,txt,reply,pe,time.time())
    return _j({"ok":True,"message_id":mid})


_CE_THUMB: dict = {}   # شناسه ایموجی سفارشی → file_id بندانگشتی (از پک‌هایی که کاربرا باز کردن)
_CE_LINK_RE = re.compile(r"(?:https?://)?(?:t|telegram)\.me/(?:addemoji|addstickers)/([A-Za-z0-9_]{1,64})", re.I)
_CE_TOKEN_RE = re.compile(r"\{ce:(\d{5,25})\}")


def _ce_pack_name(s):
    s = (s or "").strip()
    m = _CE_LINK_RE.search(s)
    if m:
        return m.group(1)
    return s if re.fullmatch(r"[A-Za-z0-9_]{3,64}", s) else None


async def _social_emoji_pack(qs, user):
    """لینک پک ایموجی پرمیوم (t.me/addemoji/...) → لیست ایموجی‌های پک برای پنل چت‌روم."""
    name = _ce_pack_name(qs.get("link"))
    if not name or BOT_REF is None:
        raise _ApiError("لینک پک ایموجی معتبر نیست؛ مثلاً t.me/addemoji/اسم_پک")
    try:
        st = await _ttl(f"ceset:{name.lower()}", 600, lambda: _tg_call(BOT_REF.get_sticker_set, name))
    except Exception:
        raise _ApiError("این پک پیدا نشد؛ لینکش رو چک کن")
    stype = getattr(st, "sticker_type", None)
    if stype is not None and stype != "custom_emoji":
        raise _ApiError("این لینک پک ایموجی نیست (پک استیکره). لینک t.me/addemoji/... بذار")
    if len(_CE_THUMB) > 20000:
        _CE_THUMB.clear()
    items = []
    for s in list(st.stickers)[:200]:
        cid = getattr(s, "custom_emoji_id", None)
        if not cid:
            continue
        th = getattr(s, "thumbnail", None)
        fid = getattr(th, "file_id", None) or getattr(s, "file_id", None)
        if fid:
            _CE_THUMB[str(cid)] = fid
        items.append({"id": str(cid), "e": s.emoji or ""})
    if not items:
        raise _ApiError("تو این پک ایموجی پرمیومی پیدا نشد")
    return _j({"name": st.name, "title": st.title, "items": items})


async def _social_emoji_image(qs, user):
    """تصویر بندانگشتی ایموجی سفارشی تلگرام برای نمایش داخل WebView."""
    eid = str(qs.get("id") or "").strip()
    if not eid.isdigit() or BOT_REF is None:
        return 404, "text/plain", b"not found", {}
    hit = _bin_get(f"ce:{eid}")
    if hit:
        return 200, hit[1], hit[2], {"Cache-Control": "private, max-age=3600"}
    try:
        fid = _CE_THUMB.get(eid)
        if not fid:
            stickers = await _tg_call(BOT_REF.get_custom_emoji_stickers, [eid])
            if not stickers:
                return 404, "text/plain", b"not found", {}
            sticker = stickers[0]
            thumb = getattr(sticker, "thumbnail", None)
            fid = getattr(thumb, "file_id", None) or getattr(sticker, "file_id", None)
            if fid:
                _CE_THUMB[eid] = fid
        data = await _download(fid, 2 * 1024 * 1024) if fid else b""
        ctype = _sniff_image(data) if data else None
        if not ctype:
            return 404, "text/plain", b"not found", {}
        _bin_put(f"ce:{eid}", 3600, ctype, data)
        return 200, ctype, data, {"Cache-Control": "private, max-age=3600"}
    except Exception:
        log.debug("custom emoji preview unavailable: %s", eid, exc_info=True)
        return 404, "text/plain", b"not found", {}


async def _social_room_react(b,user):
    mid=_int(b.get("message_id")); emoji=(b.get("emoji") or "❤️").strip()
    if mid is None or emoji not in ("❤️","😂","😍","🔥","👏","👍","👎","😮"): raise _ApiError("ری‌اکشن نامعتبره")
    uid=int(user["id"])
    exp=await pool.fetchval("SELECT expires_at FROM mini_subscriptions WHERE user_id=$1",uid)
    vip=bool(exp and float(exp)>time.time()) or _social_emoji_staff(user)
    async with pool.acquire() as c:
        async with c.transaction():
            if not vip:
                # حساب عادی: روی هر پیام فقط یه ری‌اکشن؛ همون رو دوباره بزنه برمی‌داره، یکی دیگه بزنه جایگزین میشه
                had=await c.fetchval("SELECT 1 FROM social_room_reactions WHERE message_id=$1 AND user_id=$2 AND emoji=$3",mid,uid,emoji)
                await c.execute("DELETE FROM social_room_reactions WHERE message_id=$1 AND user_id=$2",mid,uid)
                if had: return _j({"ok":True,"removed":True})
            await c.execute("INSERT INTO social_room_reactions(message_id,user_id,emoji,created_at) VALUES($1,$2,$3,$4) ON CONFLICT(message_id,user_id,emoji) DO NOTHING",mid,uid,emoji,time.time())
    return _j({"ok":True})



# ───── بازی دونفره «سم یا خوراکی» داخل چت‌روم مینی‌اپ ─────
# سازنده شرط رو تعیین می‌کنه (پولش همون لحظه کم میشه) و منتظر می‌مونه؛ نفر دوم باید همون مبلغ رو بده.
# هر دو سم خودشون رو پشت یکی از ۲۴ خانه مخفی می‌کنن، بعد نوبتی خانه باز می‌کنن؛ هر کی سم حریف رو پیدا کنه می‌بازه.
# برنده ۲ برابر شرط می‌گیره. مهلت‌ها به‌صورت lazy (موقع هر درخواست) بررسی میشن و تو دیتابیس می‌مونن، پس با ری‌استارت هم پول گم نمیشه.
RP_CELLS = 24
RP_TURN_SECS = 60
RP_LOBBY_SECS = 120
RP_DONE_SHOW = 0
RP_MAX_LOBBIES = 3
_ROOM_TABLE_MAX_ACTIVE = 3
_ROOM_TABLE_CREATE_LOCK = asyncio.Lock()
_RP_LOCK = asyncio.Lock()


def _rp_load(r) -> dict:
    g = dict(r)
    st = {}
    try:
        st = json.loads(g.get("state") or "{}")
    except Exception:
        st = {}
    g["hidden"] = {int(k): int(v) for k, v in (st.get("hidden") or {}).items()}
    g["opened"] = [int(x) for x in (st.get("opened") or [])]
    return g


async def _rp_fetch(gid):
    if gid is None:
        return None
    r = await pool.fetchrow("SELECT * FROM room_poison_games WHERE game_id=$1", gid)
    return _rp_load(r) if r else None


async def _rp_store(g: dict):
    await pool.execute(
        "UPDATE room_poison_games SET opponent=$2, phase=$3, turn=$4, deadline=$5, winner=$6, reason=$7, state=$8, finished_at=$9 WHERE game_id=$1",
        g["game_id"], g.get("opponent"), g["phase"], g.get("turn"), g.get("deadline"), g.get("winner"), g.get("reason"),
        json.dumps({"hidden": {str(k): v for k, v in g["hidden"].items()}, "opened": g["opened"]}), g.get("finished_at"))


RP_BOT_EMOJI = "5805662179113832818"   # ایموجی پرمیوم کنار اسم ربات
_RP_BOT: dict = {}


async def _rp_bot() -> dict:
    """اکانت خود ربات تو چت‌روم (آیدی از روی توکن، اسم از getMe)."""
    if not _RP_BOT.get("ok"):
        _RP_BOT.setdefault("id", int(BOT_TOKEN.split(":")[0]))
        _RP_BOT.setdefault("name", "ربات")
        try:
            if BOT_REF is not None:
                me = await _tg_call(BOT_REF.get_me)
                _RP_BOT["name"] = (me.full_name or me.first_name or "ربات")
                _RP_BOT["ok"] = True
        except Exception:
            log.debug("room bot getMe failed", exc_info=True)
    return _RP_BOT


async def _rp_say(text: str):
    """ربات یه پیام تو چت‌روم می‌ذاره تا همه ببینن چی شد."""
    try:
        bot = await _rp_bot()
        await pool.execute("INSERT INTO social_room_messages(user_id,text,created_at) VALUES($1,$2,$3)", int(bot["id"]), text, time.time())
    except Exception:
        log.debug("room poison say failed", exc_info=True)


async def _rp_finish(g: dict, winner, reason: str, say: bool = True):
    """پایان بازی. winner=None یعنی مساوی/لغو و شرط‌ها برمی‌گرده؛ وگرنه برنده کل جایزه رو می‌گیره."""
    if g["phase"] == "done":
        return
    g.update(phase="done", winner=winner, reason=reason, turn=None, deadline=None, finished_at=time.time())
    bet = int(g["bet"])
    if winner is None:
        await _give(g["creator"], bet)
        if g.get("opponent"):
            await _give(g["opponent"], bet)
    else:
        await _give(winner, bet * 2)
    await _rp_store(g)
    if say and not g.get("silent"):
        nm = await _rp_names([g["creator"], g.get("opponent")])
        a, b = nm.get(g["creator"], "بازیکن"), nm.get(g.get("opponent"), "بازیکن")
        if winner is not None:
            win = a if winner == g["creator"] else b
            await _rp_say(f"🏆 {win} برنده‌ی «سم یا خوراکی» شد!\n⚔️ {a} در برابر {b}\n📌 {reason}\n💰 جایزه: {bet * 2:,} تومن به حسابش رفت 🎉")
        elif g.get("opponent"):
            await _rp_say(f"🤝 بازی «سم یا خوراکی» بین {a} و {b} مساوی شد؛ شرط {bet:,} تومنی به هر دو برگشت.")


async def _rp_tick(g: dict):
    now = time.time()
    if g["phase"] == "lobby":
        if now - float(g["created_at"]) > RP_LOBBY_SECS:
            await _rp_finish(g, None, "کسی وارد نشد؛ شرط به سازنده برگشت.", say=False)
    elif g["phase"] == "hide":
        if g.get("deadline") and now > g["deadline"]:
            hid = list(g["hidden"].keys())
            if len(hid) == 1:
                await _rp_finish(g, hid[0], "حریف مهلتش برای مخفی کردن سم تموم شد.")
            else:
                await _rp_finish(g, None, "هیچ‌کدوم سم رو مخفی نکردن؛ شرط‌ها برگشت.")
    elif g["phase"] == "guess":
        if g.get("deadline") and now > g["deadline"]:
            loser = g.get("turn")
            winner = g["opponent"] if loser == g["creator"] else g["creator"]
            await _rp_finish(g, winner, "مهلت انتخاب تموم شد؛ حریف برنده شد.")


async def _rp_sweep() -> list:
    """همه‌ی بازی‌های باز رو می‌گیره و مهلت‌های تموم‌شده رو تکلیف می‌کنه (باید زیر _RP_LOCK صدا زده بشه)."""
    out = []
    for r in await pool.fetch("SELECT * FROM room_poison_games WHERE phase<>'done' ORDER BY game_id"):
        g = _rp_load(r)
        await _rp_tick(g)
        if g["phase"] != "done":
            out.append(g)
    return out


async def _rp_names(uids) -> dict:
    uids = [int(u) for u in set(uids) if u]
    if not uids:
        return {}
    rows = await pool.fetch(
        "SELECT u.user_id, COALESCE(NULLIF(sp.display_name,''), NULLIF(sp.username,''), NULLIF(u.name,'')) AS n "
        "FROM users u LEFT JOIN social_profiles sp ON sp.user_id=u.user_id WHERE u.user_id = ANY($1::bigint[])", uids)
    return {int(r["user_id"]): (r["n"] or str(r["user_id"])) for r in rows}


def _rp_view(g: dict, uid: int, names: dict, now: float) -> dict:
    mine = uid in (g["creator"], g.get("opponent"))
    left = None
    if g["phase"] == "lobby":
        left = max(0, int(RP_LOBBY_SECS - (now - float(g["created_at"]))))
    elif g.get("deadline"):
        left = max(0, int(g["deadline"] - now))
    d = {"id": g["game_id"], "creator": g["creator"], "creator_name": names.get(g["creator"], "بازیکن"),
         "opponent": g.get("opponent"), "opponent_name": names.get(g.get("opponent"), "") if g.get("opponent") else "",
         "bet": int(g["bet"]), "pot": int(g["bet"]) * 2, "phase": g["phase"], "turn": g.get("turn"), "left": left,
         "opened": g["opened"], "me": mine, "my_cell": g["hidden"].get(uid) if mine else None,
         "hid": sorted(g["hidden"].keys()), "winner": g.get("winner"), "reason": g.get("reason") or ""}
    if g["phase"] == "done":
        d["poisons"] = sorted(set(g["hidden"].values()))
    return d


async def _social_poison_state(qs, user):
    uid = int(user["id"])
    async with _RP_LOCK:
        games = await _rp_sweep()
        recent = []  # میزهای تمام‌شده دیگر در بالای چت‌روم نمایش داده نمی‌شوند.
        games += [_rp_load(r) for r in recent]
    names = await _rp_names([x for g in games for x in (g["creator"], g.get("opponent"))])
    now = time.time()
    views = [_rp_view(g, uid, names, now) for g in games]
    subs = await _mini_sub_set([x for g in games for x in (g["creator"], g.get("opponent"))])
    for v in views:
        v["creator_prem"] = v["creator"] in subs
        v["opponent_prem"] = bool(v["opponent"]) and v["opponent"] in subs
    views.sort(key=lambda v: (not v["me"], -v["id"]))
    return _j({"games": views, "balance": await _mini_balance(uid), "min_bet": CASINO_MIN_BET, "max_bet": CASINO_MAX_BET})


async def _mini_sub_set(uids) -> set:
    """آیدی کاربرانی که اشتراک ویژه‌ی فعال دارن."""
    uids = [int(u) for u in set(uids) if u]
    if not uids:
        return set()
    rows = await pool.fetch("SELECT user_id FROM mini_subscriptions WHERE user_id = ANY($1::bigint[]) AND expires_at > $2", uids, time.time())
    return {int(r["user_id"]) for r in rows}


_GC_TABLES = {"poison": "room_poison_games", "carrom": "room_carrom_games"}
GC_MAX_LEN = 200


async def _social_gamechat_get(qs, user):
    """پیام‌های چت یک میز؛ همه می‌تونن بخونن، فقط بازیکن‌های دارای اشتراک می‌تونن بفرستن."""
    kind = str(qs.get("kind") or "")
    gid = _int(qs.get("game_id"))
    if kind not in _GC_TABLES or gid is None:
        raise _ApiError("بازی نامعتبره.")
    after = _int(qs.get("after"), 0) or 0
    rows = await pool.fetch("SELECT id,user_id,text,created_at FROM room_game_chat WHERE kind=$1 AND game_id=$2 AND id>$3 ORDER BY id LIMIT 60", kind, gid, after)
    uids = [int(r["user_id"]) for r in rows]
    names = await _rp_names(uids)
    subs = await _mini_sub_set(uids)
    return _j({"messages": [{"id": int(r["id"]), "user_id": int(r["user_id"]), "name": names.get(int(r["user_id"]), "بازیکن"),
                             "text": r["text"], "prem": int(r["user_id"]) in subs, "ts": float(r["created_at"])} for r in rows]})


async def _social_gamechat_send(b, user):
    uid = int(user["id"])
    kind = str(b.get("kind") or "")
    gid = _int(b.get("game_id"))
    if kind not in _GC_TABLES or gid is None:
        raise _ApiError("بازی نامعتبره.")
    txt = re.sub(r"\s+", " ", str(b.get("text") or "")).strip()
    if not txt:
        raise _ApiError("پیام خالیه")
    if len(txt) > GC_MAX_LEN:
        raise _ApiError(f"پیام خیلی طولانیه (حداکثر {GC_MAX_LEN} کاراکتر)")
    exp = await pool.fetchval("SELECT expires_at FROM mini_subscriptions WHERE user_id=$1", uid)
    if not (exp and float(exp) > time.time()) and not _social_emoji_staff(user):
        raise _ApiError("چت هنگام بازی فقط با اشتراک ویژه فعاله.", 403)
    g = await pool.fetchrow(f"SELECT creator, opponent, phase FROM {_GC_TABLES[kind]} WHERE game_id=$1", gid)
    if not g or g["phase"] in ("lobby", "done"):
        raise _ApiError("چت فقط وقتی بازی در جریانه فعاله.")
    if uid not in (g["creator"], g["opponent"]):
        raise _ApiError("فقط بازیکن‌های همین میز می‌تونن چت کنن.", 403)
    now = time.time()
    last = await pool.fetchval("SELECT max(created_at) FROM room_game_chat WHERE user_id=$1", uid)
    if last and now - float(last) < 0.8:
        raise _ApiError("آروم‌تر بفرست.")
    mid = await pool.fetchval("INSERT INTO room_game_chat(kind,game_id,user_id,text,created_at) VALUES($1,$2,$3,$4,$5) RETURNING id", kind, gid, uid, txt, now)
    if random.random() < 0.03:
        await pool.execute("DELETE FROM room_game_chat WHERE created_at < $1", now - 86400)
    return _j({"ok": True, "id": int(mid)})


def _rp_busy_sql() -> str:
    return "SELECT 1 FROM room_poison_games WHERE phase<>'done' AND (creator=$1 OR opponent=$1)"


# ───────── کولداون بازی‌های کازینو (مشترک بین ربات و مینی‌اپ) ─────────
# slow (۳ دقیقه): اسلات، تاس، برج گنج، بازی‌های ورزشی (دارت/بولینگ/بسکتبال)، سم یا خوراکی
# fast (۱۵ ثانیه): مین، پلینکو (و جینگو بت که کولداون جدا و هم‌اندازه‌ی همین رو داره)
# موشک: بدون کولداون
CASINO_COOLDOWN_SLOW = 180
CASINO_COOLDOWN_FAST = 15
CD_SLOW_GAMES = frozenset({"slot", "dice", "tower", "darts", "bowl", "hoop", "poison"})
_CD_STAMPS = {"slow": {}, "fast": {}}


def _cd_kind(game) -> str:
    return "slow" if game in CD_SLOW_GAMES else "fast"


def _cd_left_uid(uid: int, game="mines") -> int:
    if game == "crash":      # موشک کولداون نداره
        return 0
    kind = _cd_kind(game)
    secs = CASINO_COOLDOWN_SLOW if kind == "slow" else CASINO_COOLDOWN_FAST
    left = secs - (time.time() - _CD_STAMPS[kind].get(uid, 0))
    return int(left) + 1 if left > 0 else 0


def _cd_set_uid(uid: int, game="mines"):
    if game == "crash":      # موشک کولداون نداره
        return
    st = _CD_STAMPS[_cd_kind(game)]
    if len(st) > 20000:
        cut = time.time() - CASINO_COOLDOWN_SLOW
        for k in [k for k, v in st.items() if v < cut]:
            st.pop(k, None)
    st[uid] = time.time()


def _cd_plain(left: int) -> str:
    t = f"{left // 60} دقیقه و {left % 60} ثانیه" if left >= 60 else f"{left} ثانیه"
    return f"انقدر دیگه امتیاز زدی که خسته‌ای! یه نفس بگیر؛ {t} دیگه می‌تونی این بازی رو شروع کنی."


def _cd_guard(game):
    """دکوراتور شروع بازی‌های مینی‌اپ: اگه کولداون نگذشته خطا میده، بعد از شروع موفق کولداون ثبت میشه."""
    import functools

    def deco(fn):
        @functools.wraps(fn)
        async def wrapper(b, user):
            uid = int(user["id"])
            left = _cd_left_uid(uid, game)
            if left > 0:
                raise _ApiError(_cd_plain(left))
            res = await fn(b, user)
            _cd_set_uid(uid, game)
            return res
        return wrapper
    return deco


async def _social_poison_create(b, user):
    uid, _bal = await _mini_ctx(user)
    if (left := _cd_left_uid(uid, "poison")) > 0:
        raise _ApiError(_cd_plain(left))
    try:
        bet = int(float(str(b.get("bet")).replace(",", "").strip()))
    except (TypeError, ValueError):
        raise _ApiError("مبلغ شرط نامعتبره")
    if bet < CASINO_MIN_BET:
        raise _ApiError(f"حداقل شرط {CASINO_MIN_BET:,} تومنه.")
    if bet > CASINO_MAX_BET:
        raise _ApiError(f"حداکثر شرط {CASINO_MAX_BET:,} تومنه.")
    async with _ROOM_TABLE_CREATE_LOCK, _RP_LOCK, _CR_LOCK:
        await _rp_sweep()
        await _cr_sweep()
        if await pool.fetchval(_rp_busy_sql(), uid) or await pool.fetchval(_cr_busy_sql(), uid):
            raise _ApiError("تو همین الان یه بازی فعال داری.")
        active_tables = int(await pool.fetchval("SELECT (SELECT count(*) FROM room_poison_games WHERE phase<>'done') + (SELECT count(*) FROM room_carrom_games WHERE phase<>'done')") or 0)
        if active_tables >= _ROOM_TABLE_MAX_ACTIVE:
            raise _ApiError("ظرفیت چت‌روم پره؛ حداکثر ۳ میز می‌تونه هم‌زمان فعال باشه. بعد از پایان یا انقضای یکی از میزها دوباره تلاش کن.")
        if await _take(uid, bet) is None:
            raise _ApiError("موجودی کافی نیست.")
        try:
            gid = await pool.fetchval(
                "INSERT INTO room_poison_games(creator,bet,phase,state,created_at,silent) VALUES($1,$2,'lobby','{}',$3,$4) RETURNING game_id",
                uid, bet, time.time(), bool(b.get("silent")))
        except Exception:
            await _give(uid, bet)
            raise
    creator_name = (await _rp_names([uid])).get(uid, "بازیکن")
    if not b.get("silent"):
      await _rp_say(f"{creator_name} یک میز بازی سم یا خوراکی ساخت\nمبلغ شرط: {bet:,} تومان\nجایزه برنده: {bet * 2:,} تومان\n۱۲۰ ثانیه فرصت پیوستن به این میز دارید.\n{{game:{gid}}}")
    return _j({"ok": True, "game_id": gid, "balance": await _mini_balance(uid)})


async def _social_poison_join(b, user):
    uid, _bal = await _mini_ctx(user)
    gid = _int(b.get("game_id"))
    if (left := _cd_left_uid(uid, "poison")) > 0:
        raise _ApiError(_cd_plain(left))
    async with _RP_LOCK:
        await _rp_sweep()
        g = await _rp_fetch(gid)
        if not g or g["phase"] != "lobby":
            raise _ApiError("این بازی دیگه فعال نیست.")
        if g["creator"] == uid:
            raise _ApiError("نمی‌تونی وارد بازی خودت بشی؛ منتظر حریف باش.")
        if await pool.fetchval(_rp_busy_sql(), uid):
            raise _ApiError("تو همین الان یه بازی سم یا خوراکی فعال داری.")
        if await _take(uid, int(g["bet"])) is None:
            raise _ApiError(f"برای ورود باید {int(g['bet']):,} تومن موجودی داشته باشی.")
        g.update(opponent=uid, phase="hide", deadline=time.time() + RP_TURN_SECS)
        try:
            await _rp_store(g)
        except Exception:
            await _give(uid, int(g["bet"]))
            raise
    _cd_set_uid(uid, "poison"); _cd_set_uid(int(g["creator"]), "poison")
    nm = await _rp_names([uid, g["creator"]])
    if not g.get("silent"):
      await _rp_say(f"⚔️ {nm.get(uid, 'یه بازیکن')} به بازی {nm.get(g['creator'], 'سازنده')} پیوست!\n💰 جایزه: {int(g['bet']) * 2:,} تومن — بازی شروع شد، تماشا کنید 👀")
    return _j({"ok": True, "balance": await _mini_balance(uid)})


async def _social_poison_cancel(b, user):
    uid = int(user["id"])
    gid = _int(b.get("game_id"))
    async with _RP_LOCK:
        await _rp_sweep()
        g = await _rp_fetch(gid)
        if not g or g["phase"] != "lobby":
            raise _ApiError("این بازی دیگه تو مرحله‌ی انتظار نیست.")
        if g["creator"] != uid:
            raise _ApiError("فقط سازنده می‌تونه بازی رو لغو کنه.", 403)
        await _rp_finish(g, None, "سازنده بازی رو لغو کرد؛ شرط برگشت.", say=False)
    return _j({"ok": True, "balance": await _mini_balance(uid)})


async def _social_poison_move(b, user):
    uid, _bal = await _mini_ctx(user)
    gid = _int(b.get("game_id"))
    cell = _int(b.get("cell"))
    if cell is None or not 0 <= cell < RP_CELLS:
        raise _ApiError("خانه نامعتبره")
    msg, done = "", False
    async with _RP_LOCK:
        await _rp_sweep()
        g = await _rp_fetch(gid)
        if not g:
            raise _ApiError("بازی پیدا نشد.", 404)
        if g["phase"] == "done":
            raise _ApiError(g.get("reason") or "این بازی تموم شده.")
        if g["phase"] == "lobby":
            raise _ApiError("هنوز حریف وارد نشده.")
        if uid not in (g["creator"], g["opponent"]):
            raise _ApiError("این بازی برای دو بازیکنشه.", 403)
        other = g["opponent"] if uid == g["creator"] else g["creator"]
        if g["phase"] == "hide":
            if uid in g["hidden"]:
                raise _ApiError("سمت رو قبلاً مخفی کردی؛ منتظر حریف باش.")
            g["hidden"][uid] = cell
            if len(g["hidden"]) == 2:
                g.update(phase="guess", turn=random.choice([g["creator"], g["opponent"]]), deadline=time.time() + RP_TURN_SECS)
                g["opened"] = []
                msg = "هر دو سم مخفی شد! بازی شروع شد."
            else:
                msg = "سمت مخفی شد! منتظر حریف…"
            await _rp_store(g)
        else:
            if g.get("turn") != uid:
                raise _ApiError("نوبت حریفه.")
            if cell in g["opened"]:
                raise _ApiError("این خانه قبلاً باز شده.")
            if cell == g["hidden"].get(uid):
                raise _ApiError("رو سم خودت نمی‌تونی بزنی!")
            if cell == g["hidden"].get(other):
                g["opened"].append(cell)
                await _rp_finish(g, other, "سم حریف پیدا شد!")
                done = True
                msg = "سم حریف رو پیدا کردی؛ باختی! ☠️"
            else:
                g["opened"].append(cell)
                g.update(turn=other, deadline=time.time() + RP_TURN_SECS)
                if not [i for i in range(RP_CELLS) if i not in g["opened"] and i != g["hidden"].get(other)]:
                    await _rp_finish(g, None, "خانه‌ی امنی نمونده؛ مساوی شد و شرط‌ها برگشت.")
                    done = True
                    msg = "مساوی شد."
                else:
                    await _rp_store(g)
                    msg = "خوراکی بود! 🍬 نوبت حریف."
    return _j({"ok": True, "msg": msg, "done": done, "balance": await _mini_balance(uid)})


# ───── بازی دونفره «خط و نشان» (کارام) داخل چت‌روم مینی‌اپ ─────
# سازنده شرط رو تعیین می‌کنه (پولش همون لحظه کم میشه) و منتظر حریف می‌مونه؛ نفر دوم همون مبلغ رو می‌ده.
# سازنده مهره‌های سفید (۹ تا) و حریف مهره‌های سیاه (۹ تا) داره، ملکه (قرمز) وسط میزه.
# فیزیک کامل سمت سرور شبیه‌سازی میشه (کلاینت فقط زاویه/قدرت/جای استرایکر می‌فرسته) پس تقلب ممکن نیست.
# هر نوبت ۱۲ ثانیه مهلت داره؛ سه بار پشت‌سرهم نوبت رو از دست بدی می‌بازی. برنده ۲ برابر شرط می‌گیره.
CR_W = 1000                 # میز مربعی ۱۰۰۰×۱۰۰۰ واحد
CR_R = 29                   # مهره‌ها کمی بزرگ‌تر برای لمس و دید بهتر
CR_SR = 31                  # شعاع استرایکر؛ بزرگ‌تر برای لمس راحت‌تر
CR_POCKET = 20              # فاصله‌ی مرکز جیب از گوشه
CR_CAP = 40                 # شعاع جذب جیب
CR_BASE_Y = (810.0, 190.0)  # خط شروع سازنده (پایین) / حریف (بالا)
CR_BASE_MIN, CR_BASE_MAX = 215.0, 785.0
CR_DT = 1.0 / 240.0
CR_REC = 8                  # هر ۸ گام یه فریم = ۳۰ فریم در ثانیه
CR_MAXT = 9.0
CR_DEC = 560.0
CR_DRAG = 0.45
CR_STOP = 14.0
CR_REST_W = 0.8
CR_REST_C = 0.92
CR_MASS_S = 1.5
CR_VMIN, CR_VMAX = 420.0, 2600.0
CR_TURN_SECS = 60
CR_LOBBY_SECS = 120
CR_DONE_SHOW = 0
CR_MAX_LOBBIES = 3
CR_MAX_SHOTS = 120
CR_MISS_LIMIT = 3
_CR_LOCK = asyncio.Lock()


def _cr_ids(side: str):
    return range(2, 11) if side == "w" else range(11, 20)


def _cr_initial() -> dict:
    """چیدمان اولیه: ملکه وسط، حلقه‌ی داخلی ۶ تایی، حلقه‌ی بیرونی ۱۲ تایی؛ رنگ‌ها یکی‌درمیان."""
    c = CR_W / 2
    g = 1.04
    pos = []
    for k in range(6):
        a = math.radians(90 + 60 * k)
        pos.append((a, 2 * CR_R * g))
    outer = []
    for k in range(6):
        a = math.radians(90 + 60 * k)
        outer.append((a, 4 * CR_R * g))
        outer.append((a + math.radians(30), 2 * math.sqrt(3) * CR_R * g))
    outer.sort(key=lambda t: t[0])
    coins = {1: [c, c]}
    nw, nb = 2, 11
    for idx, (a, r) in enumerate(pos + outer):
        white = idx % 2 == 0
        if idx >= 6:
            white = (idx - 6) % 2 == 0
        cid = nw if white else nb
        if white:
            nw += 1
        else:
            nb += 1
        coins[cid] = [round(c + r * math.cos(a), 1), round(c + r * math.sin(a), 1)]
    return coins


def _cr_sim(coins: dict, sx: float, sy: float, ang: float, power: float):
    """شبیه‌سازی یه ضربه. خروجی: مهره‌های باقی‌مونده، مهره‌های توی جیب، آیا استرایکر افتاد، فریم‌ها و رویدادها."""
    ids = [0] + sorted(coins)
    n = len(ids)
    x = [float(sx)] + [float(coins[i][0]) for i in ids[1:]]
    y = [float(sy)] + [float(coins[i][1]) for i in ids[1:]]
    v0 = CR_VMIN + (CR_VMAX - CR_VMIN) * power
    vx = [math.cos(ang) * v0] + [0.0] * (n - 1)
    vy = [math.sin(ang) * v0] + [0.0] * (n - 1)
    rad = [CR_SR] + [CR_R] * (n - 1)
    imass = [1.0 / CR_MASS_S] + [1.0] * (n - 1)
    alive = [True] * n
    events, frames = [], []
    P, W = CR_POCKET, CR_W
    pockets = ((P, P), (W - P, P), (P, W - P), (W - P, W - P))
    cap2 = CR_CAP * CR_CAP
    dt = CR_DT

    def snap():
        fr = []
        for i in range(n):
            fr.append(int(round(x[i])))
            fr.append(int(round(y[i])))
        frames.append(fr)

    snap()
    last_snap = 0
    steps = int(CR_MAXT / dt)
    step = 0
    for step in range(1, steps + 1):
        mv = [i for i in range(n) if alive[i] and (vx[i] or vy[i])]
        if not mv:
            break
        for i in mv:
            sp = math.hypot(vx[i], vy[i])
            ns = sp * (1.0 - CR_DRAG * dt) - CR_DEC * dt
            if ns < CR_STOP:
                vx[i] = vy[i] = 0.0
                continue
            k = ns / sp
            vx[i] *= k
            vy[i] *= k
            x[i] += vx[i] * dt
            y[i] += vy[i] * dt
            r = rad[i]
            if x[i] < r:
                x[i] = r
                vx[i] = abs(vx[i]) * CR_REST_W
            elif x[i] > W - r:
                x[i] = W - r
                vx[i] = -abs(vx[i]) * CR_REST_W
            if y[i] < r:
                y[i] = r
                vy[i] = abs(vy[i]) * CR_REST_W
            elif y[i] > W - r:
                y[i] = W - r
                vy[i] = -abs(vy[i]) * CR_REST_W
            for ci, (px, py) in enumerate(pockets):
                if (x[i] - px) ** 2 + (y[i] - py) ** 2 < cap2:
                    alive[i] = False
                    x[i], y[i] = float(px), float(py)
                    vx[i] = vy[i] = 0.0
                    events.append([len(frames), ids[i], ci])
                    break
        mvset = set(mv)
        for i in mv:
            if not alive[i]:
                continue
            for j in range(n):
                if j == i or not alive[j] or (j in mvset and j < i):
                    continue
                dx = x[j] - x[i]
                dy = y[j] - y[i]
                rr = rad[i] + rad[j]
                d2 = dx * dx + dy * dy
                if d2 >= rr * rr:
                    continue
                d = math.sqrt(d2)
                if d < 1e-6:
                    dx, dy, d = 1.0, 0.0, 1.0
                nx, ny = dx / d, dy / d
                im = imass[i] + imass[j]
                ov = rr - d
                x[i] -= nx * ov * imass[i] / im
                y[i] -= ny * ov * imass[i] / im
                x[j] += nx * ov * imass[j] / im
                y[j] += ny * ov * imass[j] / im
                rv = (vx[j] - vx[i]) * nx + (vy[j] - vy[i]) * ny
                if rv < 0:
                    jj = -(1.0 + CR_REST_C) * rv / im
                    vx[i] -= jj * imass[i] * nx
                    vy[i] -= jj * imass[i] * ny
                    vx[j] += jj * imass[j] * nx
                    vy[j] += jj * imass[j] * ny
        if step % CR_REC == 0:
            snap()
            last_snap = step
    else:
        for i in range(n):
            vx[i] = vy[i] = 0.0
    if last_snap != step or len(frames) < 2:
        snap()
    final, pocketed = {}, []
    for i in range(1, n):
        if alive[i]:
            final[ids[i]] = [round(x[i], 1), round(y[i], 1)]
        else:
            pocketed.append(ids[i])
    return {"final": final, "pocketed": pocketed, "striker_in": not alive[0], "ids": ids, "frames": frames, "ev": events}


def _cr_place(coins: dict, cid: int):
    """مهره رو (مثلاً ملکه یا مهره‌ی جریمه) وسط میز یا نزدیک‌ترین جای خالی برمی‌گردونه."""
    c = CR_W / 2
    gap = 2 * CR_R + 2
    cand = [(c, c)]
    for ring in range(1, 8):
        for k in range(12 * ring):
            a = 2 * math.pi * k / (12 * ring)
            cand.append((c + ring * gap * 0.9 * math.cos(a), c + ring * gap * 0.9 * math.sin(a)))
    for px, py in cand:
        if all((px - o[0]) ** 2 + (py - o[1]) ** 2 >= gap * gap for k, o in coins.items() if k != cid):
            coins[cid] = [round(px, 1), round(py, 1)]
            return
    coins[cid] = [c, c]


def _cr_load(r) -> dict:
    g = dict(r)
    try:
        st = json.loads(g.get("state") or "{}")
    except Exception:
        st = {}
    g["coins"] = {int(k): [float(v[0]), float(v[1])] for k, v in (st.get("coins") or {}).items()}
    g["out"] = [int(i) for i in (st.get("out") or [])]
    g["qown"] = st.get("qown")
    g["qpend"] = st.get("qpend")
    g["seq"] = int(st.get("seq") or 0)
    g["miss"] = {int(k): int(v) for k, v in (st.get("miss") or {}).items()}
    g["shots"] = int(st.get("shots") or 0)
    g["last"] = st.get("last") or {}
    g["ready_at"] = float(st.get("ready_at") or 0)
    return g


def _cr_pack(g: dict) -> str:
    return json.dumps({"coins": {str(k): v for k, v in g["coins"].items()}, "out": g["out"], "qown": g.get("qown"),
                       "qpend": g.get("qpend"), "seq": g.get("seq", 0), "miss": {str(k): v for k, v in g["miss"].items()},
                       "shots": g.get("shots", 0), "last": g.get("last") or {}, "ready_at": g.get("ready_at", 0)})


async def _cr_fetch(gid):
    if gid is None:
        return None
    r = await pool.fetchrow("SELECT * FROM room_carrom_games WHERE game_id=$1", gid)
    return _cr_load(r) if r else None


async def _cr_store(g: dict):
    await pool.execute(
        "UPDATE room_carrom_games SET opponent=$2, phase=$3, turn=$4, deadline=$5, winner=$6, reason=$7, state=$8, finished_at=$9 WHERE game_id=$1",
        g["game_id"], g.get("opponent"), g["phase"], g.get("turn"), g.get("deadline"), g.get("winner"), g.get("reason"),
        _cr_pack(g), g.get("finished_at"))


async def _cr_finish(g: dict, winner, reason: str, say: bool = True):
    """پایان بازی. winner=None یعنی مساوی/لغو و شرط‌ها برمی‌گرده؛ وگرنه برنده کل جایزه رو می‌گیره."""
    if g["phase"] == "done":
        return
    g.update(phase="done", winner=winner, reason=reason, turn=None, deadline=None, finished_at=time.time())
    bet = int(g["bet"])
    if winner is None:
        await _give(g["creator"], bet)
        if g.get("opponent"):
            await _give(g["opponent"], bet)
    else:
        await _give(winner, bet * 2)
    await _cr_store(g)
    if say and not g.get("silent"):
        nm = await _rp_names([g["creator"], g.get("opponent")])
        a, b = nm.get(g["creator"], "بازیکن"), nm.get(g.get("opponent"), "بازیکن")
        sw = sum(1 for i in g["out"] if i in _cr_ids("w"))
        sb = sum(1 for i in g["out"] if i in _cr_ids("b"))
        if winner is not None:
            win = a if winner == g["creator"] else b
            await _rp_say(f"🏆 {win} برنده‌ی «خط و نشان» شد!\n🎯 {a} ({sw} مهره) در برابر {b} ({sb} مهره)\n📌 {reason}\n💰 جایزه: {bet * 2:,} تومن به حسابش رفت 🎉")
        elif g.get("opponent"):
            await _rp_say(f"🤝 بازی «خط و نشان» بین {a} و {b} مساوی شد؛ شرط {bet:,} تومنی به هر دو برگشت.")


async def _cr_tick(g: dict):
    now = time.time()
    if g["phase"] == "lobby":
        if now - float(g["created_at"]) > CR_LOBBY_SECS:
            await _cr_finish(g, None, "کسی وارد نشد؛ شرط به سازنده برگشت.", say=False)
        return
    if g["phase"] != "play":
        return
    changed = False
    while g["phase"] == "play" and g.get("deadline") and now > g["deadline"]:
        loser = g["turn"]
        other = g["opponent"] if loser == g["creator"] else g["creator"]
        g["miss"][loser] = g["miss"].get(loser, 0) + 1
        if g["miss"][loser] >= CR_MISS_LIMIT:
            if g["miss"].get(other, 0) >= CR_MISS_LIMIT - 1:
                await _cr_finish(g, None, "هیچ‌کدوم بازی نکردن؛ شرط‌ها برگشت.")
            else:
                await _cr_finish(g, other, f"حریف {CR_MISS_LIMIT} بار پشت‌سرهم نوبتش رو از دست داد.")
            return
        if g.get("qpend") == loser:
            _cr_place(g["coins"], 1)
            g["qpend"] = None
        g["last"] = {"by": loser, "timeout": True}
        g["turn"] = other
        g["deadline"] = float(g["deadline"]) + CR_TURN_SECS
        g["ready_at"] = 0
        changed = True
    if changed:
        await _cr_store(g)


async def _cr_sweep() -> list:
    """همه‌ی بازی‌های باز رو می‌گیره و مهلت‌های تموم‌شده رو تکلیف می‌کنه (باید زیر _CR_LOCK صدا زده بشه)."""
    out = []
    for r in await pool.fetch("SELECT * FROM room_carrom_games WHERE phase<>'done' ORDER BY game_id"):
        g = _cr_load(r)
        await _cr_tick(g)
        if g["phase"] != "done":
            out.append(g)
    return out


def _cr_view(g: dict, uid: int, names: dict, now: float, shot=None) -> dict:
    mine = uid in (g["creator"], g.get("opponent"))
    left = None
    if g["phase"] == "lobby":
        left = max(0, int(CR_LOBBY_SECS - (now - float(g["created_at"]))))
    elif g.get("deadline"):
        left = max(0.0, round(float(g["deadline"]) - now, 2))
    d = {"id": g["game_id"], "creator": g["creator"], "creator_name": names.get(g["creator"], "بازیکن"),
         "opponent": g.get("opponent"), "opponent_name": names.get(g.get("opponent"), "") if g.get("opponent") else "",
         "bet": int(g["bet"]), "pot": int(g["bet"]) * 2, "phase": g["phase"], "turn": g.get("turn"), "left": left,
         "me": mine, "winner": g.get("winner"), "reason": g.get("reason") or "", "seq": g["seq"], "secs": CR_TURN_SECS,
         "ready_in": max(0.0, round(g["ready_at"] - now, 2)) if g.get("ready_at") else 0,
         "coins": [[k, v[0], v[1]] for k, v in sorted(g["coins"].items())], "out": g["out"],
         "qown": g.get("qown"), "qpend": g.get("qpend"), "last": g.get("last") or {},
         "miss": g["miss"].get(uid, 0) if mine else 0}
    if shot:
        d["shot"] = shot
    return d


async def _cr_games_for(uid: int, seen: dict, only_ids=None) -> list:
    async with _CR_LOCK:
        games = await _cr_sweep()
        recent = []  # بازی‌های تمام‌شده دیگر در بالای چت‌روم باقی نمی‌مانند.
        games += [_cr_load(r) for r in recent]
    names = await _rp_names([x for g in games for x in (g["creator"], g.get("opponent"))])
    now = time.time()
    shots = {}
    want = [g["game_id"] for g in games if g["game_id"] in seen and g["seq"] > seen[g["game_id"]]]
    if want:
        for r in await pool.fetch("SELECT game_id, seq, data FROM room_carrom_shots WHERE game_id = ANY($1::bigint[])", want):
            try:
                sh = json.loads(r["data"])
                sh["seq"] = int(r["seq"])
                shots[int(r["game_id"])] = sh
            except Exception:
                pass
    views = []
    for g in games:
        sh = shots.get(g["game_id"])
        if sh and sh["seq"] != g["seq"]:
            sh = None
        views.append(_cr_view(g, uid, names, now, sh))
    subs = await _mini_sub_set([x for g in games for x in (g["creator"], g.get("opponent"))])
    for v in views:
        v["creator_prem"] = v["creator"] in subs
        v["opponent_prem"] = bool(v["opponent"]) and v["opponent"] in subs
    views.sort(key=lambda v: (not v["me"], -v["id"]))
    return views


def _cr_parse_seen(s) -> dict:
    out = {}
    for part in str(s or "").split(","):
        if ":" in part:
            a, b = part.split(":", 1)
            try:
                out[int(a)] = int(b)
            except ValueError:
                pass
    return out


async def _social_carrom_state(qs, user):
    uid = int(user["id"])
    views = await _cr_games_for(uid, _cr_parse_seen(qs.get("seen")))
    return _j({"games": views, "balance": await _mini_balance(uid), "min_bet": CASINO_MIN_BET, "max_bet": CASINO_MAX_BET})


def _cr_busy_sql() -> str:
    return "SELECT 1 FROM room_carrom_games WHERE phase<>'done' AND (creator=$1 OR opponent=$1)"


async def _social_carrom_create(b, user):
    uid, _bal = await _mini_ctx(user)
    try:
        bet = int(float(str(b.get("bet")).replace(",", "").strip()))
    except (TypeError, ValueError):
        raise _ApiError("مبلغ شرط نامعتبره")
    if bet < CASINO_MIN_BET:
        raise _ApiError(f"حداقل شرط {CASINO_MIN_BET:,} تومنه.")
    if bet > CASINO_MAX_BET:
        raise _ApiError(f"حداکثر شرط {CASINO_MAX_BET:,} تومنه.")
    async with _ROOM_TABLE_CREATE_LOCK, _RP_LOCK, _CR_LOCK:
        await _rp_sweep()
        await _cr_sweep()
        if await pool.fetchval(_cr_busy_sql(), uid) or await pool.fetchval(_rp_busy_sql(), uid):
            raise _ApiError("تو همین الان یه بازی فعال داری.")
        active_tables = int(await pool.fetchval("SELECT (SELECT count(*) FROM room_poison_games WHERE phase<>'done') + (SELECT count(*) FROM room_carrom_games WHERE phase<>'done')") or 0)
        if active_tables >= _ROOM_TABLE_MAX_ACTIVE:
            raise _ApiError("ظرفیت چت‌روم پره؛ حداکثر ۳ میز می‌تونه هم‌زمان فعال باشه. بعد از پایان یا انقضای یکی از میزها دوباره تلاش کن.")
        if await _take(uid, bet) is None:
            raise _ApiError("موجودی کافی نیست.")
        try:
            st = json.dumps({"coins": {str(k): v for k, v in _cr_initial().items()}, "out": [], "seq": 0})
            gid = await pool.fetchval(
                "INSERT INTO room_carrom_games(creator,bet,phase,state,created_at,silent) VALUES($1,$2,'lobby',$3,$4,$5) RETURNING game_id",
                uid, bet, st, time.time(), bool(b.get("silent")))
        except Exception:
            await _give(uid, bet)
            raise
    creator_name = (await _rp_names([uid])).get(uid, "بازیکن")
    if not b.get("silent"):
      await _rp_say(f"{creator_name} یک میز بازی خط و نشان ساخت\nمبلغ شرط: {bet:,} تومان\nجایزه برنده: {bet * 2:,} تومان\n۱۲۰ ثانیه فرصت پیوستن به این میز دارید.\n{{carrom:{gid}}}")
    return _j({"ok": True, "game_id": gid, "balance": await _mini_balance(uid)})


async def _social_carrom_join(b, user):
    uid, _bal = await _mini_ctx(user)
    gid = _int(b.get("game_id"))
    async with _CR_LOCK:
        await _cr_sweep()
        g = await _cr_fetch(gid)
        if not g or g["phase"] != "lobby":
            raise _ApiError("این بازی دیگه فعال نیست.")
        if g["creator"] == uid:
            raise _ApiError("نمی‌تونی وارد بازی خودت بشی؛ منتظر حریف باش.")
        if await pool.fetchval(_cr_busy_sql(), uid):
            raise _ApiError("تو همین الان یه بازی خط و نشان فعال داری.")
        if await _take(uid, int(g["bet"])) is None:
            raise _ApiError(f"برای ورود باید {int(g['bet']):,} تومن موجودی داشته باشی.")
        now = time.time()
        g.update(opponent=uid, phase="play", turn=random.choice([g["creator"], uid]),
                 deadline=now + 3 + CR_TURN_SECS, ready_at=now + 3)
        g["coins"] = _cr_initial()
        g["out"], g["qown"], g["qpend"], g["seq"], g["miss"], g["shots"], g["last"] = [], None, None, 0, {}, 0, {}
        try:
            await _cr_store(g)
        except Exception:
            await _give(uid, int(g["bet"]))
            raise
    nm = await _rp_names([uid, g["creator"]])
    if not g.get("silent"):
      await _rp_say(f"⚔️ {nm.get(uid, 'یه بازیکن')} به بازی «خط و نشان» {nm.get(g['creator'], 'سازنده')} پیوست!\n💰 جایزه: {int(g['bet']) * 2:,} تومن — بازی شروع شد، تماشا کنید 👀")
    return _j({"ok": True, "balance": await _mini_balance(uid)})


async def _social_carrom_cancel(b, user):
    uid = int(user["id"])
    gid = _int(b.get("game_id"))
    async with _CR_LOCK:
        await _cr_sweep()
        g = await _cr_fetch(gid)
        if not g or g["phase"] != "lobby":
            raise _ApiError("این بازی دیگه تو مرحله‌ی انتظار نیست.")
        if g["creator"] != uid:
            raise _ApiError("فقط سازنده می‌تونه بازی رو لغو کنه.", 403)
        await _cr_finish(g, None, "سازنده بازی رو لغو کرد؛ شرط برگشت.", say=False)
    return _j({"ok": True, "balance": await _mini_balance(uid)})


def _cr_resolve(g: dict, uid: int, res: dict):
    """قانون‌های بازی بعد از یه ضربه: امتیاز، ملکه، خطا، نوبت بعدی و برنده. (winner, reason, finished) برمی‌گردونه."""
    other = g["opponent"] if uid == g["creator"] else g["creator"]
    mine_side = "w" if uid == g["creator"] else "b"
    oth_side = "b" if mine_side == "w" else "w"
    coins = res["final"]
    g["coins"] = {k: list(v) for k, v in coins.items()}
    pk = res["pocketed"]
    own = [i for i in pk if i in _cr_ids(mine_side)]
    opp = [i for i in pk if i in _cr_ids(oth_side)]
    qin = 1 in pk
    for i in pk:
        if i != 1:
            g["out"].append(i)
    info = {"by": uid, "own": len(own), "opp": len(opp), "queen": None, "foul": False}
    extra = False
    if res["striker_in"]:
        info["foul"] = True
        if qin:
            _cr_place(g["coins"], 1)
            info["queen"] = "back"
        if g.get("qpend") == uid:
            _cr_place(g["coins"], 1)
            g["qpend"] = None
            info["queen"] = "back"
        back = [i for i in g["out"] if i in _cr_ids(mine_side) and i not in own]
        if back:
            g["out"].remove(back[-1])
            _cr_place(g["coins"], back[-1])
            info["returned"] = 1
    else:
        if g.get("qpend") == uid:
            if own:
                g["qown"], g["qpend"] = uid, None
                info["queen"] = "won"
            else:
                _cr_place(g["coins"], 1)
                g["qpend"] = None
                info["queen"] = "back"
        if qin:
            if own:
                g["qown"] = uid
                info["queen"] = "won"
            else:
                g["qpend"] = uid
                info["queen"] = "pending"
        extra = bool(own) or (info["queen"] == "pending")
    winner, reason = None, ""
    for side, owner in ((mine_side, uid), (oth_side, other)):
        got = [i for i in g["out"] if i in _cr_ids(side)]
        if len(got) == 9:
            if g.get("qown") is None:
                pref = [i for i in pk if i in _cr_ids(side)] or got
                g["out"].remove(pref[-1])
                _cr_place(g["coins"], pref[-1])
                info["last_back"] = True
            elif winner is None:
                winner = owner
                reason = "همه‌ی مهره‌هاش رو توی جیب انداخت!"
    g["shots"] = g.get("shots", 0) + 1
    finished = winner is not None
    if not finished and g["shots"] >= CR_MAX_SHOTS:
        sw = sum(1 for i in g["out"] if i in _cr_ids("w"))
        sb = sum(1 for i in g["out"] if i in _cr_ids("b"))
        finished = True
        if sw != sb:
            winner = g["creator"] if sw > sb else g["opponent"]
            reason = "بازی به سقف ضربه‌ها رسید؛ برنده کسیه که مهره‌ی بیشتری انداخته."
        else:
            reason = "بازی به سقف ضربه‌ها رسید و مساوی شد."
    g["last"] = info
    if not finished:
        g["miss"][uid] = 0
        g["turn"] = uid if extra else other
    return winner, reason, finished


async def _social_carrom_shoot(b, user):
    uid, _bal = await _mini_ctx(user)
    gid = _int(b.get("game_id"))
    try:
        sx = float(b.get("x"))
        ang = float(b.get("angle"))
        power = float(b.get("power"))
    except (TypeError, ValueError):
        raise _ApiError("اطلاعات ضربه نامعتبره")
    if not all(math.isfinite(v) for v in (sx, ang, power)):
        raise _ApiError("اطلاعات ضربه نامعتبره")
    power = min(1.0, max(0.0, power))
    sx = min(CR_BASE_MAX, max(CR_BASE_MIN, sx))
    async with _CR_LOCK:
        await _cr_sweep()
        g = await _cr_fetch(gid)
        if not g:
            raise _ApiError("بازی پیدا نشد.", 404)
        if g["phase"] == "done":
            raise _ApiError(g.get("reason") or "این بازی تموم شده.")
        if g["phase"] != "play":
            raise _ApiError("هنوز حریف وارد نشده.")
        if uid not in (g["creator"], g["opponent"]):
            raise _ApiError("این بازی برای دو بازیکنشه.", 403)
        if g.get("turn") != uid:
            raise _ApiError("نوبت حریفه.")
        now = time.time()
        if now < g["ready_at"]:
            raise _ApiError("صبر کن تا ضربه‌ی قبلی تموم بشه.")
        sy = CR_BASE_Y[0] if uid == g["creator"] else CR_BASE_Y[1]
        for o in g["coins"].values():
            if (o[0] - sx) ** 2 + (o[1] - sy) ** 2 < (CR_R + CR_SR - 1) ** 2:
                raise _ApiError("استرایکر روی یه مهره‌ست؛ جاش رو عوض کن.")
        seq_before = g["seq"]
        res = await asyncio.to_thread(_cr_sim, g["coins"], sx, sy, ang, power)
        winner, reason, finished = _cr_resolve(g, uid, res)
        dur = len(res["frames"]) / 30.0
        now = time.time()
        g["seq"] = seq_before + 1
        g["ready_at"] = now + dur + 0.5
        if g["phase"] == "play" and not finished:
            g["deadline"] = now + dur + 0.5 + CR_TURN_SECS
        await pool.execute(
            "INSERT INTO room_carrom_shots(game_id,seq,data) VALUES($1,$2,$3) ON CONFLICT (game_id) DO UPDATE SET seq=$2, data=$3",
            g["game_id"], g["seq"], json.dumps({"by": uid, "ids": res["ids"], "frames": res["frames"], "ev": res["ev"], "striker_in": res["striker_in"]}))
        if finished:
            await _cr_finish(g, winner, reason)
        else:
            await _cr_store(g)
    views = await _cr_games_for(uid, {gid: seq_before})
    mine = next((v for v in views if v["id"] == gid), None)
    return _j({"ok": True, "game": mine, "done": bool(finished), "balance": await _mini_balance(uid)})


async def _myself_cars(uid):
    out = []
    for i, car in (await _owned_cars(uid)).items():
        i = int(i)
        parts, costs = {}, {}
        for k, (_l, _ic, col) in CAR_PARTS.items():
            lv = int(car[col] or 0)
            parts[k] = lv
            costs[k] = car_upgrade_cost(i, lv) if lv < CAR_MAX_LEVEL else None
        out.append({"idx": i, "name": CARS[i][0], "emoji": CARS[i][2], "color": int(car["color"] or 0),
                    "level": int(car["level"] or 1), "pending": int(car["pending_profit"] or 0),
                    "hourly": car_profit(i, car), "parts": parts, "costs": costs})
    return out


