def _special_img(key: str, gender: str) -> bytes:
    p = Path(__file__).resolve().parent / "special_images" / f"{key}.jpg"
    if p.exists():
        return p.read_bytes()
    if key in _SPECIAL_IMG2:
        return base64.b64decode(_SPECIAL_IMG2[key])
    return base64.b64decode(_SPECIAL_IMG["f" if gender == "f" else "m"])


async def special_current(uid: int):
    """کلید کاراکتر ویژه‌ی فعال کاربر یا None."""
    try:
        return await pool.fetchval("SELECT key FROM special_chars WHERE user_id=$1 AND active LIMIT 1", uid)
    except Exception:
        return None


async def special_active(uid: int) -> bool:
    return bool(await special_current(uid))


async def special_key_active(uid: int, key) -> bool:
    keys = (key,) if isinstance(key, str) else tuple(key)
    return (await special_current(uid)) in keys


async def _special_gender(uid: int) -> str:
    g = await pool.fetchval("SELECT gender FROM users WHERE user_id=$1", uid)
    return g if g in ("m", "f") else "m"


def _special_allowed(key: str, gender: str) -> bool:
    sp = SPECIALS.get(key)
    return bool(sp) and sp["gender"] in (None, gender)


async def _g_myself_special(qs, user):
    uid = int(user["id"]); gender = await _special_gender(uid)
    rows = await pool.fetch("SELECT key,active FROM special_chars WHERE user_id=$1", uid)
    owned = {r["key"]: bool(r["active"]) for r in rows}
    items = [{"key": k, "name": v["name"], "power": v["power"] + " " + SPECIAL_COMMON, "price": v["price"],
              "owned": k in owned, "active": owned.get(k, False), "image": f"/api/myself/special-img?k={k}&g={gender}"}
             for k, v in SPECIALS.items() if _special_allowed(k, gender)]
    return _j({"items": items, "owned_any": bool(owned) and SPECIAL_ONE_ONLY})


async def _g_myself_special_img(qs, user):
    gender = await _special_gender(int(user["id"]))
    key = str(qs.get("k") or SPECIAL_KEY)
    if not _special_allowed(key, gender):
        return 404, "text/plain", b"not found", {}
    return 200, "image/jpeg", _special_img(key, gender), {"Cache-Control": "private, max-age=3600"}


async def _p_myself_special_buy(b, user):
    uid = int(user["id"]); key = str(b.get("key") or SPECIAL_KEY)
    gender = await _special_gender(uid)
    if not _special_allowed(key, gender):
        raise _ApiError("این کاراکتر برای تو در دسترس نیست.")
    price = int(SPECIALS[key]["price"])
    async with pool.acquire() as c:
        async with c.transaction():
            r = await c.fetchrow("SELECT balance,bank_balance FROM users WHERE user_id=$1 FOR UPDATE", uid)
            if not r:
                raise _ApiError("حساب پیدا نشد")
            if await c.fetchval("SELECT 1 FROM special_chars WHERE user_id=$1 AND key=$2", uid, key):
                raise _ApiError("این کاراکتر رو قبلاً خریدی.")
            if SPECIAL_ONE_ONLY and await c.fetchval("SELECT 1 FROM special_chars WHERE user_id=$1", uid):
                raise _ApiError("هر نفر فقط می‌تونه یه کاراکتر ویژه داشته باشه؛ دو اسکین نمی‌شه خرید.")
            pocket, bank = int(r["balance"] or 0), int(r["bank_balance"] or 0)
            if pocket + bank < price:
                raise _ApiError(f"موجودی کافی نیست؛ قیمت {price:,} تومان (جیب + بانک).")
            from_pocket = min(pocket, price); from_bank = price - from_pocket
            await c.execute("UPDATE users SET balance=balance-$1, bank_balance=bank_balance-$2 WHERE user_id=$3", from_pocket, from_bank, uid)
            await c.execute("UPDATE special_chars SET active=FALSE WHERE user_id=$1", uid)   # فقط یکی فعال بمونه
            await c.execute("INSERT INTO special_chars(user_id,key,active,bought_at) VALUES($1,$2,TRUE,$3)", uid, key, time.time())
    return _j({"ok": True, "owned": True, "active": True})


async def _p_myself_special_toggle(b, user):
    uid = int(user["id"]); key = str(b.get("key") or SPECIAL_KEY)
    async with pool.acquire() as c:
        async with c.transaction():
            cur = await c.fetchrow("SELECT active FROM special_chars WHERE user_id=$1 AND key=$2 FOR UPDATE", uid, key)
            if not cur:
                raise _ApiError("اول باید این کاراکتر رو بخری.")
            new_active = not bool(cur["active"])
            if new_active:   # فعال‌کردن یکی، بقیه رو غیرفعال می‌کنه
                await c.execute("UPDATE special_chars SET active=FALSE WHERE user_id=$1", uid)
            await c.execute("UPDATE special_chars SET active=$3 WHERE user_id=$1 AND key=$2", uid, key, new_active)
    return _j({"ok": True, "active": new_active})


async def _g_giveaway_referrals(qs, user):
    uid=int(user["id"])
    rows=await pool.fetch(
        "SELECT g.id,g.name,g.prize,g.ends_at,e.user_id,e.inviter_id,e.status,e.joined_at,u.name AS user_name "
        "FROM giveaways g JOIN giveaway_entries e ON e.gid=g.id "
        "LEFT JOIN users u ON u.user_id=e.user_id "
        "WHERE g.status='active' AND e.inviter_id IS NOT NULL "
        "ORDER BY g.ends_at DESC,e.joined_at DESC LIMIT 1000")
    out=[]
    for r in rows:
        out.append({"giveaway_id":r["id"],"giveaway":r["name"],"prize":r["prize"],
                    "ends_at":r["ends_at"],"user_id":r["user_id"],"user_name":r["user_name"] or "کاربر",
                    "inviter_id":r["inviter_id"],"status":r["status"],
                    "user_link":f"tg://user?id={r['user_id']}","inviter_link":f"tg://user?id={r['inviter_id']}"})
    return _j(out)

# ───────────── بازی‌های مینی‌اپ: موشک و مین با شرط واقعی (همه‌چیز سمت سرور حساب میشه) ─────────────
MINI_MIN_BET = 50_000          # حداقل شرط موشک و مین مینی‌اپ (تومن)
MINI_CRASH_RATE = 0.12         # ضریب = e^(RATE × ثانیه)؛ از x1.00 شروع میشه
MINI_CRASH_EDGE = 0.88         # بخش اصلی توزیع انفجار؛ پایین‌تر = سخت‌تر
MINI_CRASH_EARLY = 0.38        # احتمال برخورد ناگهانی با شهاب‌سنگ در ضریب پایین (x1.00 تا x1.19)
MINI_CRASH_MAX = 100.0
MINI_CRASH_DELAY = 10.0        # ۱۰ ثانیه فرصت ثبت شرط پیش از پرواز
MINI_MINES_CELLS = 25          # دقیقاً مثل خودِ ربات (MINES_CELLS)
MINI_MINES_COUNT = 3           # دقیقاً مثل خودِ ربات (MINES_COUNT)
MINI_MINES_MAXMULT = 3.05      # ضریب خانه‌ی امن هجدهم؛ بهش برسه خودکار برداشت میشه
_MINI_LOCKS: dict[int, asyncio.Lock] = {}
_MINI_HIST: list[float] = []   # آخرین نقطه‌های انفجار موشک (کل بازیکنا)


def _mini_lock(uid: int) -> asyncio.Lock:
    return _MINI_LOCKS.setdefault(uid, asyncio.Lock())


def _mini_crash_point() -> float:
    if random.random() < MINI_CRASH_EARLY:
        return round(random.uniform(1.0, 1.19), 2)
    u = max(random.random(), 1e-9)
    return max(1.0, min(3.25, MINI_CRASH_MAX, math.floor(100 * MINI_CRASH_EDGE / u) / 100))


def _mini_mult_at(t: float) -> float:
    return 1.0 if t <= 0 else max(1.0, math.floor(math.exp(MINI_CRASH_RATE * t) * 100) / 100)


def _mini_time_for(m: float) -> float:
    return math.log(max(m, 1.0)) / MINI_CRASH_RATE


def _mini_mines_mult(k: int) -> float:
    """همون ضریب پلکانی خودِ ربات (mines_multiplier): ۳ مین تو ۲۱ خونه، تا ۳٫۰۵× تو خانه‌ی امن هجدهم."""
    if k <= 0:
        return 1.0
    return round(1.0 + 2.05 * (k / (MINI_MINES_CELLS - MINI_MINES_COUNT)), 2)


_MINI_HIST_LOADED = False
_MINI_CRASH_ROUNDS: dict = {}   # round_id -> {uid: {name, bet, target, res, m}}؛ فقط برای نمایش لیست بازیکنان پرواز


def _mini_crash_register(round_id: int, uid: int, name: str, bet: int, target):
    _MINI_CRASH_ROUNDS.setdefault(round_id, {})[uid] = {"name": name, "bet": bet, "target": target, "res": None, "m": None}
    for k in sorted(_MINI_CRASH_ROUNDS)[:-8]:
        _MINI_CRASH_ROUNDS.pop(k, None)


async def _mini_crash_players(rid, t0, cp, now) -> list:
    """بازیکنان یک دور موشک با وضعیت لحظه‌ای‌شان (در پرواز / برداشت کرده / منفجر شده). نقطه انفجار فقط بعد از وقوع لو می‌ره."""
    if rid is None:
        return []
    rec = dict(_MINI_CRASH_ROUNDS.get(rid) or {})
    try:
        rows = await pool.fetch(
            "SELECT g.uid, g.bet, g.state, u.name FROM mini_games g LEFT JOIN users u ON u.user_id=g.uid "
            "WHERE g.kind='crash' AND (g.state::json->>'round_id')::bigint=$1", int(rid))
    except Exception:
        rows = []
    for r in rows:
        uid = int(r["uid"])
        if uid in rec:
            continue
        try:
            s = json.loads(r["state"]) if isinstance(r["state"], str) else dict(r["state"])
        except Exception:
            s = {}
        rec[uid] = {"name": r["name"] or "کاربر", "bet": int(r["bet"]), "target": s.get("target"), "res": None, "m": None}
    started = now >= t0
    el = max(0.0, now - t0)
    out = []
    for uid, p in rec.items():
        tgt = p.get("target")
        st_, m = "fly", (_mini_mult_at(el) if started else 1.0)
        if p["res"] == "win":
            st_, m = "won", float(p["m"])
        elif p["res"] == "crash":
            st_, m = "lost", float(p["m"])
        elif cp is not None and started:
            if tgt and tgt <= cp and el >= _mini_time_for(tgt):
                st_, m = "won", float(tgt)
            elif el >= _mini_time_for(cp):
                st_, m = "lost", float(cp)
        out.append({"uid": uid, "name": p["name"], "bet": p["bet"], "mult": m, "state": st_})
    out.sort(key=lambda x: -x["bet"])
    return out[:30]


async def _mini_hist_ensure():
    """بعد از ری‌استارت ربات، آخرین پروازها از دیتابیس برگردن (قبلاً با هر دیپلوی پاک می‌شدن)."""
    return   # سوابق حالا توسط mini_crash_round_loop از جدول دورها ساخته می‌شه
    global _MINI_HIST_LOADED
    if _MINI_HIST_LOADED:
        return
    _MINI_HIST_LOADED = True
    try:
        rows = await pool.fetch("SELECT point FROM mini_crash_hist ORDER BY id DESC LIMIT 30")
        if rows and not _MINI_HIST:
            _MINI_HIST[:] = [float(r["point"]) for r in rows]
    except Exception:
        log.debug("mini crash hist load failed", exc_info=True)


async def _mini_ctx(user):
    await _mini_hist_ensure()
    uid = int(user["id"])
    if BANNED.get(uid, 0) > time.time():
        raise _ApiError("حسابت محروم شده.", 403)
    r = await pool.fetchrow("SELECT balance FROM users WHERE user_id=$1", uid)
    if not r:
        raise _ApiError("اول ربات رو استارت کن تا حسابت ساخته بشه")
    return uid, int(r["balance"] or 0)


async def _mini_balance(uid: int) -> int:
    return int(await pool.fetchval("SELECT balance FROM users WHERE user_id=$1", uid) or 0)


def _mini_bet(b) -> int:
    try:
        bet = int(float(str(b.get("bet")).replace(",", "").strip()))
    except (TypeError, ValueError):
        raise _ApiError("مبلغ شرط نامعتبره")
    if bet < MINI_MIN_BET:
        raise _ApiError(f"حداقل شرط {MINI_MIN_BET:,} تومنه.")
    if bet > CASINO_MAX_BET:
        raise _ApiError(f"حداکثر شرط {CASINO_MAX_BET:,} تومنه.")
    return bet


def _mini_base(bal: int) -> dict:
    return {"balance": bal, "min_bet": MINI_MIN_BET, "max_bet": CASINO_MAX_BET, "hist": _MINI_HIST[:14]}


# ───── موشک ─────
def _mini_crash_eval(st: dict, manual: bool):
    """('win'|'crash'|'run', ضریب). خروج خودکار روی ضریب هدف هم همین‌جا (به‌صورت lazy) حساب میشه."""
    el = max(0.0, time.time() - st["t0"])
    cp, tgt = st["crash"], st.get("target")
    if tgt and tgt <= cp and el >= _mini_time_for(tgt):
        return "win", float(tgt)
    if el >= _mini_time_for(cp):
        return "crash", cp
    if manual:
        return "win", min(_mini_mult_at(el), cp)
    return "run", _mini_mult_at(el)


async def _mini_crash_finish(uid: int, bet: int, st: dict, res: str, m: float) -> dict:
    win = res == "win"
    await pool.execute("DELETE FROM mini_games WHERE uid=$1", uid)
    payout = int(bet * m + 1e-6) if win else 0
    if payout > 0:
        await _give(uid, payout)
    _rec = (_MINI_CRASH_ROUNDS.get(st.get("round_id")) or {}).get(uid)
    if _rec:
        _rec["res"] = "win" if win else "crash"
        _rec["m"] = m if win else st["crash"]
    return {"done": True, "active": False, "result": "win" if win else "crash", "mult": m, "crash": st["crash"],
            "bet": bet, "payout": payout, "profit": payout - bet, "balance": await _mini_balance(uid), "hist": _MINI_HIST[:14],
            "rate": MINI_CRASH_RATE}


@_cd_guard("crash")
async def _p_game_crash_start(b, user):
    uid, _bal = await _mini_ctx(user)
    bet = _mini_bet(b)
    tgt = None
    if b.get("target") not in (None, "", 0):
        try:
            tgt = round(float(b.get("target")), 2)
        except (TypeError, ValueError):
            raise _ApiError("ضریب نامعتبره")
        if tgt < 1.1 or tgt > MINI_CRASH_MAX:
            raise _ApiError("ضریب باید بین ۱٫۱ تا ۱۰۰ باشه.")

    # قفل دیتابیسی مشترک: دو کاربر هم‌زمان هم نمی‌تونن وسط پرواز شرط ثبت کنن.
    async with _mini_lock(uid):
        async with pool.acquire() as c:
            async with c.transaction():
                await c.fetchval("SELECT pg_advisory_xact_lock($1::bigint)", 2026111701)
                now = time.time()
                if await c.fetchval("SELECT 1 FROM mini_games WHERE uid=$1", uid):
                    raise _ApiError("اول بازی قبلیت رو تموم کن.")

                slot = int(now // MINI_CRASH_DELAY)
                current = await c.fetchrow(
                    "SELECT starts_at, crash_point FROM mini_crash_rounds WHERE round_id=$1",
                    slot - 1)
                if current:
                    current_start = float(current["starts_at"])
                    current_end = current_start + _mini_time_for(float(current["crash_point"]))
                    if current_start <= now < current_end:
                        raise _ApiError("🚀 موشک در حال پروازه! باید سقوط کنه تا بتونی برای دور بعد شرط ببندی.")

                round_id = slot
                starts_at = (round_id + 1) * MINI_CRASH_DELAY
                await c.execute(
                    "INSERT INTO mini_crash_rounds(round_id,starts_at,crash_point,created_at) "
                    "VALUES($1,$2,$3,$4) ON CONFLICT(round_id) DO NOTHING",
                    round_id, starts_at, _mini_crash_point(), now)
                rr = await c.fetchrow(
                    "SELECT starts_at,crash_point FROM mini_crash_rounds WHERE round_id=$1",
                    round_id)
                if not rr:
                    raise _ApiError("ساخت دور موشک ناموفق بود؛ دوباره تلاش کن.", 503)
                starts_at = float(rr["starts_at"])
                if starts_at <= now:
                    raise _ApiError("مهلت شرط‌بندی این دور تموم شده؛ منتظر دور بعدی بمون.")

                new_balance = await c.fetchval(
                    "UPDATE users SET balance=balance-$1::bigint "
                    "WHERE user_id=$2 AND balance >= $1::bigint RETURNING balance",
                    bet, uid)
                if new_balance is None:
                    raise _ApiError("موجودی کافی نیست.")
                st = {"crash": float(rr["crash_point"]), "t0": starts_at,
                      "target": tgt, "round_id": round_id}
                await c.execute(
                    "INSERT INTO mini_games(uid,kind,bet,state,created_at) VALUES($1,'crash',$2,$3,$4)",
                    uid, bet, json.dumps(st), now)

    _mini_crash_register(round_id, uid,
                         str(user.get("first_name") or user.get("username") or "کاربر")[:24],
                         bet, tgt)
    return _j({"t0": st["t0"], "now": time.time(), "rate": MINI_CRASH_RATE,
               "bet": bet, "target": tgt, "balance": int(new_balance)})

async def _mini_crash_watch_state_core(bal: int) -> dict:
    """نمای عمومی دورهای موشک؛ پرواز مستقل از شرط کاربران و بدون افشای نقطه انفجار."""
    now = time.time()
    slot = int(now // MINI_CRASH_DELAY)
    # اگر دور همین بازه در حال پرواز باشد، آن را نشان بده؛ وگرنه دور بعدی را آماده کن.
    current = await pool.fetchrow("SELECT round_id,starts_at,crash_point FROM mini_crash_rounds WHERE round_id=$1", slot - 1)
    if current and now >= float(current["starts_at"]):
        t0 = float(current["starts_at"])
        elapsed = max(0.0, now - t0)
        cp = float(current["crash_point"])
        if elapsed < _mini_time_for(cp):
            return {**_mini_base(bal), "active": False, "done": False, "watch_phase": "flying",
                    "watch_round": int(current["round_id"]), "t0": t0, "now": now,
                    "mult": _mini_mult_at(elapsed), "rate": MINI_CRASH_RATE,
                    "next_t0": (slot + 1) * MINI_CRASH_DELAY}
        return {**_mini_base(bal), "active": False, "done": False, "watch_phase": "crashed",
                "watch_round": int(current["round_id"]), "t0": t0, "now": now,
                "mult": cp, "rate": MINI_CRASH_RATE,
                "next_t0": (slot + 1) * MINI_CRASH_DELAY}
    rid = slot
    starts_at = (rid + 1) * MINI_CRASH_DELAY
    rr = await pool.fetchrow(
        "INSERT INTO mini_crash_rounds(round_id,starts_at,crash_point,created_at) VALUES($1,$2,$3,$4) "
        "ON CONFLICT(round_id) DO UPDATE SET round_id=EXCLUDED.round_id RETURNING starts_at",
        rid, starts_at, _mini_crash_point(), now)
    return {**_mini_base(bal), "active": False, "done": False, "watch_phase": "waiting",
            "watch_round": rid, "t0": float(rr["starts_at"]), "now": now,
            "mult": 1.0, "rate": MINI_CRASH_RATE}


async def _mini_crash_watch_state(bal: int) -> dict:
    d = await _mini_crash_watch_state_core(bal)
    try:
        rid, now, t0 = int(d["watch_round"]), float(d["now"]), float(d["t0"])
        cp = await pool.fetchval("SELECT crash_point FROM mini_crash_rounds WHERE round_id=$1", rid)
        d["players"] = await _mini_crash_players(rid, t0, float(cp) if cp is not None else None, now)
        if d.get("next_t0"):
            d["players_next"] = await _mini_crash_players(rid + 1, float(d["next_t0"]), None, now)
    except Exception:
        log.debug("crash players failed", exc_info=True)
        d.setdefault("players", [])
    return d


async def _g_game_crash_state(qs, user):
    uid, bal = await _mini_ctx(user)
    async with _mini_lock(uid):
        row = await pool.fetchrow("SELECT kind, bet, state FROM mini_games WHERE uid=$1", uid)
        if not row or row["kind"] != "crash":
            base = await _mini_crash_watch_state(bal)
            base["other"] = row["kind"] if row else None
            return _j(base)
        st, bet = json.loads(row["state"]), int(row["bet"])
        res, m = _mini_crash_eval(st, False)
        if res == "run":
            return _j({**_mini_base(bal), "active": True, "done": False, "t0": st["t0"], "now": time.time(),
                       "rate": MINI_CRASH_RATE, "bet": bet, "target": st.get("target"),
                       "players": await _mini_crash_players(st.get("round_id"), st["t0"], st["crash"], time.time())})
        return _j(await _mini_crash_finish(uid, bet, st, res, m))


async def _p_game_crash_cashout(b, user):
    uid, _bal = await _mini_ctx(user)
    async with _mini_lock(uid):
        row = await pool.fetchrow("SELECT kind, bet, state FROM mini_games WHERE uid=$1", uid)
        if not row or row["kind"] != "crash":
            raise _ApiError("بازی فعالی نداری.")
        st, bet = json.loads(row["state"]), int(row["bet"])
        if time.time() < st["t0"]:
            raise _ApiError("موشک هنوز پرواز نکرده؛ تا پایان شمارش معکوس ۱۰ ثانیه‌ای صبر کن.")
        res, m = _mini_crash_eval(st, True)
        return _j(await _mini_crash_finish(uid, bet, st, res, m))


# ───── مین ─────
def _mini_mines_view(st: dict, bet: int) -> dict:
    k = len(st["opened"])
    m = _mini_mines_mult(k)
    nxt = _mini_mines_mult(k + 1) if k < MINI_MINES_CELLS - MINI_MINES_COUNT else None
    return {"opened": st["opened"], "mult": m, "next": nxt, "bet": bet, "payout": int(bet * m + 1e-6),
            "cells": MINI_MINES_CELLS, "mines": MINI_MINES_COUNT}


@_cd_guard("mines")
async def _p_game_mines_start(b, user):
    uid, _bal = await _mini_ctx(user)
    bet = _mini_bet(b)
    async with _mini_lock(uid):
        if await pool.fetchval("SELECT 1 FROM mini_games WHERE uid=$1", uid):
            raise _ApiError("اول بازی قبلیت رو تموم کن.")
        if await _take(uid, bet) is None:
            raise _ApiError("موجودی کافی نیست.")
        st = {"bombs": random.sample(range(MINI_MINES_CELLS), MINI_MINES_COUNT), "opened": []}
        try:
            await pool.execute("INSERT INTO mini_games (uid, kind, bet, state, created_at) VALUES ($1,'mines',$2,$3,$4)",
                               uid, bet, json.dumps(st), time.time())
        except Exception:
            await _give(uid, bet)
            raise
    return _j({**_mini_mines_view(st, bet), "balance": await _mini_balance(uid)})


async def _g_game_mines_state(qs, user):
    uid, bal = await _mini_ctx(user)
    row = await pool.fetchrow("SELECT kind, bet, state FROM mini_games WHERE uid=$1", uid)
    if not row or row["kind"] != "mines":
        return _j({**_mini_base(bal), "active": False, "other": row["kind"] if row else None,
                   "cells": MINI_MINES_CELLS, "mines": MINI_MINES_COUNT})
    return _j({**_mini_base(bal), "active": True, **_mini_mines_view(json.loads(row["state"]), int(row["bet"]))})


async def _p_game_mines_open(b, user):
    uid, _bal = await _mini_ctx(user)
    cell = _int(b.get("cell"))
    if cell is None or not 0 <= cell < MINI_MINES_CELLS:
        raise _ApiError("خونه نامعتبره")
    async with _mini_lock(uid):
        row = await pool.fetchrow("SELECT kind, bet, state FROM mini_games WHERE uid=$1", uid)
        if not row or row["kind"] != "mines":
            raise _ApiError("بازی فعالی نداری.")
        st, bet = json.loads(row["state"]), int(row["bet"])
        if cell in st["opened"]:
            raise _ApiError("این خونه قبلاً باز شده.")
        if cell in st["bombs"]:
            await pool.execute("DELETE FROM mini_games WHERE uid=$1", uid)
            return _j({"lost": True, "cell": cell, "opened": st["opened"], "bombs": st["bombs"], "bet": bet,
                       "balance": await _mini_balance(uid)})
        st["opened"].append(cell)
        v = _mini_mines_view(st, bet)
        if len(st["opened"]) >= MINI_MINES_CELLS - MINI_MINES_COUNT or v["mult"] >= MINI_MINES_MAXMULT:
            await pool.execute("DELETE FROM mini_games WHERE uid=$1", uid)
            await _give(uid, v["payout"])
            return _j({**v, "won": True, "auto": True, "bombs": st["bombs"], "profit": v["payout"] - bet,
                       "balance": await _mini_balance(uid)})
        await pool.execute("UPDATE mini_games SET state=$2 WHERE uid=$1", uid, json.dumps(st))
        return _j(v)


async def _p_game_mines_cashout(b, user):
    uid, _bal = await _mini_ctx(user)
    async with _mini_lock(uid):
        row = await pool.fetchrow("SELECT kind, bet, state FROM mini_games WHERE uid=$1", uid)
        if not row or row["kind"] != "mines":
            raise _ApiError("بازی فعالی نداری.")
        st, bet = json.loads(row["state"]), int(row["bet"])
        if not st["opened"]:
            raise _ApiError("اول حداقل یه خونه امن باز کن.")
        v = _mini_mines_view(st, bet)
        await pool.execute("DELETE FROM mini_games WHERE uid=$1", uid)
        await _give(uid, v["payout"])
        return _j({**v, "won": True, "auto": False, "bombs": st["bombs"], "profit": v["payout"] - bet,
                   "balance": await _mini_balance(uid)})



# ───── برج گنج (۸ طبقه؛ آسان = ۴ در، سخت = ۳ در؛ پشت یکی از درهای هر طبقه نگهبان است) ─────
TOWER_FLOORS = 8
TOWER_RTP = 0.95
TOWER_MODES = {"easy": {"cols": 4, "fa": "آسان", "top": 5.0}, "hard": {"cols": 3, "fa": "سخت", "top": 7.0}}   # top = ضریب طبقه‌ی آخر (سقف)
TOWER_COLS = 4                                                    # سازگاری با نسخه‌ی قبلی
TOWER_MULTS = (1.26, 1.68, 2.25, 3.00, 4.00, 5.33, 7.11)          # فقط برای بازی‌های نیمه‌تمامِ نسخه‌ی قبلی


def _tower_mode(m) -> str:
    return "hard" if str(m or "").strip().lower() in ("hard", "h", "سخت") else "easy"


def _tower_mults_for(mode: str) -> list:
    """ضریب طبقه‌ها: رشد هندسی تا سقف هر حالت (آسان ×۵، سخت ×۷)؛ ضریب طبقه‌ی آخر دقیقاً برابر سقفه."""
    top = float(TOWER_MODES[mode]["top"])
    out = [round(top ** (k / TOWER_FLOORS), 2) for k in range(1, TOWER_FLOORS + 1)]
    out[-1] = top
    return out


TOWER_MULTS_BY_MODE = {m: _tower_mults_for(m) for m in TOWER_MODES}


def _tower_cfg(st: dict):
    mode = st.get("mode")
    if mode in TOWER_MODES:
        return mode, TOWER_MODES[mode]["cols"], TOWER_MULTS_BY_MODE[mode]
    return "easy", TOWER_COLS, list(TOWER_MULTS)       # بازی قدیمی بدون حالت


# ایموجی‌های پرمیوم برج: نقش هر کدوم از روی ایموجی پایه‌ی خودِ استیکر تشخیص داده میشه.
# اگه جایی اشتباه نشست، همین‌جا دستی بنویس: TOWER_EMOJI_OVERRIDE = {"door": "آیدی", "lock": "آیدی", ...}
TOWER_EIDS = ["5994417719666024807", "6001098094618353299", "6001375025519663654", "5994634555384934359",
              "5994347320857078339", "5994388054326910670", "5994478622302281933", "5994525506165284642"]
TOWER_EMOJI_OVERRIDE: dict = {}
_TOWER_FB = {"tower": "🏰", "coin": "🪙", "target": "🎯", "guard": "🛡", "gem": "💎", "lock": "🔒", "door": "🚪", "arrow": "⬅️"}
_TOWER_BASE = {"🏰": "tower", "🏯": "tower", "🏛": "tower", "🗼": "tower", "🪙": "coin", "💰": "coin", "💵": "coin",
               "🎯": "target", "🛡": "guard", "💂": "guard", "⚔": "guard", "💎": "gem", "💠": "gem", "✨": "gem",
               "🔒": "lock", "🔐": "lock", "🔓": "lock", "🔑": "lock", "🗝": "lock", "🚪": "door",
               "⬅": "arrow", "◀": "arrow", "👈": "arrow", "↩": "arrow", "🔙": "arrow", "👉": "arrow", "➡": "arrow"}
_TOWER_EMOJI: dict = {}
_TOWER_EMOJI_DONE = False
_TOWER_EMOJI_TRY = 0.0


async def _tower_emoji_ensure():
    global _TOWER_EMOJI_DONE, _TOWER_EMOJI_TRY
    if _TOWER_EMOJI_DONE or BOT_REF is None or time.time() - _TOWER_EMOJI_TRY < 300:
        return
    _TOWER_EMOJI_TRY = time.time()
    try:
        stickers = await _tg_call(BOT_REF.get_custom_emoji_stickers, TOWER_EIDS)
        by_role: dict = {}
        for stk in stickers or []:
            base = (getattr(stk, "emoji", "") or "").replace("\ufe0f", "").replace("\u200d", "")[:1]
            role = _TOWER_BASE.get(base)
            cid = str(getattr(stk, "custom_emoji_id", "") or "")
            log.info("tower emoji %s -> base %r role %s", cid, base, role)
            if role and cid:
                by_role.setdefault(role, []).append(cid)
        found = {r: v[0] for r, v in by_role.items()}
        if "lock" not in found and len(by_role.get("door", [])) >= 2:
            found["lock"], found["door"] = by_role["door"][0], by_role["door"][1]
            log.warning("tower emoji: two door emojis found, assigned by order (lock first)")
        found.update({k: str(v) for k, v in TOWER_EMOJI_OVERRIDE.items() if k in _TOWER_FB})
        _TOWER_EMOJI.clear()
        _TOWER_EMOJI.update(found)
        _TOWER_EMOJI_DONE = True
    except Exception:
        log.warning("tower emoji detection failed", exc_info=True)


def _tw(role: str) -> str:
    eid = _TOWER_EMOJI.get(role)
    fb = _TOWER_FB[role]
    return f'<tg-emoji emoji-id="{eid}">{fb}</tg-emoji>' if eid else fb


def _tower_view(st: dict, bet: int) -> dict:
    mode, cols, mults = _tower_cfg(st)
    k = len(st["picks"])
    m = mults[k - 1] if k else 1.0
    return {"mode": mode, "mode_fa": TOWER_MODES[mode]["fa"], "rows": len(mults), "cols": cols, "mults": list(mults),
            "picks": st["picks"], "bet": bet, "mult": m, "payout": int(bet * m + 1e-6)}


def _tower_reveal(st: dict) -> dict:
    return {"bombs": st["bombs"]}


@_cd_guard("tower")
async def _p_game_tower_start(b, user):
    import secrets
    uid, _bal = await _mini_ctx(user)
    bet = _mini_bet(b)
    mode = _tower_mode(b.get("mode"))
    cols = TOWER_MODES[mode]["cols"]
    async with _mini_lock(uid):
        if await pool.fetchval("SELECT 1 FROM mini_games WHERE uid=$1", uid):
            raise _ApiError("اول بازی قبلیت رو تموم کن.")
        if await _take(uid, bet) is None:
            raise _ApiError("موجودی کافی نیست.")
        bombs = [secrets.randbelow(cols) for _ in range(TOWER_FLOORS)]
        st = {"mode": mode, "bombs": bombs, "picks": []}
        try:
            await pool.execute("INSERT INTO mini_games (uid, kind, bet, state, created_at) VALUES ($1,'tower',$2,$3,$4)",
                               uid, bet, json.dumps(st), time.time())
        except Exception:
            await _give(uid, bet)
            raise
    return _j({**_tower_view(st, bet), "balance": await _mini_balance(uid)})


async def _g_game_tower_state(qs, user):
    uid, bal = await _mini_ctx(user)
    await _tower_emoji_ensure()
    row = await pool.fetchrow("SELECT kind, bet, state FROM mini_games WHERE uid=$1", uid)
    base = {**_mini_base(bal), "rows": TOWER_FLOORS, "cols": TOWER_MODES["easy"]["cols"],
            "mults": TOWER_MULTS_BY_MODE["easy"], "emoji": dict(_TOWER_EMOJI),
            "modes": {m: {"cols": v["cols"], "fa": v["fa"], "mults": TOWER_MULTS_BY_MODE[m]} for m, v in TOWER_MODES.items()}}
    if not row or row["kind"] != "tower":
        return _j({**base, "active": False, "other": row["kind"] if row else None})
    return _j({**base, "active": True, **_tower_view(json.loads(row["state"]), int(row["bet"]))})


async def _p_game_tower_open(b, user):
    uid, _bal = await _mini_ctx(user)
    col = _int(b.get("col"))
    async with _mini_lock(uid):
        row = await pool.fetchrow("SELECT kind, bet, state FROM mini_games WHERE uid=$1", uid)
        if not row or row["kind"] != "tower":
            raise _ApiError("بازی فعالی نداری.")
        st, bet = json.loads(row["state"]), int(row["bet"])
        mode, cols, mults = _tower_cfg(st)
        if col is None or not 0 <= col < cols:
            raise _ApiError("در نامعتبره")
        r = len(st["picks"])
        if st["bombs"][r] == col:
            await pool.execute("DELETE FROM mini_games WHERE uid=$1", uid)
            return _j({"lost": True, "row": r, "col": col, "picks": st["picks"], "bet": bet,
                       "mode": mode, "cols": cols, "mults": list(mults), **_tower_reveal(st),
                       "balance": await _mini_balance(uid)})
        st["picks"].append(col)
        v = _tower_view(st, bet)
        if len(st["picks"]) >= len(mults):
            await pool.execute("DELETE FROM mini_games WHERE uid=$1", uid)
            await _give(uid, v["payout"])
            return _j({**v, "won": True, "auto": True, **_tower_reveal(st), "profit": v["payout"] - bet,
                       "balance": await _mini_balance(uid)})
        await pool.execute("UPDATE mini_games SET state=$2 WHERE uid=$1", uid, json.dumps(st))
        return _j(v)


async def _p_game_tower_cashout(b, user):
    uid, _bal = await _mini_ctx(user)
    async with _mini_lock(uid):
        row = await pool.fetchrow("SELECT kind, bet, state FROM mini_games WHERE uid=$1", uid)
        if not row or row["kind"] != "tower":
            raise _ApiError("بازی فعالی نداری.")
        st, bet = json.loads(row["state"]), int(row["bet"])
        if not st["picks"]:
            raise _ApiError("اول حداقل یه طبقه رو رد کن.")
        v = _tower_view(st, bet)
        await pool.execute("DELETE FROM mini_games WHERE uid=$1", uid)
        await _give(uid, v["payout"])
        return _j({**v, "won": True, "auto": False, **_tower_reveal(st), "profit": v["payout"] - bet,
                   "balance": await _mini_balance(uid)})


async def _p_game_tower_cancel(b, user):
    """انصراف و برگشت شرط؛ فقط تا وقتی هنوز هیچ دری باز نشده."""
    uid, _bal = await _mini_ctx(user)
    async with _mini_lock(uid):
        row = await pool.fetchrow("SELECT kind, bet, state FROM mini_games WHERE uid=$1", uid)
        if not row or row["kind"] != "tower":
            raise _ApiError("بازی فعالی نداری.")
        st, bet = json.loads(row["state"]), int(row["bet"])
        if st["picks"]:
            raise _ApiError("بعد از باز کردن اولین در انصراف ممکن نیست؛ برداشت بزن.")
        await pool.execute("DELETE FROM mini_games WHERE uid=$1", uid)
        await _give(uid, bet)
        _CD_STAMPS["slow"].pop(uid, None)   # شرط برگشت؛ کولداون برج هم برمی‌گرده
        return _j({"cancelled": True, "bet": bet, "balance": await _mini_balance(uid)})


def _tower_result_data(result):
    return json.loads(result[2].decode("utf-8"))


def _tower_mode_code(mode: str) -> str:
    return "h" if mode == "hard" else "e"


def _tower_bot_keyboard(uid: int, data: dict):
    picks = data.get("picks") or []
    cols, floor = int(data.get("cols") or 4), len(picks)
    rows = []
    if floor < int(data.get("rows") or TOWER_FLOORS):
        door = _TOWER_EMOJI.get("door")
        rows.append([btn(str(i + 1), "success", icon=door, callback_data=f"cz:to:{uid}:{i}") for i in range(cols - 1, -1, -1)])
    if floor:
        rows.append([btn(f"💰 برداشت {int(data.get('payout', 0)):,}", "primary", callback_data=f"cz:tc:{uid}")])
    else:
        rows.append([btn("انصراف و برگشت شرط", "danger", callback_data=f"cz:tx:{uid}")])
    return InlineKeyboardMarkup(rows)


def _tower_bot_text(data: dict) -> str:
    picks = data.get("picks") or []
    mults = data.get("mults") or TOWER_MULTS_BY_MODE["easy"]
    cols, bet, k, n = int(data.get("cols") or 4), int(data.get("bet", 0)), len(picks), len(mults)
    chance = round((cols - 1) / cols * 100)
    lines = [f"{_tw('tower')} <b>برج گنج · {data.get('mode_fa') or 'آسان'}</b>",
             f"{_tw('coin')} شرط: <b>{bet:,}</b> تومان", ""]
    lines += [f"{_tw('target')} یکی از <b>{cols}</b> در را انتخاب کن.",
              f"{_tw('guard')} پشت یکی از آنها نگهبان است!"]
    if k < n:
        lines.append(f"{_tw('target')} شانس طبقه بعد: <b>{chance}٪</b>")
    if k:
        lines.append(f"{_tw('coin')} برداشت فعلی: <b>×{float(data.get('mult', 1)):.2f}</b> = <b>{int(data.get('payout', 0)):,}</b> تومان")
    lines += ["", f"{_tw('gem')} گنج: <b>{int(bet * mults[-1] + 1e-6):,}</b> تومان", ""]
    for r in range(n - 1, -1, -1):
        prize = int(bet * mults[r] + 1e-6)
        if r < k:
            lines.append(" ".join(["✅"] * cols) + f"  {prize:,}")
        elif r == k:
            lines.append(" ".join([_tw("door")] * cols) + f"  {_tw('arrow')} {prize:,}")
        else:
            lines.append(" ".join([_tw("lock")] * cols) + f"  {prize:,}")
    return "\n".join(lines)


def _tower_end_text(data: dict, head: str) -> str:
    """نمای پایان بازی: همه‌ی نگهبان‌ها لو میرن."""
    bombs = data.get("bombs") or []
    cols, picks = int(data.get("cols") or 4), data.get("picks") or []
    lines = [head, ""]
    for r in range(len(bombs) - 1, -1, -1):
        cells = []
        for c in range(cols):
            if bombs[r] == c:
                cells.append(_tw("guard"))
            elif r < len(picks) and picks[r] == c:
                cells.append("✅")
            else:
                cells.append(_tw("door"))
        lines.append(" ".join(cells))
    return "\n".join(lines)


def _tower_end_kb(uid: int, mode: str):
    return InlineKeyboardMarkup([[btn("🔁 بازی دوباره", "success", callback_data=f"cz:a:{uid}:tower:{_tower_mode_code(mode)}")],
                                 [btn("🔙 کازینو", None, icon=EID_BACK, callback_data=f"cz:m:{uid}")]])


