# ───────────────────────── مزرعه (مینی‌اپ؛ فعلاً فقط برای پشتیبان‌ها) ─────────────────────────
# یه زمین (فقط یه محصول: گندم یا سویا)، یه گاو (سویا می‌خوره، شیر میده) و انبار (ظرفیت مشترک) با ارتقا.
# سکه‌ی مزرعه جداست و به پول واقعی ربات (balance) ربطی نداره؛ برای تست امنه. همه‌ی زمان‌ها سمت سرور حساب میشن.
FARM_CROPS = {
    "wheat": {"name": "گندم", "seed": 10, "secs": 60, "yield": 6, "price": 6, "lvl": 1},
    "soy": {"name": "سویا", "seed": 14, "secs": 90, "yield": 4, "price": 9, "lvl": 1},
    "corn": {"name": "ذرت", "seed": 18, "secs": 120, "yield": 5, "price": 10, "lvl": 3},
}
FARM_RECIPES = {   # کارگاه‌ها: ورودی → یک محصول
    "bread": {"b": "bakery", "lvl": 2, "in": {"wheat": 2}, "secs": 40, "price": 22, "name": "نان"},
    "cheese": {"b": "dairy", "lvl": 4, "in": {"milk": 2}, "secs": 60, "price": 40, "name": "پنیر"},
    "cake": {"b": "bakery", "lvl": 6, "in": {"wheat": 3, "milk": 1}, "secs": 90, "price": 70, "name": "کیک"},
    "butter": {"b": "dairy", "lvl": 5, "in": {"milk": 3}, "secs": 75, "price": 62, "name": "کره"},
    "pie": {"b": "bakery", "lvl": 7, "in": {"wheat": 2, "corn": 2, "milk": 1}, "secs": 110, "price": 105, "name": "پای"},
}
FARM_BLD_LVL = {"bakery": 2, "dairy": 4}
FARM_MILK_PRICE = 14
FARM_MILK_SECS = 60
FARM_MILK_BASE = 2
FARM_BARN_BASE = 24
FARM_BARN_STEP = 16
FARM_MAX_LVL = 5
FARM_START_COINS = 120
FARM_START_SOY = 1
FARM_UP_COST = {"barn": [120, 300, 700, 1500], "field": [150, 400, 900, 1800], "cow": [200, 500, 1000, 2000]}
FARM_UP_NAME = {"barn": "انبار", "field": "زمین", "cow": "گاو"}
FARM_COL_ITEMS = ("wheat", "soy", "milk", "corn")      # ستون‌های دیتابیس
FARM_XTRA = ("bread", "cheese", "cake", "butter", "pie")                # داخل ext (json)
FARM_ITEMS = FARM_COL_ITEMS + FARM_XTRA
FARM_ITEM_FA = {"wheat": "گندم", "soy": "سویا", "milk": "شیر", "corn": "ذرت", "bread": "نان", "cheese": "پنیر", "cake": "کیک", "butter": "کره", "pie": "پای"}
FARM_PRICE = {"wheat": 6, "soy": 9, "milk": 14, "corn": 10, "bread": 22, "cheese": 40, "cake": 70, "butter": 62, "pie": 105}
FARM_XP_LV = [0, 20, 60, 120, 200, 300, 430, 600]      # حداقل XP هر سطح (۸ سطح)
FARM_UNLOCKS = ["گندم و سویا، گاوداری و انبار", "نانوایی 🍞 (نان)", "کاشت ذرت 🌽", "لبنیات‌سازی 🧀 (پنیر)",
                "کره 🧈 در لبنیات + مشتری چهارم", "کیک 🍰 در نانوایی", "پای 🥧 در نانوایی + سفارش‌های بزرگ‌تر", "سفارش پنجم و پاداش بیشتر"]
FARM_WHO = ["🧑‍🌾", "👩‍🌾", "👨‍🍳", "🧕", "👳", "👩", "🧔", "👵"]
# زمین‌های اطراف: نقشه ۴×۴ بلوک (هر بلوک ۶×۶ خانه)؛ ۴ بلوک وسط مزرعه‌ی اصلیه و ۱۲ بلوک دورش قابل‌خریدن.
# فقط بلوکی که لبه‌اش به مزرعه یا زمین خریده‌شده چسبیده باشه خریدنیه؛ قیمت با تعداد خریدها بالا میره.
FARM_PLOT_GRID = 4
FARM_PLOT_CORE = frozenset({5, 6, 9, 10})
FARM_PLOT_COST = [300, 450, 650, 900, 1250, 1700, 2300, 3000, 4000, 5200, 6800, 9000]


def _farm_cap(barn_lvl: int) -> int:
    return FARM_BARN_BASE + FARM_BARN_STEP * (barn_lvl - 1)


def _farm_yield(crop: str, field_lvl: int) -> int:
    return int(math.ceil(FARM_CROPS[crop]["yield"] * (1 + 0.25 * (field_lvl - 1))))


def _farm_grow_secs(crop: str, field_lvl: int) -> int:
    return int(round(FARM_CROPS[crop]["secs"] * (1 - 0.06 * (field_lvl - 1))))


def _farm_milk_amount(cow_lvl: int) -> int:
    return FARM_MILK_BASE + (cow_lvl - 1)


def _farm_milk_secs(cow_lvl: int) -> int:
    return FARM_MILK_SECS - 6 * (cow_lvl - 1)


def _farm_plv(xp: int) -> int:
    return sum(1 for t in FARM_XP_LV if xp >= t)


def _farm_slots(plv: int) -> int:
    return 3 + (1 if plv >= 5 else 0) + (1 if plv >= 8 else 0)


def _farm_ext(r) -> dict:
    try:
        e = json.loads(r.get("ext") or "{}")
        if not isinstance(e, dict):
            e = {}
    except Exception:
        e = {}
    e.setdefault("items", {}); e.setdefault("prod", {}); e.setdefault("orders", [])
    e.setdefault("next_at", 0); e.setdefault("seq", 0)
    pl = e.get("plots")
    e["plots"] = sorted({int(i) for i in pl if isinstance(i, int) and 0 <= i < FARM_PLOT_GRID ** 2 and i not in FARM_PLOT_CORE}) if isinstance(pl, list) else []
    return e


def _farm_plot_open(i: int, owned) -> bool:
    """بلوک i خریدنیه؟ (خریده نشده و یکی از چهار همسایه‌ی کناریش مزرعه یا زمین خریده‌شده باشه)"""
    g = FARM_PLOT_GRID
    if not (0 <= i < g * g) or i in FARM_PLOT_CORE or i in owned:
        return False
    r, q = divmod(i, g)
    have = FARM_PLOT_CORE | set(owned)
    return any(0 <= rr < g and 0 <= qq < g and rr * g + qq in have for rr, qq in ((r - 1, q), (r + 1, q), (r, q - 1), (r, q + 1)))


def _farm_inv(r, e) -> dict:
    inv = {k: int(r.get(k) or 0) for k in FARM_COL_ITEMS}
    inv.update({k: int(e["items"].get(k, 0)) for k in FARM_XTRA})
    return inv


def _farm_new_order(e: dict, plv: int) -> dict:
    pool = ["wheat", "soy", "milk"] + (["bread"] if plv >= 2 else []) + (["corn"] if plv >= 3 else []) \
        + (["cheese"] if plv >= 4 else []) + (["cake"] if plv >= 6 else []) + (["butter"] if plv >= 5 else []) + (["pie"] if plv >= 7 else [])
    need = {}
    for k in random.sample(pool, min(len(pool), random.choice((1, 2)))):
        cap_q = 2 if k in ("cheese", "cake", "butter", "pie") else 1 + plv // 3
        need[k] = random.randint(1, max(1, cap_q))
    e["seq"] = int(e["seq"]) + 1
    worth = sum(FARM_PRICE[k] * n for k, n in need.items())
    coins = int(worth * (1.8 if plv >= 8 else 1.6)) + 4
    return {"id": e["seq"], "who": random.choice(FARM_WHO), "need": need, "coins": coins, "xp": 2 * sum(need.values())}


def _farm_orders_fix(e: dict, plv: int, now: float) -> bool:
    ch = False
    while len(e["orders"]) < _farm_slots(plv) and now >= float(e["next_at"]):
        e["orders"].append(_farm_new_order(e, plv)); ch = True
    return ch


def _farm_state(row, now: float) -> dict:
    """وضعیت کامل مزرعه برای کلاینت (همه‌ی عددها و زمان‌ها از سرورن)."""
    r = dict(row)
    e = _farm_ext(r)
    items = _farm_inv(r, e)
    xp = int(r.get("xp") or 0)
    plv = _farm_plv(xp)
    used = sum(items.values())
    cap = _farm_cap(int(r["barn_lvl"]))
    crop = r["crop"] or None
    if not crop:
        fstat = "empty"
    elif now >= float(r["crop_ready"]):
        fstat = "ready"
    else:
        fstat = "growing"
    cr = float(r["cow_ready"] or 0)
    cstat = "hungry" if cr <= 0 else ("ready" if now >= cr else "producing")
    lv = {"barn": int(r["barn_lvl"]), "field": int(r["field_lvl"]), "cow": int(r["cow_lvl"])}
    return {
        "now": now, "coins": int(r["coins"]), "slots": _farm_slots(plv),
        "items": items, "used": used, "cap": cap,
        "lvl": lv, "max_lvl": FARM_MAX_LVL,
        "xp": xp, "plv": plv, "plv_max": len(FARM_XP_LV), "xp_lo": FARM_XP_LV[plv - 1],
        "xp_hi": FARM_XP_LV[plv] if plv < len(FARM_XP_LV) else None,
        "prod": e["prod"], "orders": e["orders"], "next_in": max(0, float(e["next_at"]) - now),
        "plots": {"owned": e["plots"], "grid": FARM_PLOT_GRID, "core": sorted(FARM_PLOT_CORE),
                  "cost": (FARM_PLOT_COST[len(e["plots"])] if len(e["plots"]) < len(FARM_PLOT_COST) else None)},
        "recipes": [{"key": k, **v} for k, v in FARM_RECIPES.items()],
        "up_cost": {k: (FARM_UP_COST[k][lv[k] - 1] if lv[k] < FARM_MAX_LVL else None) for k in FARM_UP_COST},
        "field": {"status": fstat, "crop": crop, "planted_at": float(r["crop_at"] or 0), "ready_at": float(r["crop_ready"] or 0)},
        "cow": {"status": cstat, "ready_at": cr, "milk": _farm_milk_amount(lv["cow"]), "secs": _farm_milk_secs(lv["cow"])},
        "cfg": {
            "crops": {k: {**v, "yield": _farm_yield(k, lv["field"]), "secs": _farm_grow_secs(k, lv["field"])} for k, v in FARM_CROPS.items()},
            "milk_price": FARM_MILK_PRICE, "feed_soy": 1, "prices": FARM_PRICE, "bld": FARM_BLD_LVL, "unlocks": FARM_UNLOCKS,
        },
    }


def _farm_apply(action: str, row, data: dict, now: float):
    """منطق خالصِ مزرعه (بدون دیتابیس): (تغییرات ستون‌ها, پیام, افکت) یا _ApiError."""
    r = dict(row)
    e = _farm_ext(r)
    used = sum(_farm_inv(r, e).values())
    cap = _farm_cap(int(r["barn_lvl"]))
    free = cap - used
    plv = _farm_plv(int(r.get("xp") or 0))
    if action == "plant":
        crop = str(data.get("crop") or "")
        if crop not in FARM_CROPS:
            raise _ApiError("محصول نامعتبره")
        if plv < FARM_CROPS[crop]["lvl"]:
            raise _ApiError(f"{FARM_CROPS[crop]['name']} در سطح {FARM_CROPS[crop]['lvl']} باز میشه")
        if r["crop"]:
            raise _ApiError("زمین الان پره؛ اول محصولش رو برداشت کن")
        seed = FARM_CROPS[crop]["seed"]
        if int(r["coins"]) < seed:
            raise _ApiError(f"برای بذر {FARM_CROPS[crop]['name']} {seed} سکه لازمه")
        secs = _farm_grow_secs(crop, int(r["field_lvl"]))
        return ({"coins": int(r["coins"]) - seed, "crop": crop, "crop_at": now, "crop_ready": now + secs},
                f"{FARM_CROPS[crop]['name']} کاشته شد 🌱", {"kind": "plant", "crop": crop})
    if action == "harvest":
        if not r["crop"]:
            raise _ApiError("زمین خالیه")
        if now < float(r["crop_ready"]):
            raise _ApiError("هنوز نرسیده")
        crop = r["crop"]
        y = _farm_yield(crop, int(r["field_lvl"]))
        if y > free:
            raise _ApiError(f"انبار جا نداره (برای برداشت {y} جای خالی لازمه)؛ چیزی بفروش یا انبار رو ارتقا بده")
        return ({crop: int(r[crop]) + y, "crop": None, "crop_at": 0, "crop_ready": 0},
                f"{y} {FARM_CROPS[crop]['name']} برداشت شد 🌾", {"kind": "harvest", "crop": crop, "n": y})
    if action == "feed":
        if float(r["cow_ready"] or 0) > 0:
            raise _ApiError("گاو الان سیره")
        if int(r["soy"]) < 1:
            raise _ApiError("سویا نداری؛ اول سویا بکار و برداشت کن")
        secs = _farm_milk_secs(int(r["cow_lvl"]))
        return ({"soy": int(r["soy"]) - 1, "cow_ready": now + secs}, "گاو سویا خورد 🫘", {"kind": "feed"})
    if action == "milk":
        cr = float(r["cow_ready"] or 0)
        if cr <= 0:
            raise _ApiError("گاو گرسنه‌ست؛ اول بهش سویا بده")
        if now < cr:
            raise _ApiError("شیر هنوز آماده نیست")
        m = _farm_milk_amount(int(r["cow_lvl"]))
        if m > free:
            raise _ApiError(f"انبار جا نداره (برای شیر {m} جای خالی لازمه)؛ چیزی بفروش یا انبار رو ارتقا بده")
        return ({"milk": int(r["milk"]) + m, "cow_ready": 0}, f"{m} شیر دوشیده شد 🥛", {"kind": "milk", "n": m})
    if action == "sell":
        item = str(data.get("item") or "")
        if item not in FARM_COL_ITEMS:
            raise _ApiError("کالای نامعتبر")
        have = int(r[item])
        q = data.get("qty")
        qty = have if (q in (None, "all")) else _int(q, 0, 0, 10**6)
        if qty is None or qty <= 0 or have <= 0:
            raise _ApiError("چیزی برای فروش نیست")
        qty = min(qty, have)
        gain = qty * FARM_PRICE[item]
        return ({item: have - qty, "coins": int(r["coins"]) + gain},
                f"{qty} {FARM_ITEM_FA[item]} فروخته شد: +{gain} سکه 🪙", {"kind": "sell", "n": qty, "gain": gain})
    if action == "upgrade":
        what = str(data.get("what") or "")
        if what not in FARM_UP_COST:
            raise _ApiError("ارتقای نامعتبر")
        col = {"barn": "barn_lvl", "field": "field_lvl", "cow": "cow_lvl"}[what]
        lvl = int(r[col])
        if lvl >= FARM_MAX_LVL:
            raise _ApiError("به آخرین سطح رسیده")
        cost = FARM_UP_COST[what][lvl - 1]
        if int(r["coins"]) < cost:
            raise _ApiError(f"برای این ارتقا {cost} سکه لازمه")
        return ({col: lvl + 1, "coins": int(r["coins"]) - cost},
                f"{FARM_UP_NAME[what]} به سطح {lvl + 1} رسید ⭐", {"kind": "upgrade", "what": what})
    if action == "reset":
        return ({"coins": FARM_START_COINS, "wheat": 0, "soy": FARM_START_SOY, "milk": 0, "corn": 0, "xp": 0, "ext": "{}",
                 "barn_lvl": 1, "field_lvl": 1, "cow_lvl": 1, "crop": None, "crop_at": 0, "crop_ready": 0, "cow_ready": 0},
                "مزرعه از اول شروع شد", {"kind": "reset"})
    raise _ApiError("عملیات نامعتبر")


_FARM_A2 = ("make", "collect", "deliver", "sellx", "buyplot")


def _farm_apply2(action: str, row, data: dict, now: float):
    """کارگاه‌ها (نانوایی/لبنیات)، سفارش مشتری‌ها و فروش محصولات ساخته‌شده."""
    r = dict(row)
    e = _farm_ext(r)
    plv = _farm_plv(int(r.get("xp") or 0))
    inv = _farm_inv(r, e)
    free = _farm_cap(int(r["barn_lvl"])) - sum(inv.values())
    st = {"coins": int(r["coins"])}

    def out(msg, fx):
        upd = {k: inv[k] for k in FARM_COL_ITEMS if inv[k] != int(r.get(k) or 0)}
        e["items"] = {k: inv[k] for k in FARM_XTRA if inv[k]}
        upd["ext"] = json.dumps(e, ensure_ascii=False)
        if st["coins"] != int(r["coins"]):
            upd["coins"] = st["coins"]
        return upd, msg, fx

    if action == "make":
        key = str(data.get("r") or "")
        rc = FARM_RECIPES.get(key)
        if not rc:
            raise _ApiError("دستور تولید نامعتبره")
        if plv < max(rc["lvl"], FARM_BLD_LVL[rc["b"]]):
            raise _ApiError(f"این دستور در سطح {max(rc['lvl'], FARM_BLD_LVL[rc['b']])} باز میشه")
        if e["prod"].get(rc["b"]):
            raise _ApiError("این کارگاه الان مشغوله")
        for k, n in rc["in"].items():
            if inv[k] < n:
                raise _ApiError(f"{FARM_ITEM_FA[k]} کافی نداری")
        for k, n in rc["in"].items():
            inv[k] -= n
        e["prod"][rc["b"]] = {"r": key, "ready": now + rc["secs"]}
        return out(f"{rc['name']} در حال تولیده 🍳", {"kind": "make", "r": key})
    if action == "collect":
        b = str(data.get("b") or "")
        job = e["prod"].get(b)
        if not job:
            raise _ApiError("چیزی در حال تولید نیست")
        if now < float(job["ready"]):
            raise _ApiError("هنوز آماده نیست")
        if free < 1:
            raise _ApiError("انبار جا نداره؛ چیزی بفروش یا انبار رو ارتقا بده")
        inv[job["r"]] += 1
        del e["prod"][b]
        return out(f"{FARM_ITEM_FA[job['r']]} آماده شد و رفت تو انبار ✅", {"kind": "collect", "r": job["r"]})
    if action == "deliver":
        oid = _int(data.get("id"), 0, 0, 10**9)
        od = next((o for o in e["orders"] if o["id"] == oid), None)
        if od is None:
            raise _ApiError("این سفارش دیگه نیست")
        for k, n in od["need"].items():
            if inv.get(k, 0) < n:
                raise _ApiError(f"{FARM_ITEM_FA[k]} کافی نداری")
        for k, n in od["need"].items():
            inv[k] -= n
        st["coins"] += int(od["coins"])
        e["orders"].remove(od)
        e["next_at"] = now + 20
        return out(f"سفارش تحویل شد: +{od['coins']} سکه 🪙 +{od['xp']} ⭐", {"kind": "deliver", "coins": od["coins"], "xp": od["xp"]})
    if action == "sellx":
        item = str(data.get("item") or "")
        if item not in FARM_XTRA:
            raise _ApiError("کالای نامعتبر")
        have = inv[item]
        q = data.get("qty")
        qty = have if (q in (None, "all")) else _int(q, 0, 0, 10**6)
        if qty is None or qty <= 0 or have <= 0:
            raise _ApiError("چیزی برای فروش نیست")
        qty = min(qty, have)
        gain = qty * FARM_PRICE[item]
        inv[item] -= qty
        st["coins"] += gain
        return out(f"{qty} {FARM_ITEM_FA[item]} فروخته شد: +{gain} سکه 🪙", {"kind": "sell", "n": qty, "gain": gain})
    if action == "buyplot":
        idx = _int(data.get("i"), -1, -1, FARM_PLOT_GRID ** 2)
        owned = e["plots"]
        if idx is None or idx < 0 or idx in FARM_PLOT_CORE:
            raise _ApiError("این زمین قابل‌خرید نیست")
        if idx in owned:
            raise _ApiError("این زمین رو قبلاً خریدی")
        if len(owned) >= len(FARM_PLOT_COST):
            raise _ApiError("همه‌ی زمین‌ها مال خودته 👑")
        if not _farm_plot_open(idx, owned):
            raise _ApiError("اول یکی از زمین‌های کنارش رو بخر 🔒")
        cost = FARM_PLOT_COST[len(owned)]
        if st["coins"] < cost:
            raise _ApiError(f"برای این زمین {cost} سکه لازمه")
        st["coins"] -= cost
        e["plots"] = sorted(owned + [idx])
        return out(f"زمین جدید مال تو شد 🌳 (−{cost} سکه)", {"kind": "buyplot", "i": idx, "cost": cost})
    raise _ApiError("عملیات نامعتبر")


def _farm_xp(fx: dict) -> int:
    k = fx.get("kind")
    if k == "deliver":
        return int(fx.get("xp", 0))
    return {"plant": 1, "harvest": 4, "feed": 1, "milk": 3, "make": 2, "collect": 4, "buyplot": 12}.get(k, 0)


_FARM_COLS = frozenset({"coins", "wheat", "soy", "milk", "corn", "xp", "ext", "barn_lvl", "field_lvl", "cow_lvl", "crop", "crop_at", "crop_ready", "cow_ready"})


def _farm_check(user):
    uid = int(user["id"])
    if not (_social_staff(user) and has_perm(uid, "miniapp")):
        raise _ApiError("مزرعه فعلاً فقط برای پشتیبان‌هاست", 403)
    return uid


async def _farm_load(c, uid: int, lock: bool):
    await c.execute("INSERT INTO farm_state(uid, coins, soy, created_at) VALUES($1,$2,$3,$4) ON CONFLICT (uid) DO NOTHING",
                    uid, FARM_START_COINS, FARM_START_SOY, time.time())
    return await c.fetchrow("SELECT * FROM farm_state WHERE uid=$1" + (" FOR UPDATE" if lock else ""), uid)


async def _farm_fix(c, uid: int, row, now: float) -> dict:
    """مشتری‌های جدید (تا سقف سطح) رو می‌سازه و ذخیره می‌کنه."""
    r = dict(row)
    e = _farm_ext(r)
    if _farm_orders_fix(e, _farm_plv(int(r.get("xp") or 0)), now):
        r["ext"] = json.dumps(e, ensure_ascii=False)
        await c.execute("UPDATE farm_state SET ext=$2 WHERE uid=$1", uid, r["ext"])
    return r


async def _farm_get_state(qs, user):
    uid = _farm_check(user)
    now = time.time()
    async with pool.acquire() as c:
        async with c.transaction():
            row = await _farm_load(c, uid, True)
            row = await _farm_fix(c, uid, row, now)
    return _j({"ok": True, "state": _farm_state(row, now)})


def _farm_post(action: str):
    async def _h(data, user):
        uid = _farm_check(user)
        async with pool.acquire() as c:
            async with c.transaction():
                row = await _farm_load(c, uid, True)
                now = time.time()
                row = await _farm_fix(c, uid, row, now)
                upd, msg, fx = (_farm_apply2 if action in _FARM_A2 else _farm_apply)(action, row, data, now)
                xpg = _farm_xp(fx)
                if xpg and action != "reset":
                    old = int(row.get("xp") or 0)
                    upd["xp"] = old + xpg
                    if _farm_plv(old + xpg) > _farm_plv(old):
                        msg += f" 🎉 سطح {_farm_plv(old + xpg)}!"
                assert set(upd) <= _FARM_COLS
                if upd:
                    keys = list(upd)
                    await c.execute("UPDATE farm_state SET " + ", ".join(f"{k}=${i + 2}" for i, k in enumerate(keys)) + " WHERE uid=$1",
                                    uid, *[upd[k] for k in keys])
                row = await c.fetchrow("SELECT * FROM farm_state WHERE uid=$1", uid)
                row = await _farm_fix(c, uid, row, now)
        return _j({"ok": True, "msg": msg, "fx": fx, "state": _farm_state(row, now)})
    return _h


_FARM_GET = {"/api/farm/state": _farm_get_state}
_FARM_POST = {f"/api/farm/{a}": _farm_post(a) for a in ("plant", "harvest", "feed", "milk", "sell", "upgrade", "reset") + _FARM_A2}


# ───────────── مزرعه‌ی نقشه‌ای (farm.html) ─────────────
# هر آیتم: id → (زمان آماده‌شدن به ثانیه، سکه‌ی برداشت). کلاینت فقط id می‌فرسته؛ زمان و پاداش سمت سرور حساب میشه.
FARM_MAP_ITEMS = {
    "f0": (20, 30, "tomato", 4), "f1": (30, 50, "corn", 5), "f2": (25, 40, "wheat", 4),
    "f3": (35, 60, "cotton", 6), "f4": (40, 80, "berry", 7), "f5": (25, 40, "wheat", 4),
    "f6": (22, 34, "tomato", 5), "f7": (32, 55, "corn", 6), "f8": (42, 85, "berry", 8),
    "cow": (45, 25, "milk", 6), "sheep": (40, 20, "wool", 6), "pig": (35, 15, "truffle", 5),
    "hen": (20, 8, "egg", 3), "duck": (25, 10, "egg", 3), "goat": (40, 18, "milk", 5),
}
FARM_MAP_PRODUCTS = {"tomato": "🍅 گوجه", "corn": "🌽 ذرت", "wheat": "🌾 گندم", "cotton": "🧶 پنبه",
                     "berry": "🫐 بلوبری", "milk": "🥛 شیر", "wool": "🧶 پشم", "truffle": "🍄 قارچ", "egg": "🥚 تخم‌مرغ"}
FARM_MAP_LEVEL_XP = [0, 30, 90, 180, 320, 500, 730, 1010, 1340, 1720, 2150, 2630, 3160, 3740, 4370, 5050]
FARM_MAP_MIN_LEVEL = {"f0":1,"f1":3,"f2":1,"f3":6,"f4":7,"f5":1,"f6":3,"f7":5,"f8":7,"cow":1,"sheep":6,"pig":3,"hen":1,"duck":2,"goat":5}
FARM_MAP_UNLOCKS = {
    1: ["خانه و زمین‌های آغازین"], 2: ["مرغداری و تخم‌مرغ"], 3: ["کارگاه نان و غرفه دوم"],
    4: ["گاو و تولید شیر"], 5: ["کارخانه لبنیات"], 6: ["گوسفند و تولید پشم"],
    7: ["باغ بلوبری و محصولات ویژه"], 8: ["بازار بزرگ و مشتری‌های بیشتر"],
    9: ["اصطبل پیشرفته"], 10: ["کارخانه دوم و زمین‌های تازه"],
    11: ["باغ میوه"], 12: ["عمارت کشاورزی"], 13: ["تالار بزرگ"], 14: ["زمین‌های طلایی"], 15: ["مزرعه افسانه‌ای"]
}

def _farm_map_unpack(row):
    try: t = json.loads(row["t"] or "{}")
    except Exception: t = {}
    if not isinstance(t, dict): t = {}
    t.setdefault("xp", 0); t.setdefault("inventory", {}); t.setdefault("orders", []); t.setdefault("order_seq", 0); t.setdefault("timers", {k:v for k,v in t.items() if k in FARM_MAP_ITEMS})
    return t

def _farm_map_level(xp):
    return max(1, min(len(FARM_MAP_LEVEL_XP), 1 + sum(1 for x in FARM_MAP_LEVEL_XP[1:] if xp >= x)))

def _farm_map_make_order(t, level):
    pool = ["wheat", "tomato", "milk", "egg"]
    if level >= 3: pool += ["corn"]
    if level >= 6: pool += ["wool"]
    if level >= 7: pool += ["berry"]
    if level >= 8: pool += ["cotton", "truffle"]
    need = {}
    for k in random.sample(pool, min(len(pool), random.choice([1, 1, 2]))):
        need[k] = random.randint(1, min(3, 1 + level // 4))
    t["order_seq"] = int(t.get("order_seq", 0)) + 1
    worth = sum(FARM_MAP_ITEMS[next((i for i,v in FARM_MAP_ITEMS.items() if v[2] == k), "f0")][1] for k in need)
    return {"id": t["order_seq"], "who": random.choice(["مادربزرگ", "آشپز", "کشاورز", "گردشگر", "فروشنده"]),
            "need": need, "coins": max(35, worth * 2), "xp": 12 + 4 * sum(need.values())}

def _farm_map_out(row, now: float) -> dict:
    t = _farm_map_unpack(row); xp = int(t.get("xp", 0)); level = _farm_map_level(xp)
    # سفارش‌های فعال را تا سقف متناسب با سطح نگه می‌داریم.
    if not t["orders"]: t["orders"] = [_farm_map_make_order(t, level)]
    next_xp = FARM_MAP_LEVEL_XP[level] if level < len(FARM_MAP_LEVEL_XP) else None
    return {"ok": True, "now": now, "coins": int(row["coins"]), "t": {k: v for k, v in t.items() if k not in ("inventory", "orders")},
            "level": level, "xp": xp, "xp_next": next_xp, "inventory": t["inventory"], "orders": t["orders"],
            "unlocks": [v for lv, vals in FARM_MAP_UNLOCKS.items() if lv <= level for v in vals],
            "unlock_level": {str(k): v for k, v in FARM_MAP_UNLOCKS.items()}}

async def _farm_map_load(c, uid: int):
    await c.execute("INSERT INTO farm_map(uid, coins, created_at) VALUES($1,0,$2) ON CONFLICT (uid) DO NOTHING", uid, time.time())
    return await c.fetchrow("SELECT coins, t FROM farm_map WHERE uid=$1 FOR UPDATE", uid)

async def _g_farm_map_state(qs, user):
    uid, _bal = await _mini_ctx(user)
    async with pool.acquire() as c:
        async with c.transaction():
            row = await _farm_map_load(c, uid)
            t = _farm_map_unpack(row); level = _farm_map_level(int(t.get("xp", 0)))
            if not t["orders"]:
                t["orders"] = [_farm_map_make_order(t, level)]
                await c.execute("UPDATE farm_map SET t=$2 WHERE uid=$1", uid, json.dumps(t))
                row = await c.fetchrow("SELECT coins,t FROM farm_map WHERE uid=$1", uid)
    return _j(_farm_map_out(row, time.time()))

async def _p_farm_map_collect(data, user):
    uid, _bal = await _mini_ctx(user); iid = str(data.get("id") or "")
    base = iid.split("_")[0]
    if base not in FARM_MAP_ITEMS: raise _ApiError("آیتم نامعتبره")
    secs, reward, product, xp_gain = FARM_MAP_ITEMS[base]
    now = time.time()
    async with pool.acquire() as c:
        async with c.transaction():
            row = await _farm_map_load(c, uid); t = _farm_map_unpack(row)
            level = _farm_map_level(int(t.get("xp", 0)))
            if level < FARM_MAP_MIN_LEVEL.get(base, 1): raise _ApiError(f"این بخش در سطح {FARM_MAP_MIN_LEVEL.get(base, 1)} باز میشه 🔒")
            timers = t.get("timers", {})
            if now - float(timers.get(iid, 0)) < secs: raise _ApiError("هنوز آماده نیست؛ کمی صبر کن 🌱")
            inv = t["inventory"]; inv[product] = int(inv.get(product, 0)) + 1
            timers[iid] = now; t["timers"] = timers
            t["xp"] = int(t.get("xp", 0)) + xp_gain
            level = _farm_map_level(t["xp"])
            t["orders"] = t.get("orders", []) or [_farm_map_make_order(t, level)]
            await c.execute("UPDATE farm_map SET t=$2 WHERE uid=$1", uid, json.dumps(t))
            row = await c.fetchrow("SELECT coins,t FROM farm_map WHERE uid=$1", uid)
    out = _farm_map_out(row, now); out["gained_xp"] = xp_gain; out["product"] = product
    out["gained"] = 0
    return _j(out)

async def _p_farm_map_deliver(data, user):
    uid, _bal = await _mini_ctx(user); oid = int(data.get("order_id") or 0); now = time.time()
    async with pool.acquire() as c:
        async with c.transaction():
            row = await _farm_map_load(c, uid); t = _farm_map_unpack(row)
            orders = t.get("orders", []); order = next((o for o in orders if int(o.get("id", 0)) == oid), None)
            if not order: raise _ApiError("این سفارش دیگه فعال نیست")
            inv = t["inventory"]
            missing = [FARM_MAP_PRODUCTS.get(k, k) + " ×" + str(n-int(inv.get(k,0))) for k,n in order["need"].items() if int(inv.get(k,0)) < int(n)]
            if missing: raise _ApiError("هنوز این محصولات رو نداری: " + "، ".join(missing))
            for k,n in order["need"].items(): inv[k] = int(inv.get(k,0))-int(n)
            t["xp"] = int(t.get("xp",0)) + int(order.get("xp",10))
            orders.remove(order); level = _farm_map_level(t["xp"])
            orders.append(_farm_map_make_order(t, level))
            await c.execute("UPDATE farm_map SET coins=coins+$2,t=$3 WHERE uid=$1", uid, int(order["coins"]), json.dumps(t))
            row = await c.fetchrow("SELECT coins,t FROM farm_map WHERE uid=$1", uid)
    out = _farm_map_out(row, now); out["delivered"] = True; out["gained"] = int(order["coins"]); return _j(out)

_FARM_GET["/api/farm/map/state"] = _g_farm_map_state
_FARM_POST["/api/farm/map/collect"] = _p_farm_map_collect
_FARM_POST["/api/farm/map/deliver"] = _p_farm_map_deliver


