# ───────────── Arena 1v1 (server-authoritative combat) ─────────────
def _arena_out(r, uid):
    d=dict(r); uid=int(uid)
    players=[{"uid":int(d["p1"]),"name":d["p1_name"],"gender":d.get("p1_gender") or "male","x":float(d["p1_x"]),"y":float(d["p1_y"]),"hp":int(d["p1_hp"]),"face":int(d["p1_face"]),"attack_at":float(d["p1_attack"] or 0),"guard_until":float(d.get("p1_guard_until") or 0),"hit_until":0},
             ({"uid":int(d["p2"]),"name":d["p2_name"],"gender":d.get("p2_gender") or "female","x":float(d["p2_x"]),"y":float(d["p2_y"]),"hp":int(d["p2_hp"]),"face":int(d["p2_face"]),"attack_at":float(d["p2_attack"] or 0),"guard_until":float(d.get("p2_guard_until") or 0),"hit_until":0} if d.get("p2") else None)]
    return {"id":int(d["id"]),"status":d["status"],"map":int(d["map"]),"players":players,"winner":int(d["winner"]) if d.get("winner") else None,"side":0 if uid==int(d["p1"]) else 1}

async def _arena_profile_get(qs,user):
    uid=int(user["id"])
    row=await pool.fetchrow("SELECT gender,display_name FROM arena_profiles WHERE uid=$1",uid)
    stats=await pool.fetchrow("SELECT wins,losses,matches FROM arena_stats WHERE uid=$1",uid)
    return _j({"ok":True,"profile":{"gender":(row["gender"] if row else None),"name":((row["display_name"] or "") if row else "")},"stats":{"wins":int(stats["wins"]) if stats else 0,"losses":int(stats["losses"]) if stats else 0,"matches":int(stats["matches"]) if stats else 0}})

async def _arena_profile_save(data,user):
    uid=int(user["id"]); gender=str(data.get("gender") or "").lower()
    if gender not in ("male","female"): raise _ApiError("لطفاً یکی از دو جنسیت کاراکتر را انتخاب کن")
    name=" ".join(str(data.get("name") or user.get("first_name") or "بازیکن").split())[:24]
    if not name: name="بازیکن"
    await pool.execute("INSERT INTO arena_profiles(uid,gender,display_name,updated_at) VALUES($1,$2,$3,$4) ON CONFLICT(uid) DO UPDATE SET gender=EXCLUDED.gender,display_name=EXCLUDED.display_name,updated_at=EXCLUDED.updated_at",uid,gender,name,time.time())
    stats=await pool.fetchrow("SELECT wins,losses,matches FROM arena_stats WHERE uid=$1",uid)
    return _j({"ok":True,"profile":{"gender":gender,"name":name},"stats":{"wins":int(stats["wins"]) if stats else 0,"losses":int(stats["losses"]) if stats else 0,"matches":int(stats["matches"]) if stats else 0}})

async def _arena_join(data,user):
    uid=int(user["id"])
    profile=await pool.fetchrow("SELECT gender,display_name FROM arena_profiles WHERE uid=$1",uid)
    if not profile: raise _ApiError("اول پروفایل آرنا و جنسیت کاراکترت رو انتخاب کن")
    gender=profile["gender"] if profile["gender"] in ("male","female") else "male"
    name=(profile["display_name"] or str(user.get("first_name") or "بازیکن"))[:32]
    async with pool.acquire() as c:
      async with c.transaction():
        await c.execute("SELECT pg_advisory_xact_lock(714202611)")
        old=await c.fetchrow("SELECT * FROM arena_matches WHERE status IN ('waiting','playing') AND (p1=$1 OR p2=$1) ORDER BY id DESC LIMIT 1 FOR UPDATE",uid)
        if old: return _j({"ok":True,"match":_arena_out(old,uid),"side":0 if uid==old['p1'] else 1})
        waiting=await c.fetchrow("SELECT * FROM arena_matches WHERE status='waiting' AND p1<>$1 AND created_at>$2 ORDER BY id LIMIT 1 FOR UPDATE",uid,time.time()-90)
        if waiting:
          await c.execute("UPDATE arena_matches SET p2=$2,p2_name=$3,p2_gender=$4,status='playing',updated_at=$5 WHERE id=$1",waiting['id'],uid,name,gender,time.time())
          row=await c.fetchrow("SELECT * FROM arena_matches WHERE id=$1",waiting['id'])
        else:
          m=max(0,min(3,int(data.get('map',0))))
          row=await c.fetchrow("INSERT INTO arena_matches(map,p1,p1_name,p1_gender,created_at,updated_at) VALUES($1,$2,$3,$4,$5,$5) RETURNING *",m,uid,name,gender,time.time())
    return _j({"ok":True,"match":_arena_out(row,uid),"side":0 if uid==row['p1'] else 1})

async def _arena_state(qs,user):
    uid=int(user['id']); mid=int(qs.get('match_id') or 0)
    row=await pool.fetchrow("SELECT * FROM arena_matches WHERE id=$1 AND (p1=$2 OR p2=$2)",mid,uid)
    if not row: raise _ApiError("مسابقه پیدا نشد",404)
    if row['status']=='waiting' and time.time()-float(row['created_at'])>120:
      await pool.execute("UPDATE arena_matches SET status='done',updated_at=$2 WHERE id=$1 AND status='waiting'",mid,time.time())
      row=await pool.fetchrow("SELECT * FROM arena_matches WHERE id=$1",mid)
    return _j({"ok":True,"match":_arena_out(row,uid)})

async def _arena_action(data,user):
    uid=int(user['id']); mid=int(data.get('match_id') or 0); kind=str(data.get('kind') or 'move')
    if kind not in ('move','attack','defend'): raise _ApiError('حرکت نامعتبره')
    now=time.time()
    async with pool.acquire() as c:
      async with c.transaction():
        row=await c.fetchrow("SELECT * FROM arena_matches WHERE id=$1 FOR UPDATE",mid)
        if not row or row['status']!='playing' or uid not in (row['p1'],row['p2']): raise _ApiError('مسابقه فعال نیست')
        a=uid==row['p1']; ix='p1' if a else 'p2'; ox='p2' if a else 'p1'
        raw_x=max(.06,min(.94,float(data.get('x',row[ix+'_x'])))); raw_y=max(.2,min(.88,float(data.get('y',row[ix+'_y']))))
        # حرکت سمت سرور محدود می‌شود تا کلاینت نتواند تلپورت کند.
        old_x=float(row[ix+'_x']); old_y=float(row[ix+'_y'])
        x=old_x+max(-.045,min(.045,raw_x-old_x)); y=old_y+max(-.035,min(.035,raw_y-old_y))
        face=max(-1,min(1,int(data.get('face') or row[ix+'_face'])))
        updates={ix+'_x':x,ix+'_y':y,ix+'_face':face,'updated_at':now}
        if kind=='attack':
          if now-float(row[ix+'_attack'])<.55: raise _ApiError('کمی صبر کن و دوباره حمله کن')
          dist=((x-float(row[ox+'_x']))**2+(y-float(row[ox+'_y']))**2)**.5
          facing=(float(row[ox+'_x'])-x)*face>=-.03
          if dist<=.19 and facing:
            damage=4 if float(row.get(ox+'_guard_until') or 0)>now else 12
            hp=max(0,int(row[ox+'_hp'])-damage);updates[ox+'_hp']=hp
            if hp<=0: updates['status']='done';updates['winner']=uid
          updates[ix+'_attack']=now
        if kind=='defend': updates[ix+'_guard_until']=now+.65
        sets=[];vals=[mid]
        for k,v in updates.items(): vals.append(v);sets.append(f"{k}=${len(vals)}")
        await c.execute("UPDATE arena_matches SET "+','.join(sets)+" WHERE id=$1",*vals)
        row=await c.fetchrow("SELECT * FROM arena_matches WHERE id=$1",mid)
        if row['status']=='done' and row.get('winner'):
          win=int(row['winner']);lose=int(row['p2'] if win==row['p1'] else row['p1'])
          await c.execute("INSERT INTO arena_stats(uid,wins,losses,matches) VALUES($1,1,0,1) ON CONFLICT(uid) DO UPDATE SET wins=arena_stats.wins+1,matches=arena_stats.matches+1",win)
          await c.execute("INSERT INTO arena_stats(uid,wins,losses,matches) VALUES($1,0,1,1) ON CONFLICT(uid) DO UPDATE SET losses=arena_stats.losses+1,matches=arena_stats.matches+1",lose)
    return _j({"ok":True,"match":_arena_out(row,uid)})

async def _arena_leave(data,user):
    uid=int(user['id']);mid=int(data.get('match_id') or 0)
    async with pool.acquire() as c:
      async with c.transaction():
        r=await c.fetchrow("SELECT * FROM arena_matches WHERE id=$1 FOR UPDATE",mid)
        if r and r['status'] in ('waiting','playing') and uid in (r['p1'],r['p2']):
          winner=int(r['p2'] if uid==r['p1'] else r['p1']) if r['p2'] else None
          await c.execute("UPDATE arena_matches SET status='done',winner=$2,updated_at=$3 WHERE id=$1",mid,winner,time.time())
    return _j({"ok":True})

_ARENA_GET={'/api/arena/state':_arena_state,'/api/arena/profile':_arena_profile_get}
_ARENA_POST={'/api/arena/profile':_arena_profile_save,'/api/arena/join':_arena_join,'/api/arena/action':_arena_action,'/api/arena/leave':_arena_leave}

_JOIN_OK: dict = {}   # آیدی کاربر → تا کی عضویتش تایید شده (کش ۲ دقیقه‌ای؛ نتیجه‌ی منفی کش نمیشه)


# Embedded fallback assets: the arena still works if Railway deploys bot.py without the folder.
_ARENA_ASSET_B64 = {
    "hero0.png": "",
    "hero1.png": "",
    "map0.jpg": "",
    "map1.jpg": "",
    "map2.jpg": "",
    "map3.jpg": ""
}

async def _web_route(method: str, path: str, qs: dict, headers: dict, body: bytes):
    """(status, content-type, body bytes, extra headers)"""
    if path in ("/", "/index.html"):
        return 200, "text/html; charset=utf-8", WEBAPP_HTML.encode(), {}
    if path.startswith("/arena-assets/"):
        import base64 as _b64
        _name = path.rsplit("/", 1)[-1]
        _f = Path(__file__).resolve().parent / "arena_assets" / _name
        if not _f.is_file() and _name not in _ARENA_ASSET_B64:
            return 404, "text/plain", b"not found", {}
        if _f.is_file():
            _data = _f.read_bytes()
        else:
            _data = _b64.b64decode(_ARENA_ASSET_B64[_name])
        _ctype = "image/png" if _name.endswith(".png") else "image/jpeg"
        return 200, _ctype, _data, {"Cache-Control":"public, max-age=86400", "Access-Control-Allow-Origin":"*"}
    if path == "/health":
        return 200, "text/plain", b"ok", {}
    if path == "/farm" and FARM_MAP_HTML:
        return 200, "text/html; charset=utf-8", FARM_MAP_HTML, {"Cache-Control": "no-cache"}
    if path == "/farm/scene.jpg":
        return 200, "image/jpeg", FARM_SCENE_BYTES, {"Cache-Control": "public, max-age=86400"}
    if not path.startswith("/api/"):
        return 404, "text/plain", b"not found", {}
    user = _verify_init_data(headers.get("x-init-data", ""))
    if user is None:
        return _j({"error": "نشست تلگرام معتبر نیست؛ مینی‌اپ را از داخل تلگرام باز کن"}, 403)
    # محروم‌ها و کسایی که عضو کانال‌های اجباری نیستن نباید از مینی‌اپ استفاده کنن (مالک‌ها و پشتیبان‌ها معاف)
    _gid = int(user["id"])
    if _gid not in ADMIN_IDS and _gid not in OWNER_IDS:
        _bu = BANNED.get(_gid, 0)
        if _bu > time.time():
            return _j({"error": f"🚫 تو از ربات سکوت زده شدی ({_ban_until_txt(_bu)}) و اینجا دنبال چی می‌گردی؟ 😏 تا وقتی محرومی به مینی‌اپ دسترسی نداری.",
                       "blocked": "ban"}, 403)
        if BOT_REF is not None and _JOIN_OK.get(_gid, 0) < time.time():
            _miss = await missing_channels(BOT_REF, _gid)
            if _miss:
                return _j({"error": "برای استفاده از مینی‌اپ باید اول توی کانال‌های اجباری عضو بشی.",
                           "blocked": "join", "channels": _miss}, 403)
            _JOIN_OK[_gid] = time.time() + 120
    social = path.startswith("/api/social/")
    game = path.startswith("/api/game/")
    farm = path.startswith("/api/farm/")
    arena = path.startswith("/api/arena/")
    # آرنا فعلاً دقیقاً مانند بخش‌های پشتیبانی، فقط برای صاحب ربات/پشتیبان دارای مجوز miniapp باز است.
    if arena:
        _arena_uid = int(user["id"])
        if not (_social_staff(user) and has_perm(_arena_uid, "miniapp")):
            return _j({"error": "آرنا فعلاً فقط برای حساب‌های پشتیبانی فعال است."}, 403)
    if path.startswith("/api/game/crash/") and not crash_allowed(int(user["id"])):
        return _j({"error": "این بخش غیرفعال شده"}, 403)   # همون کلید موشکِ ربات (CRASH_PUBLIC)   # بازی‌های مینی‌اپ: برای همه‌ی کاربرای ثبت‌نام‌شده
    # پنل پشتیبانی: صاحب ربات و فقط پشتیبان‌های دارای مجوز panel.
    # API اجتماعی جداست و طبق قواعد خودش برای کاربران واردشده بررسی می‌شود.
    # عکس پروفایل کاربرها (نه گروه‌ها) برای همه‌ی کاربرهای مینی‌اپ بازه؛ بدونش آواتارِ بقیه هیچ‌وقت نمی‌اومد
    public_avatar = path == "/api/avatar" and not qs.get("chat")
    if not social and not game and not farm and not arena and not public_avatar and not path.startswith("/api/myself") :
        _uid = int(user["id"])
        if not (has_perm(_uid, "panel") and has_perm(_uid, "miniapp")):
            return _j({"error": "برای پنل پشتیبانی دسترسی نداری"}, 403)
        _need_p = _API_PERM.get(path)
        if _need_p and not any(has_perm(_uid, p) for p in _need_p):
            return _j({"error": "این بخش برای حساب تو فعال نیست."}, 403)
    if pool is None:
        return _j({"error": "دیتابیس هنوز آماده نیست"}, 503)
    try:
        if method in ("GET", "HEAD"):
            fn = (_SOCIAL_GET if social else _ARENA_GET if arena else _FARM_GET if farm else _GAME_GET if game else _GET).get(path)
            if fn:
                return await fn(qs, user)
        elif method == "POST":
            fn = (_SOCIAL_POST if social else _ARENA_POST if arena else _FARM_POST if farm else _GAME_POST if game else _POST).get(path)
            if fn:
                try:
                    data = json.loads(body.decode("utf-8") or "{}")
                except Exception:
                    raise _ApiError("بدنه‌ی درخواست نامعتبره")
                if not isinstance(data, dict):
                    raise _ApiError("بدنه‌ی درخواست نامعتبره")
                return await fn(data, user)
    except _ApiError as e:
        return _j({"error": str(e)}, e.status)
    except Exception:
        log.exception("api error %s", path)
        return _j({"error": "خطای داخلی سرور"}, 500)
    return _j({"error": "not found"}, 404)


async def _http_conn(reader, writer):
    import gzip
    import urllib.parse
    from http import HTTPStatus
    status, ctype, body, extra, method, headers = 500, "text/plain", b"error", {}, "GET", {}
    try:
        head = await asyncio.wait_for(reader.readuntil(b"\r\n\r\n"), 10)
        lines = head.decode("latin1").split("\r\n")
        method, target, _v = lines[0].split(" ", 2)
        headers = {k.strip().lower(): v.strip() for k, v in (l.split(":", 1) for l in lines[1:] if ":" in l)}
        clen = _int(headers.get("content-length"), 0, 0)
        if method not in ("GET", "HEAD", "POST"):
            status, ctype, body, extra = 405, "text/plain", b"method not allowed", {}
        elif clen > (5_500_000 if urllib.parse.urlsplit(target).path in ("/api/social/post", "/api/social/story", "/api/social/subscription/receipt", "/api/social/store/order", "/api/emoji/create") else 200_000):
            status, ctype, body, extra = 413, "text/plain", b"too large", {}
        else:
            raw = await asyncio.wait_for(reader.readexactly(clen), 15 if clen < 300_000 else 90) if clen else b""
            url = urllib.parse.urlsplit(target)
            status, ctype, body, extra = await _web_route(method, url.path, dict(urllib.parse.parse_qsl(url.query)), headers, raw)
    except Exception:
        log.warning("webapp request failed", exc_info=True)
    try:
        hdr = {"Content-Type": ctype, "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff",
               "Referrer-Policy": "no-referrer", "Connection": "close", **extra}
        if len(body) > 1200 and (ctype.startswith("text/") or ctype.startswith("application/json")) \
                and "gzip" in headers.get("accept-encoding", ""):
            body = gzip.compress(body, 5)
            hdr["Content-Encoding"] = "gzip"
            hdr["Vary"] = "Accept-Encoding"
        hdr["Content-Length"] = str(len(body))
        try:
            reason = HTTPStatus(status).phrase
        except ValueError:
            reason = "Error"
        out = f"HTTP/1.1 {status} {reason}\r\n" + "".join(f"{k}: {v}\r\n" for k, v in hdr.items()) + "\r\n"
        writer.write(out.encode("latin1") + (b"" if method == "HEAD" else body))
        await writer.drain()
    except Exception:
        pass
    finally:
        try:
            writer.close()
        except Exception:
            pass


async def start_webapp():
    """سرور کوچک مینی‌اپ (بدون نیاز به پکیج جدید). Railway پورتش رو تو PORT میده."""
    port = int(os.environ.get("PORT", "8080"))
    srv = await asyncio.start_server(_http_conn, "0.0.0.0", port)
    log.info("webapp listening on :%s (WEBAPP_URL=%s)", port, WEBAPP_URL or "—")
    return srv



async def mini_crash_round_loop():
    """ایجاد دورهای سراسری موشک در تمام زمان اجرا، حتی وقتی کسی صفحه بازی را باز نکرده."""
    while True:
        try:
            now = time.time()
            rid = int(now // MINI_CRASH_DELAY)
            starts_at = (rid + 1) * MINI_CRASH_DELAY
            await pool.execute(
                "INSERT INTO mini_crash_rounds(round_id,starts_at,crash_point,created_at) VALUES($1,$2,$3,$4) "
                "ON CONFLICT(round_id) DO NOTHING", rid, starts_at, _mini_crash_point(), now)
            # فقط تاریخچه محدود نگه داشته شود؛ دورهای دارای شرط در mini_games اطلاعات لازم را دارند.
            await pool.execute("DELETE FROM mini_crash_rounds WHERE round_id < $1", rid - 120)
            # سوابق: ضریب انفجار همه‌ی پروازهای تموم‌شده (چه کسی شرط بسته باشه چه نه)
            fin = await pool.fetch("SELECT crash_point, starts_at FROM mini_crash_rounds WHERE starts_at <= $1 ORDER BY round_id DESC LIMIT 40", now)
            _MINI_HIST[:] = [float(x["crash_point"]) for x in fin
                             if now >= float(x["starts_at"]) + _mini_time_for(float(x["crash_point"]))][:30]
        except asyncio.CancelledError:
            raise
        except Exception:
            log.warning("mini crash round scheduler failed", exc_info=True)
        await asyncio.sleep(0.35)

async def jagsal_expiry_loop():
    """پایان خودکار گفت‌وگو پس از ۱۲ دقیقه."""
    while True:
        try:
            now = time.time()
            rows = await pool.fetch("SELECT * FROM jagsal_sessions WHERE status='connected' AND expires_at IS NOT NULL AND expires_at <= $1 LIMIT 50", now)
            for row in rows:
                await _jagsal_end(BOT_REF, row, 0, "time_expired")
            stale = await pool.fetch("SELECT session_id, source_chat FROM jagsal_sessions WHERE status='waiting' AND created_at <= $1 LIMIT 50", now - 600)
            for row in stale:
                await _jagsal_cancel_waiting(BOT_REF, row)
        except asyncio.CancelledError:
            raise
        except Exception:
            log.warning("jagsal expiry loop failed", exc_info=True)
        await asyncio.sleep(3)


async def startup(app: Application):
    """موقع روشن شدن: دیتابیس رو آماده می‌کنه و به پشتیبان‌ها تو تلگرام خبر میده (بدون نیاز به لاگ Railway)."""
    global BOT_REF
    BOT_REF = app.bot
    try:
        await init_db(app)
        await start_support_userbot()
        app.bot_data["car_task"] = asyncio.create_task(car_profit_loop())
        app.bot_data["energy_task"] = asyncio.create_task(energy_decay_loop())
        app.bot_data["bank_interest_task"] = asyncio.create_task(bank_interest_loop())
        try:
            from telegram import MenuButtonDefault, MenuButtonWebApp
            await app.bot.delete_my_commands(scope=BotCommandScopeAllPrivateChats())
            if WEBAPP_URL.startswith("https://"):   # مینی‌اپ برای همه‌ی کاربرها: دکمه‌ی کنار فیلد پیام
                await app.bot.set_chat_menu_button(menu_button=MenuButtonWebApp(text="📱 مینی‌اپ", web_app=WebAppInfo(url=WEBAPP_URL)))
            else:
                await app.bot.set_chat_menu_button(menu_button=MenuButtonDefault())
        except Exception:
            log.warning("reset commands menu failed", exc_info=True)
        app.bot_data["ref_task"] = asyncio.create_task(referral_check_loop(app))
        app.bot_data["gw_task"] = asyncio.create_task(giveaway_loop(app))
        app.bot_data["mini_crash_round_task"] = asyncio.create_task(mini_crash_round_loop())
        app.bot_data["jagsal_expiry_task"] = asyncio.create_task(jagsal_expiry_loop())
        await boss_init_db()
        app.bot_data["boss_task"] = asyncio.create_task(boss_loop(app))
        app.bot_data["house_notify_task"] = asyncio.create_task(house_notify_loop(app))
        try:
            app.bot_data["web"] = await start_webapp()
        except Exception:
            log.exception("webapp start failed")
        note = f"✅ ربات روشن شد.\nنسخه: {BOT_VERSION}"
    except Exception as e:
        log.exception("startup failed")
        note = f"❌ ربات روشن شد ولی دیتابیس وصل نشد:\n{type(e).__name__}: {str(e)[:200]}"
    for aid in ADMIN_IDS:
        try:
            await app.bot.send_message(aid, note)
        except Exception:
            log.warning("could not notify admin %s", aid)


