JM_CELLS = 10   # تعداد خونه‌های نوار پروفیت (جاهای دیگه‌ی ربات)
PANEL_BAR_CELLS = 6   # تعداد خونه‌های نوارهای پنل «خودم»؛ اگه هنوز نوار میره خط بعد، کمترش کن (مثلا 6)


def _pct_txt(p: float) -> str:
    return f"{_fmt_en(round(p, 1))}٪"


# هر نوار از سه تیکه ساخته میشه: (شروع، بدنه، ته). فقط از همین ایموجی‌ها استفاده میشه (ایموجی‌های قدیمی نوار دیگه نیستن).
# BAR_SETS = تیکه‌های قسمت پُر هر نوار | BAR_EMPTY = تیکه‌های قسمت خالی (برای هر سه نوار یکسان)
BAR_SETS = {
    "level":  ("6019611795960897325", "6019417805173039520", "6019492937035947689"),
    "jm":     ("6019552920549204941", "6019365402277061626", "6019267704655977508"),
    "energy": ("6019417633374348025", "6019616808187733402", "6019314957886168728"),
}
BAR_SETS["edu"] = ("6023742313254100760", "6021691754133069784", "6021757003276230454")   # نوار واحد تا مدرک بعدی
BAR_EMPTY = ("6019528104228166791", "6019341045517525436", "6019103233178345190")
BAR_CAP_KEY = {"selfen": "energy", "energy": "energy", "jm": "jm", "level": "level", "edu": "edu"}


def _custom_bar(section: str, pct: float, cells: int) -> str:
    """نوار بدون فاصله: خونه‌ی اول=شروع، آخر=ته، بقیه=بدنه؛ خونه‌های پُر از ست نوار، خالی‌ها از BAR_EMPTY."""
    pct = max(0.0, min(100.0, float(pct or 0)))
    filled = min(cells, math.ceil(pct / 100 * cells - 1e-9)) if pct > 0 else 0
    fset = BAR_SETS[BAR_CAP_KEY.get(section, "energy")]
    out = []
    for i in range(cells):
        part = 0 if i == 0 else (2 if i == cells - 1 else 1)
        eid = (fset if i < filled else BAR_EMPTY)[part]
        out.append(f'<tg-emoji emoji-id="{eid}">▫️</tg-emoji>')
    return "".join(out)


def _panel_bar(section: str, fill_fallback: str, empty_fallback: str, pct: float) -> str:
    """نوار پنل + درصد، همه تو یه خط (تعداد خونه‌ها = PANEL_BAR_CELLS)."""
    pct = max(0.0, min(100.0, float(pct or 0)))
    return f"{_custom_bar(section, pct, PANEL_BAR_CELLS)} {_pct_txt(pct)}"


def self_energy_line(energy) -> str:
    """نوار انرژی پنل «خودم» (ایموجی جدا از بقیه‌ی جاها)."""
    e = max(0.0, min(ENERGY_MAX, float(energy or 0)))
    return f"{ce('energy', 1, '⚡')} انرژی\n{_panel_bar('selfen', '🟨', '▫️', e / ENERGY_MAX * 100)}"


def jm_bar_line(amount) -> str:
    """نوار پروفیت (با /setemoji پروفیت ست میشه؛ اسلت ۱ = پر، ۲ = خالی). فقط نوار و درصد."""
    a = max(0, min(JM_CAP, int(amount or 0)))
    return f"{JM_CE} پروفیت\n{_panel_bar('jm', '🟪', '▫️', a / JM_CAP * 100)}"


def level_progress_pct(lvl: int, jaghs: int, work_count: int = 0) -> float:
    """درصد پیشرفت تا کاراکتر بعدی (همون منطق card_text)."""
    n = len(LEVEL_THRESHOLDS)
    if lvl >= n:
        return 100.0
    if lvl == n - 1 and jaghs >= LEVEL_THRESHOLDS[-1] and work_count < 1200:
        return min(100.0, work_count / 1200 * 100)   # آخرین پله: ۱۲۰۰ کار
    lo, hi = LEVEL_THRESHOLDS[lvl - 1], LEVEL_THRESHOLDS[lvl]
    return max(0.0, min(100.0, (jaghs - lo) / (hi - lo) * 100))


def level_bar_line(pct: float) -> str:
    """نوار سطح (با /setemoji level ست میشه؛ اسلت ۱ = پر، ۲ = خالی)."""
    return f"{ce('level', 3, '📊')} سطح\n{_panel_bar('level', '🟪', '⬜', pct)}"


def _lvl_hint(row) -> str:
    """وقتی واحدهاش برای سطح بعد کافیه ولی مدرک لازم رو نداره، بهش می‌گه مدرک بگیره."""
    try:
        units, deg = int(row["edu_units"] or 0), int(row["edu_degree"] or 0)
        lv = edu_level(units, deg)
        if lv < len(EDU_LEVEL_UNITS) and units >= EDU_LEVEL_UNITS[lv] and deg < len(EDU_DEGREES):
            return f"\n🔒 برای رفتن به سطح {lv + 1} باید مدرک «{EDU_DEGREES[deg][0]}» بگیری (از «تحصیل»)."
    except Exception:
        pass
    return ""


async def self_panel_text(uid: int, name: str = "") -> str:
    row = await get_user(uid)
    total = int(row["balance"] or 0) + int(row["bank_balance"] or 0)
    jaghs = int(row["jaghs"] or 0)
    work_count = int(row["work_count"] or 0)
    g = row["gender"]
    lvl_pct = 0.0
    if g in JOBS:
        job = current_job(g, jaghs, work_count, _jsel(row))
        lvl = row_level(row)
        char_name = CHARACTERS[g][lvl - 1][0]
        job_name = job[1] if job else "بیکار"
        lvl_pct = edu_level_pct(row["edu_units"], row["edu_degree"])   # پیشرفت سطح = واحد درسی تا سطح بعدی
        sk = await special_current(uid)
        if sk in SPECIALS:   # کاراکتر ویژه‌ی فعال (مثل محبوبیت) جای اسم کاراکتر میاد
            char_name = SPECIALS[sk]["name"]
    else:
        char_name, job_name = "جنسیت انتخاب نشده (تنظیمات ← تغییر جنسیت)", "—"
    return B(
        f"{ce('me', 1, '🎖')} {html.escape(char_name)}\n\n"
        f"💼 شغل: {html.escape(job_name)}\n"
        f"🏅 سطح {row_level(row)} · "
        f'<tg-emoji emoji-id="6023744400608206043">🎓</tg-emoji> مدرک: {html.escape(_deg_name(_edeg(row)))}\n'
        f"{MONEY_CE} دارایی کل: {total:,} تومان\n\n"
        f"{self_energy_line(row.get('energy', 0))}\n\n"
        f"{jm_bar_line(row.get('jagh_machine', 0))}\n\n"
        f"{level_bar_line(lvl_pct)}{_lvl_hint(row)}"
    )


async def send_self_panel(bot, chat_id: int, uid: int, name: str = "", reply_to: int | None = None):
    """پنل شخصی: عکس کاراکتر + کپشن + دکمه‌ها تو یه پیام."""
    row = await get_user(uid)
    text = await self_panel_text(uid, name)
    kb = self_panel_keyboard(uid, private=chat_id > 0)
    if row and row["gender"] in JOBS:
        await send_card(bot, chat_id, row, reply_to=reply_to, text=text, reply_markup=kb,
                        img_balance=int(row["balance"] or 0) + int(row["bank_balance"] or 0))
        return
    rp = ReplyParameters(message_id=reply_to, allow_sending_without_reply=True) if reply_to else None
    await bot.send_message(chat_id, text, parse_mode="HTML", reply_markup=kb, reply_parameters=rp)


async def show_self_panel(update: Update, context: ContextTypes.DEFAULT_TYPE):
    user, msg = update.effective_user, update.effective_message
    await upsert_user(user.id, user.full_name)
    await send_self_panel(context.bot, msg.chat_id, user.id, user.full_name, reply_to=msg.message_id)


