async def special_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """spc:<v|b|y|t>:<uid>:<key> — دیدن (عکس + قدرت)، خرید با تایید، فعال/غیرفعال."""
    q = update.callback_query
    try:
        _, act, uid_s, key = q.data.split(":")
        uid = int(uid_s)
    except ValueError:
        await q.answer("درخواست نامعتبره.", show_alert=True); return
    if q.from_user.id != uid:
        await q.answer("این پنل برای شما نیست.", show_alert=True); return
    gender = await _special_gender(uid)
    if not _special_allowed(key, gender):
        await q.answer("این کاراکتر برای تو در دسترس نیست.", show_alert=True); return
    sp = SPECIALS[key]
    back = [btn("🔙 برگشت به کاراکترهای ویژه", "primary", icon=EID_BACK, callback_data=f"sp:special:{uid}")]
    if act == "b":   # تایید خرید
        await q.answer()
        kb = InlineKeyboardMarkup([[btn("✅ تایید خرید", "success", callback_data=f"spc:y:{uid}:{key}"), btn("❌ انصراف", "danger", callback_data=f"spc:v:{uid}:{key}")]])
        cap = B(f"آیا «{html.escape(sp['name'])}» به قیمت {sp['price']:,} تومان (از جیب و بانک) خریداری بشه؟")
        try:
            await q.edit_message_caption(caption=cap, parse_mode="HTML", reply_markup=kb)
        except Exception:
            pass
        return
    if act == "y":
        try:
            await _p_myself_special_buy({"key": key}, {"id": uid})
            await q.answer("کاراکتر ویژه خریداری و فعال شد 👑", show_alert=True)
        except _ApiError as e:
            await q.answer(str(e), show_alert=True); return
    elif act == "t":
        try:
            await _p_myself_special_toggle({"key": key}, {"id": uid})
            await q.answer()
        except _ApiError as e:
            await q.answer(str(e), show_alert=True); return
    else:
        await q.answer()
    row = await pool.fetchrow("SELECT active FROM special_chars WHERE user_id=$1 AND key=$2", uid, key)
    any_owned = SPECIAL_ONE_ONLY and await pool.fetchval("SELECT 1 FROM special_chars WHERE user_id=$1", uid)
    cap = f"<b>{html.escape(sp['name'])}</b>\n\nقدرت: {html.escape(sp['power'])}\n{html.escape(SPECIAL_COMMON)}\n\nقیمت: {sp['price']:,} تومان (از جیب و بانک)"
    rows = []
