def _pet_ce(idx: int) -> str:
    pt = PETS[idx - 1]
    return f'<tg-emoji emoji-id="{pt["eid"]}">{pt["fb"]}</tg-emoji>'


def _pet_names_of(row) -> dict:
    try:
        d = json.loads(row["pet_names"] or "{}")
        return d if isinstance(d, dict) else {}
    except Exception:
        return {}


def _pet_name_of(row, idx: int) -> str:
    return _pet_names_of(row).get(str(idx)) or PETS[idx - 1]["name"]


def _pet_stats_of(row) -> dict:
    try:
        d = json.loads(row["pet_stats"] or "{}")
        return d if isinstance(d, dict) else {}
    except Exception:
        return {}


def _pet_st(row, idx: int, now: float | None = None) -> dict:
    """رنک، محبوبیت و شکمِ فعلیِ پتِ شماره‌ی idx (شکم با گذشت زمان کم شده)."""
    now = now or time.time()
    d = _pet_stats_of(row).get(str(idx)) or {}
    belly0 = float(d.get("belly", 50.0))   # پت تازه‌خریده نصفه گرسنه‌ست
    bt = float(d.get("bt") or now)
    belly = max(0.0, min(100.0, belly0 - max(0.0, now - bt) / 3600 * PET_BELLY_DECAY))
    return {"rank": max(1, min(4, int(d.get("rank", 1)))), "pop": int(d.get("pop", 0)), "belly": belly}


def _pet_view_idx(row) -> int:
    owned = int(row["pets_owned"] or 0)
    return 1 if owned <= 0 else max(1, min(owned, int(row["pet_active"] or 1)))


def _pet_stage(row) -> int:
    return _pet_st(row, _pet_view_idx(row))["rank"]


def _pet_upgrade_price(idx: int, rank: int) -> int | None:
    return None if rank >= 4 else PET_UPGRADE_BASE[rank - 1] * idx


def _pet_src(idx: int, stage: int):
    fid = _PET_FILEID.get((idx, stage))
    if fid:
        return fid
    for f in (PET_DIR / f"pet{idx}_{stage}.jpg", PET_DIR.parent / f"pet{idx}_{stage}.jpg"):   # تو پوشه‌ی pets یا کنار bot.py
        if f.exists():
            return f.read_bytes()
    if not _PET_WARNED.get((idx, stage)):
        _PET_WARNED[(idx, stage)] = True
        log.warning("pet image not found: pet%s_%s.jpg (looked in %s and next to bot.py)", idx, stage, PET_DIR)
    return None


def _pet_cache(idx: int, stage: int, message):
    try:
        if message is not None and getattr(message, "photo", None):
            _PET_FILEID[(idx, stage)] = message.photo[-1].file_id
    except Exception:
        pass


def _pet_cd_left(row, kind: str, now: float) -> int:
    return max(0, int(float(row[f"pet_t_{kind}"] or 0) + PET_CD[kind] - now))


def _pet_caption(row, note: str = "") -> str:
    owned = int(row["pets_owned"] or 0)
    now = time.time()
    if owned <= 0:
        return (f"<b>🐾 پت‌ها</b>\n\nهنوز پتی نداری! اولین همراهت {_pet_ce(1)} «{PETS[0]['name']}» ست — "
                f"قیمت {PET_PRICES[0]:,} تومن.\nرنک پتت رو با پول ارتقا بده تا تکامل پیدا کنه و قوی‌تر بشه.")
    idx = _pet_view_idx(row)
    st_ = _pet_st(row, idx, now)
    stage = st_["rank"]
    name = html.escape(_pet_name_of(row, idx))

    def cd(kind):
        left = _pet_cd_left(row, kind, now)
        return "آماده ✅" if left <= 0 else f"{_duration_fa(left)} دیگه"

    up = _pet_upgrade_price(idx, stage)
    nxt = f"ارتقای بعدی: {up:,} تومن" if up else "به آخرین رنک رسیده 👑"
    head = f"{note}\n\n" if note else ""
    pop_pct = min(100.0, st_["pop"] / PET_POP_CAP * 100)
    return (f"{head}{_pet_ce(idx)} <b>{name}</b> · {PETS[idx - 1]['name']} {PETS[idx - 1]['titles'][stage - 1]}\n"
            f"رنک {stage} از ۴ — {nxt}\n\n"
            f"محبوبیت\n{_panel_bar('pop', '🟪', '▫️', pop_pct)}\n\n"
            f"{PET_FEED_CE} شکم\n{_panel_bar('jm', '🟪', '▫️', st_['belly'])}\n\n"
            f"نوازش: {cd('pet')}\nغذا ({PET_FEED_COST:,}): {cd('feed')}\nگردش: {cd('walk')}\n\n"
            f"هر کاری با پت ۳ تا ۵ انرژی بهت میده.")


def _pet_kb(row, uid: int) -> InlineKeyboardMarkup:
    owned = int(row["pets_owned"] or 0)
    rows = []
    if owned > 0:
        idx = _pet_view_idx(row)
        rows.append([btn("نوازش", "success", icon=PET_PET_EID, callback_data=f"pt:pet:{uid}"),
                     btn(f"غذا ({PET_FEED_COST // 1000}k)", "primary", icon=PET_FEED_EID, callback_data=f"pt:feed:{uid}"),
                     btn("گردش", "primary", icon=PET_WALK_EID, callback_data=f"pt:walk:{uid}")])
        up = _pet_upgrade_price(idx, _pet_st(row, idx)["rank"])
        if up:
            rows.append([btn(f"⬆️ ارتقای رنک — {up:,}", "success", callback_data=f"pt:up:{uid}")])
        if owned > 1:
            act = idx
            sel = [btn(("✅ " if i == act else "") + _pet_name_of(row, i), None, icon=PETS[i - 1]["eid"], callback_data=f"pt:sel:{uid}:{i}") for i in range(1, owned + 1)]
            rows += [sel[k:k + 3] for k in range(0, len(sel), 3)]
    if owned < len(PETS):
        rows.append([btn(f"خرید {PETS[owned]['name']} — {PET_PRICES[owned]:,}", "danger", icon=PETS[owned]["eid"], callback_data=f"pt:buy:{uid}")])
    return InlineKeyboardMarkup(rows)


async def send_pet_panel(bot, chat_id: int, uid: int, reply_to=None, note: str = ""):
    row = await get_user(uid)
    cap, kb = _pet_caption(row, note), _pet_kb(row, uid)
    idx, stage = _pet_view_idx(row), _pet_stage(row)
    rp = ReplyParameters(message_id=reply_to, allow_sending_without_reply=True) if reply_to else None
    src = _pet_src(idx, stage)
    if src is not None:
        try:
            m = await bot.send_photo(chat_id, src, caption=cap, parse_mode="HTML", reply_markup=kb, reply_parameters=rp)
            _pet_cache(idx, stage, m)
            return
        except Exception:
            log.warning("pet photo send failed", exc_info=True)
    await bot.send_message(chat_id, cap, parse_mode="HTML", reply_markup=kb, reply_parameters=rp)


async def _pet_edit(q, uid: int, note: str = ""):
    row = await get_user(uid)
    cap, kb = _pet_caption(row, note), _pet_kb(row, uid)
    idx, stage = _pet_view_idx(row), _pet_stage(row)
    src = _pet_src(idx, stage)
    try:
        if src is not None and getattr(q.message, "photo", None):
            m = await q.edit_message_media(InputMediaPhoto(src, caption=cap, parse_mode="HTML"), reply_markup=kb)
            _pet_cache(idx, stage, m)
        elif getattr(q.message, "photo", None):
            await q.edit_message_caption(cap, parse_mode="HTML", reply_markup=kb)
        else:
            await q.edit_message_text(cap, parse_mode="HTML", reply_markup=kb)
    except Exception as e:
        if "not modified" not in str(e).lower():
            log.warning("pet panel edit failed", exc_info=True)


async def _pet_do(uid: int, kind: str):
    """نوازش/غذا/گردش → (status, info). status: ok | nopet | cd | poor | full"""
    now = time.time()
    async with pool.acquire() as c:
        async with c.transaction():
            r = await c.fetchrow("SELECT balance, pets_owned, pet_active, pet_names, pet_stats, pet_t_pet, pet_t_feed, pet_t_walk FROM users WHERE user_id=$1 FOR UPDATE", uid)
            if not r or int(r["pets_owned"] or 0) <= 0:
                return "nopet", None
            left = _pet_cd_left(r, kind, now)
            if left > 0:
                return "cd", left
            idx = max(1, min(int(r["pets_owned"]), int(r["pet_active"] or 1)))
            st_ = _pet_st(r, idx, now)
            if kind == "feed":
                if st_["belly"] >= 90:
                    return "full", None
                if int(r["balance"] or 0) < PET_FEED_COST:
                    return "poor", None
            gain = random.randint(*PET_ENERGY)
            cost = PET_FEED_COST if kind == "feed" else 0
            stats = _pet_stats_of(r)
            d = dict(stats.get(str(idx)) or {})
            d["rank"] = st_["rank"]
            d["pop"] = st_["pop"] + PET_POP_GAIN[kind]
            d["belly"] = min(100.0, st_["belly"] + PET_BELLY_FEED) if kind == "feed" else st_["belly"]
            d["bt"] = now
            stats[str(idx)] = d
            await c.execute(
                f"UPDATE users SET pet_t_{kind}=$1, pet_acts=pet_acts+1, balance=balance-$2, energy=LEAST(energy+$3::double precision, $4::double precision), pet_stats=$5 WHERE user_id=$6",
                now, cost, float(gain), ENERGY_MAX, json.dumps(stats), uid)
            return "ok", (gain, _pet_name_of(r, idx))


def _pet_result_text(kind: str, name: str, gain: int) -> str:
    line = random.choice(PET_LINES[kind]).format(n=f"<b>{html.escape(name)}</b>")
    return f"{PET_LEAD[kind]} {line}\n\n⚡ +{gain} انرژی" + (f" · {PET_FEED_COST:,} تومن غذا" if kind == "feed" else "")


_PET_FAIL = {"nopet": "هنوز پت نداری! بنویس «پت» و اولین پتت رو بخر.",
             "poor": f"موجودی جیبت برای غذا کافی نیست ({PET_FEED_COST:,} تومن).",
             "full": "شکم پتت الان پره؛ یکم صبر کن گرسنه بشه."}


async def pet_text(update: Update, context: ContextTypes.DEFAULT_TYPE, text: str) -> bool:
    msg, user = update.effective_message, update.effective_user
    raw = norm_word(text)
    m = re.match(r"^جینگو\s*اسم\s*پت\s+(.+)$", raw)
    key = _word_key(text)
    kinds = {"پتنوازش": "pet", "پتغذا": "feed", "پتگردش": "walk"}
    if not m and key != "پت" and key not in kinds:
        return False
    await upsert_user(user.id, user.full_name)
    rp = ReplyParameters(message_id=msg.message_id, allow_sending_without_reply=True)
    if m:
        new = m.group(1).strip()
        if not (1 <= len(new) <= 16) or "\n" in new:
            await msg.reply_text(BP("اسم پت باید بین ۱ تا ۱۶ حرف باشه."), parse_mode="HTML", reply_parameters=rp); return True
        async with pool.acquire() as c:
            async with c.transaction():
                r = await c.fetchrow("SELECT pets_owned, pet_active, pet_names FROM users WHERE user_id=$1 FOR UPDATE", user.id)
                if not r or int(r["pets_owned"] or 0) <= 0:
                    await msg.reply_text(BP(_PET_FAIL["nopet"]), parse_mode="HTML", reply_parameters=rp); return True
                idx = max(1, min(int(r["pets_owned"]), int(r["pet_active"] or 1)))
                names = _pet_names_of(r); names[str(idx)] = new
                await c.execute("UPDATE users SET pet_names=$1 WHERE user_id=$2", json.dumps(names, ensure_ascii=False), user.id)
        await msg.reply_text(B(f"از این به بعد اسم پتت «{html.escape(new)}» ـه 🐾"), parse_mode="HTML", reply_parameters=rp)
        return True
    if key == "پت":
        await send_pet_panel(context.bot, msg.chat_id, user.id, reply_to=msg.message_id)
        return True
    kind = kinds[key]
    st, info = await _pet_do(user.id, kind)
    if st == "ok":
        gain, name = info
        await _eq_say(msg, _pet_result_text(kind, name, gain))
    elif st == "cd":
        await msg.reply_text(B(f"پتت الان استراحت می‌کنه؛ {_duration_fa(info)} دیگه دوباره."), parse_mode="HTML", reply_parameters=rp)
    else:
        await msg.reply_text(B(_PET_FAIL[st]), parse_mode="HTML", reply_parameters=rp)
    return True


async def pet_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    p = q.data.split(":")
    try:
        act, uid = p[1], int(p[2])
    except (IndexError, ValueError):
        await q.answer(); return
    if q.from_user.id != uid:
        await q.answer("این پنل مال شما نیست.", show_alert=True); return
    await upsert_user(uid, q.from_user.full_name)
    if act in ("pet", "feed", "walk"):
        st, info = await _pet_do(uid, act)
        if st == "ok":
            await q.answer()
            await _pet_edit(q, uid, _pet_result_text(act, info[1], info[0]))
        elif st == "cd":
            await q.answer(f"پتت استراحت می‌کنه؛ {_duration_fa(info)} دیگه.", show_alert=True)
        else:
            await q.answer(_PET_FAIL[st], show_alert=True)
        return
    if act == "sel":
        try:
            n = int(p[3])
        except (IndexError, ValueError):
            await q.answer(); return
        r = await get_user(uid)
        if 1 <= n <= int(r["pets_owned"] or 0):
            await pool.execute("UPDATE users SET pet_active=$1 WHERE user_id=$2", n, uid)
        await q.answer(); await _pet_edit(q, uid); return
    if act == "up":
        alert = None
        async with pool.acquire() as c:
            async with c.transaction():
                r = await c.fetchrow("SELECT balance, pets_owned, pet_active, pet_stats FROM users WHERE user_id=$1 FOR UPDATE", uid)
                if int(r["pets_owned"] or 0) <= 0:
                    alert = _PET_FAIL["nopet"]
                else:
                    idx = max(1, min(int(r["pets_owned"]), int(r["pet_active"] or 1)))
                    st_ = _pet_st(r, idx)
                    price = _pet_upgrade_price(idx, st_["rank"])
                    if price is None:
                        alert = "پتت به بالاترین رنک رسیده!"
                    elif int(r["balance"] or 0) < price:
                        alert = f"موجودی جیبت کافی نیست؛ {price:,} تومن لازمه."
                    else:
                        stats = _pet_stats_of(r)
                        d = dict(stats.get(str(idx)) or {})
                        d.update(rank=st_["rank"] + 1, pop=st_["pop"], belly=st_["belly"], bt=time.time())
                        stats[str(idx)] = d
                        await c.execute("UPDATE users SET balance=balance-$1, pet_stats=$2 WHERE user_id=$3", price, json.dumps(stats), uid)
        if alert:
            await q.answer(alert, show_alert=True); return
        await q.answer("رنک پتت ارتقا پیدا کرد! ✨")
        await _pet_edit(q, uid, "پتت تکامل پیدا کرد و قوی‌تر شد!")
        return
    if act == "buy":
        alert = None
        async with pool.acquire() as c:
            async with c.transaction():
                r = await c.fetchrow("SELECT balance, pets_owned FROM users WHERE user_id=$1 FOR UPDATE", uid)
                owned = int(r["pets_owned"] or 0)
                if owned >= len(PETS):
                    alert = "همه‌ی پت‌ها رو داری!"
                elif int(r["balance"] or 0) < PET_PRICES[owned]:
                    alert = f"موجودی جیبت کافی نیست؛ {PET_PRICES[owned]:,} تومن لازمه."
                else:
                    await c.execute("UPDATE users SET balance=balance-$1, pets_owned=pets_owned+1, pet_active=$2 WHERE user_id=$3", PET_PRICES[owned], owned + 1, uid)
        if alert:
            await q.answer(alert, show_alert=True); return
        await q.answer("پت جدیدت اومد! 🐾", show_alert=True)
        await _pet_edit(q, uid, "پت جدیدت به خانواده پیوست!")
        return
    await q.answer()


async def spy_text(update: Update, context: ContextTypes.DEFAULT_TYPE, text: str) -> bool:
    msg, user = update.effective_message, update.effective_user
    key = _word_key(text)
    if key in ("خریدجاسوسی", "خریدابزارجاسوسی"):
        await upsert_user(user.id, user.full_name)
        async with pool.acquire() as c:
            async with c.transaction():
                row = await c.fetchrow("SELECT balance, spy_owned FROM users WHERE user_id=$1 FOR UPDATE", user.id)
                if row["spy_owned"]:
                    answer = "ابزار جاسوسی رو قبلاً خریدی؛ برای استفاده روی پیام کاربر ریپلای کن و بنویس «جاسوسی»."
                elif int(row["balance"] or 0) < SPY_PRICE:
                    answer = f"موجودی کافی نیست. قیمت جاسوسی: {SPY_PRICE:,} تومان؛ موجودی جیب: {int(row['balance'] or 0):,} تومان."
                else:
                    await c.execute("UPDATE users SET balance=balance-$1, spy_owned=TRUE, spy_day=$2, spy_uses=0 WHERE user_id=$3", SPY_PRICE, _spy_day_key(), user.id)
                    answer = f"{SPY_CE} ابزار جاسوسی با موفقیت خریداری شد!\nهزینه: {SPY_PRICE:,} تومان\nروزانه {SPY_DAILY_LIMIT} بار می‌تونی استفاده کنی. برای جاسوسی روی پیام کاربر ریپلای کن و بنویس «جاسوسی»."
        await msg.reply_text(B(answer), parse_mode="HTML"); return True
    if key not in ("جاسوسی", "استعلامجاسوسی"):
        return False
    target = msg.reply_to_message.from_user if msg.reply_to_message else None
    if target is None or target.is_bot or target.id == user.id:
        await msg.reply_text(B("برای جاسوسی باید روی پیام یک کاربر ریپلای کنی؛ روی خودت یا ربات نمی‌شه."), parse_mode="HTML"); return True
    await upsert_user(user.id, user.full_name)
    day = _spy_day_key()
    async with pool.acquire() as c:
        async with c.transaction():
            own = await c.fetchrow("SELECT spy_owned, spy_day, spy_uses FROM users WHERE user_id=$1 FOR UPDATE", user.id)
            if not own or not own["spy_owned"]:
                await msg.reply_text(B(f"{SPY_CE} اول باید ابزار جاسوسی رو بخری. قیمت: {SPY_PRICE:,} تومان\nبرای خرید بنویس: خرید جاسوسی"), parse_mode="HTML"); return True
            used = int(own["spy_uses"] or 0) if own["spy_day"] == day else 0
            if used >= SPY_DAILY_LIMIT:
                await msg.reply_text(B(f"سهمیه‌ی امروزت تموم شده. روزانه فقط {SPY_DAILY_LIMIT} بار جاسوسی مجازه؛ فردا دوباره شارژ می‌شه."), parse_mode="HTML"); return True
            await c.execute("UPDATE users SET spy_day=$1, spy_uses=$2 WHERE user_id=$3", day, used+1, user.id)
            row = await c.fetchrow("SELECT user_id,name,balance,bank_balance,spouse_id,gender,jaghs,work_count,job_level,job_sel,energy FROM users WHERE user_id=$1", target.id)
            if not row:
                await c.execute("INSERT INTO users(user_id,name) VALUES($1,$2) ON CONFLICT(user_id) DO NOTHING", target.id, target.full_name)
                row = await c.fetchrow("SELECT user_id,name,balance,bank_balance,spouse_id,gender,jaghs,work_count,job_level,job_sel,energy FROM users WHERE user_id=$1", target.id)
            spouse = await c.fetchrow("SELECT name FROM users WHERE user_id=$1", row["spouse_id"]) if row["spouse_id"] else None
            acts = await c.fetchrow("SELECT (SELECT count(*) FROM group_msgs WHERE user_id=$1) AS messages, (SELECT count(*) FROM cars WHERE user_id=$1) AS cars, (SELECT count(*) FROM user_house WHERE user_id=$1) AS homes, (SELECT count(*) FROM robbery_state WHERE user_id=$1) AS robberies", target.id)
    job = current_job(row["gender"], int(row["jaghs"] or 0), int(row["work_count"] or 0), _jsel(row)) if row["gender"] in JOBS else None
    job_name = job[1] if job else "بدون شغل"
    marital = f"متأهل با {html.escape(spouse['name'] or 'همسر') }" if spouse else "مجرد"
    activity = f"امتیاز ثبت‌شده: {int(row['jaghs'] or 0):,}\nشیفت‌های کاری: {int(row['work_count'] or 0):,}\nپیام‌های ثبت‌شده در گروه‌ها: {int(acts['messages'] or 0):,}\nعملیات خلاف ثبت‌شده: {int(acts['robberies'] or 0):,}\nماشین‌ها: {int(acts['cars'] or 0)}\nخانه‌ها: {int(acts['homes'] or 0)}"
    remaining = SPY_DAILY_LIMIT-(used+1)
    report = (f"{SPY_CE} <b>گزارش جاسوسی</b>\nهدف: {_ulink(target.id,target.full_name)}\n\n"
              f"💵 پول داخل جیب: <b>{int(row['balance'] or 0):,} تومان</b>\n🏦 پول داخل بانک: <b>{int(row['bank_balance'] or 0):,} تومان</b>\n"
              f"💰 دارایی کل: <b>{int(row['balance'] or 0)+int(row['bank_balance'] or 0):,} تومان</b>\n"
              f"💍 وضعیت: <b>{marital}</b>\n💼 شغل: <b>{html.escape(job_name)}</b>\n⚡ انرژی: <b>{float(row['energy'] or 0):g}</b>\n\n"
              f"📋 <b>فعالیت‌ها</b>\n{activity}\n\nاستفاده‌ی باقی‌مانده‌ی امروز: <b>{remaining} از {SPY_DAILY_LIMIT}</b>")
    await msg.reply_text(report, parse_mode="HTML"); return True


# ═════════════════════ گپ‌ناشناس: گفت‌وگوی موقت بین دو گروه ═════════════════════
PROFILE_IMAGE_B64 = ""
JAGSAL_INVITE_TEXT = (
    '<b>یه بادمجون <tg-emoji emoji-id="5980906572891557214">🍆</tg-emoji> خسته غمگین می‌خواد باهاتون دردودل کنه؛ اگه مایل هستید در رو باز کنید.</b>'
)
JAGSAL_CONNECT_TEXT = (
    '<b><tg-emoji emoji-id="5452029295109086676">🚪</tg-emoji> یه گپ در رو باز کرد!\n'
    '<tg-emoji emoji-id="5265252136752533810">⏳</tg-emoji> حالا می‌تونید به مدت ۱۲ دقیقه باهم گفت‌وگو کنید.\n\n'
    '<tg-emoji emoji-id="5420323339723881652">🚫</tg-emoji> حروف انگلیسی، یوزرنیم و شماره از گپ‌ناشناس رد نمی‌شه.\n'
    'از فحش دادن به همدیگه خودداری کنید تا محروم نشید!\n\n'
    'برای شروع، روی همین پیام ریپلای کنید.</b>'
)

JAGSAL_CONNECTING_TEXT = (
    '<b>دارم شما رو به اولین گپی که در رو باز کنه متصل می‌کنم <tg-emoji emoji-id="5379684045636511609">🔗</tg-emoji></b>'
)
_PROFILE_IMAGE_BYTES = None   # بایت‌های عکس بعد از اولین رمزگشایی نگه داشته می‌شه
_PROFILE_FILE_ID = None       # بعد از اولین آپلود موفق، file_id نگه داشته می‌شه تا عکس هر بار آپلود نشه
_JAGSAL_HINT_TS: dict = {}   # آخرین زمان نمایش راهنمای «ریپلای کنید» برای هر گپ

def _jagsal_plain_kb(markup):
    """همون دکمه‌ها بدون استایل/آیکن؛ برای وقتی که تلگرام دکمه‌ی رنگی رو قبول نکنه."""
    if not markup:
        return markup
    try:
        return InlineKeyboardMarkup([
            [InlineKeyboardButton(b.text, callback_data=b.callback_data) for b in row]
            for row in markup.inline_keyboard])
    except Exception:
        return markup

def _jagsal_fatal(exc) -> bool:
    """خطاهایی که با ساده‌کردن کپشن/دکمه درست نمی‌شن (ربات از گروه رفته/کیک شده و ...)."""
    s = str(exc).lower()
    return type(exc).__name__ in ("Forbidden", "ChatMigrated") or any(
        k in s for k in ("chat not found", "bot was kicked", "bot is not a member", "bot was blocked"))

async def _jagsal_photo(bot, chat_id, caption, reply_markup=None, reply_to=None):
    """کارت گپ‌ناشناس: عکس + کپشن HTML با ایموجی پرمیوم و دکمه‌های رنگی.

    اگه تلگرام چیزی رو رد کنه، فقط همون بخش ساده می‌شه: اول دکمه‌ها، بعد ایموجی پرمیوم،
    بعد کل HTML. اگه عکس اصلاً نرفت، همین کارت به‌صورت متن فرستاده می‌شه. اگه هیچ‌کدوم
    نشد، خطا بالا می‌ره تا کسی که صداش زده بدونه کارت نرسیده.
    """
    global _PROFILE_IMAGE_BYTES, _PROFILE_FILE_ID
    caption = caption or ""
    no_premium = re.sub(r"<tg-emoji[^>]*>(.*?)</tg-emoji>", r"\1", caption)
    plain = html.unescape(re.sub(r"<[^>]*>", "", caption))
    plain_kb = _jagsal_plain_kb(reply_markup)
    rp = ReplyParameters(message_id=int(reply_to), allow_sending_without_reply=True) if reply_to else None
    tiers = [
        (caption, "HTML", reply_markup),
        (caption, "HTML", plain_kb),
        (no_premium, "HTML", plain_kb),
        (plain, None, plain_kb),
    ]
    last_exc = None
    for text, pm, kb in tiers:
        used_id = bool(_PROFILE_FILE_ID)
        try:
            if used_id:
                photo = _PROFILE_FILE_ID
            else:
                if _PROFILE_IMAGE_BYTES is None:
                    _PROFILE_IMAGE_BYTES = base64.b64decode(PROFILE_IMAGE_B64)
                photo = BytesIO(_PROFILE_IMAGE_BYTES); photo.name = "profile.jpg"
            m = await bot.send_photo(chat_id=chat_id, photo=photo, caption=text[:1024],
                                     parse_mode=pm, reply_markup=kb, reply_parameters=rp)
            if not used_id:
                try: _PROFILE_FILE_ID = m.photo[-1].file_id
                except Exception: pass
            return m
        except Exception as exc:
            last_exc = exc
            if used_id: _PROFILE_FILE_ID = None
            log.warning("jagsal photo failed in %s (parse_mode=%s): %s", chat_id, pm, exc)
            if _jagsal_fatal(exc): raise
    for text, pm, kb in tiers[1:]:
        try:
            return await bot.send_message(chat_id=chat_id, text=text, parse_mode=pm, reply_markup=kb, reply_parameters=rp)
        except Exception as exc:
            last_exc = exc
            log.warning("jagsal text card failed in %s (parse_mode=%s): %s", chat_id, pm, exc)
            if _jagsal_fatal(exc): raise
    raise last_exc

async def _jagsal_post_cards(bot, ses, sid: int):
    """کارت اتصال رو توی هر دو گروه می‌فرسته و لیست (chat_id, message_id) کارت‌های رسیده رو برمی‌گردونه."""
    posted = []
    for cid in (int(ses["source_chat"]), int(ses["target_chat"])):
        kb = InlineKeyboardMarkup([[
            btn("قطع ارتباط", "danger", icon="5202172377277935933", callback_data=f"jgs:disconnect:{sid}"),
            btn("گزارش", icon="5447644880824181073", callback_data=f"jgs:sessionreport:{sid}")]])
        try:
            m = await _jagsal_photo(bot, cid, JAGSAL_CONNECT_TEXT, kb)
        except Exception:
            log.exception("jagsal connect card failed in chat %s for session %s", cid, sid)
            continue
        await pool.execute(
            "INSERT INTO jagsal_posts(session_id,chat_id,message_id) VALUES($1,$2,$3) "
            "ON CONFLICT(session_id,chat_id) DO UPDATE SET message_id=EXCLUDED.message_id",
            sid, cid, m.message_id)
        posted.append((cid, m.message_id))
        try:
            me = await bot.get_chat_member(cid, bot.id)
            if str(me.status) == "administrator":
                await bot.pin_chat_message(cid, m.message_id, disable_notification=True)
        except Exception:
            log.info("jagsal connect post could not be pinned in %s", cid, exc_info=True)
    return posted

async def _jagsal_cancel_waiting(bot, row):
    """دعوتی که کسی در رو بازش نکرده بسته می‌شه، دعوت‌ها پاک می‌شن و گپ درخواست‌دهنده آزاد می‌شه."""
    sid = int(row["session_id"])
    done = await pool.fetchval(
        "UPDATE jagsal_sessions SET status='cancelled',ended_at=$2,end_reason='no_taker' "
        "WHERE session_id=$1 AND status='waiting' RETURNING 1", sid, time.time())
    if not done:
        return
    for x in await pool.fetch("SELECT chat_id,message_id FROM jagsal_invites WHERE session_id=$1", sid):
        try: await bot.delete_message(int(x["chat_id"]), int(x["message_id"]))
        except Exception: pass
    try:
        await bot.send_message(int(row["source_chat"]), "<b>هیچ گپی در رو باز نکرد؛ درخواست گپ‌ناشناس بسته شد. می‌تونی دوباره بگی «گپ‌ناشناس».</b>", parse_mode="HTML")
    except Exception:
        pass

async def _jagsal_group_active(chat_id: int) -> bool:
    return bool(await pool.fetchval(
        "SELECT 1 FROM jagsal_sessions WHERE status IN ('waiting','connected') AND (source_chat=$1 OR target_chat=$1) LIMIT 1", chat_id))

async def _jagsal_cooldown(kind: str, oid: int) -> float:
    return float(await pool.fetchval("SELECT until_ts FROM jagsal_cooldowns WHERE kind=$1 AND object_id=$2", kind, oid) or 0)

async def _jagsal_is_admin(bot, chat_id: int, uid: int) -> bool:
    try:
        m = await bot.get_chat_member(chat_id, uid)
        return str(m.status) in ("creator", "administrator")
    except Exception:
        return False

async def _jagsal_invite(bot, chat_id: int, sid: int) -> bool:
    kb = InlineKeyboardMarkup([[btn("در رو باز می‌کنیم", "success", icon="5452029295109086676", callback_data=f"jgs:open:{sid}")]])
    try:
        m = await _jagsal_photo(bot, chat_id, JAGSAL_INVITE_TEXT, kb)
        await pool.execute("INSERT INTO jagsal_invites(session_id,chat_id,message_id) VALUES($1,$2,$3) ON CONFLICT DO NOTHING", sid, chat_id, m.message_id)
        return True
    except Exception as exc:
        # علت دقیق در لاگ می‌ماند؛ شکست یک گروه، دعوت گروه‌های دیگر را متوقف نمی‌کند.
        log.warning("jagsal invite failed in %s: %s", chat_id, exc, exc_info=True)
        return False

async def jagsal_group_text(update: Update, context: ContextTypes.DEFAULT_TYPE, text: str) -> bool:
    msg, user = update.effective_message, update.effective_user
    if not msg or not user or user.is_bot or msg.chat.type not in ("group", "supergroup"):
        return False
    # پیام‌های حین اتصال ابتدا برای گروه مقابل فرستاده می‌شوند.
    active = await pool.fetchrow(
        "SELECT * FROM jagsal_sessions WHERE status='connected' AND (source_chat=$1 OR target_chat=$1) ORDER BY session_id DESC LIMIT 1", msg.chat_id)
    if active:
        return bool(await _jagsal_relay_message(context.bot, active, msg, user))
    if _word_key(text) not in ("گپ‌ناشناس", "گپ‌ناشناس"):
        return False
    until = max(await _jagsal_cooldown("chat", msg.chat_id), await _jagsal_cooldown("user", user.id))
    if until > time.time():
        await msg.reply_text(f"برای استفاده دوباره از گپ‌ناشناس باید {max(1,int((until-time.time()+59)//60))} دقیقه صبر کنی.")
        return True
    if await _jagsal_group_active(msg.chat_id):
        await msg.reply_text("این گپ همین الان میزبان یک گپ‌ناشناس فعاله یا منتظر اتصال به گپ دیگه‌ست.")
        return True
    # اطلاعات سازنده برای گزارش‌های احتمالی نگهداری می‌شود.
    await upsert_user(user.id, user.full_name)
    # یک قفل دیتابیسی جلوی ساخت هم‌زمان دو دعوت از یک گروه را می‌گیرد.
    async with pool.acquire() as c:
        async with c.transaction():
            await c.fetchval("SELECT pg_advisory_xact_lock($1)", int(msg.chat_id))
            busy = await c.fetchval("SELECT 1 FROM jagsal_sessions WHERE status IN ('waiting','connected') AND (source_chat=$1 OR target_chat=$1) LIMIT 1", msg.chat_id)
            if busy:
                await msg.reply_text("این گپ همین الان در یک گپ‌ناشناس فعاله.")
                return True
            sid = await c.fetchval(
                "INSERT INTO jagsal_sessions(source_chat,source_user,status,created_at) VALUES($1,$2,'waiting',$3) RETURNING session_id",
                msg.chat_id, user.id, time.time())
    try:
        wait_msg = await _jagsal_photo(context.bot, msg.chat_id, JAGSAL_CONNECTING_TEXT, reply_to=msg.message_id)
        # این پیام بعد از وصل‌شدن همراه دعوت‌ها پاک می‌شه
        await pool.execute("INSERT INTO jagsal_invites(session_id,chat_id,message_id) VALUES($1,$2,$3) ON CONFLICT DO NOTHING",
                           int(sid), int(msg.chat_id), wait_msg.message_id)
    except Exception:
        log.exception("jagsal connecting card failed in %s", msg.chat_id)
    # دعوت فقط برای گروه‌های دیگر ارسال شود؛ گروه درخواست‌دهنده نباید دکمهٔ پذیرش خودش را ببیند.
    chats = list(dict.fromkeys(int(cid) for cid in KNOWN_CHATS if int(cid) != int(msg.chat_id)))
    sent = 0
    for cid in chats:
        if await _jagsal_invite(context.bot, cid, int(sid)):
            sent += 1
    if sent == 0:
        await pool.execute("UPDATE jagsal_sessions SET status='cancelled' WHERE session_id=$1 AND status='waiting'", int(sid))
        await msg.reply_text(
            "فعلاً هیچ گروه دیگری دعوت را دریافت نکرد. ربات لازم نیست ادمین باشد؛ "
            "اما باید عضو گروه مقصد باشد و ارسال پیام برایش محدود نشده باشد. "
            "بعد از اضافه‌کردن ربات به گروه‌های مقصد، دوباره «گپ‌ناشناس» را بفرست."
        )
    else:
        await msg.reply_text(f"دعوت گپ‌ناشناس برای {sent} گروه ارسال شد؛ منتظر اولین گروهی هستیم که در را باز کند.")
    return True

async def _jagsal_react(bot, chat_id, message_id):
    """روی پیام‌های ردشده توی گپ‌ناشناس ری‌اکشن ⚡ می‌زنه؛ اگه گروه ری‌اکشن رو نپذیره بی‌صدا رد می‌شه."""
    try:
        from telegram import ReactionTypeEmoji
        await bot.set_message_reaction(chat_id=chat_id, message_id=message_id, reaction=[ReactionTypeEmoji("⚡")])
    except Exception:
        log.debug("jagsal reaction failed in %s", chat_id, exc_info=True)

async def _jagsal_relay_message(bot, session, msg, user):
    reply_origin = None   # پیام اصلیِ اون‌ور که این پیام بهش ریپلای شده
    # اولین پیام هر گفت‌وگو باید با ریپلای به پیام اتصال شروع شود؛ پس از آن گفتگو آزاد است.
    if not session["started_at"]:
        anchor = await pool.fetchval("SELECT message_id FROM jagsal_posts WHERE session_id=$1 AND chat_id=$2", int(session["session_id"]), int(msg.chat_id))
        if not msg.reply_to_message or not anchor or int(msg.reply_to_message.message_id) != int(anchor):
            _now = time.time()
            if _now - _JAGSAL_HINT_TS.get(msg.chat_id, 0) >= 90:
                _JAGSAL_HINT_TS[msg.chat_id] = _now
                try: await msg.reply_text("<b>برای شروع گفت‌وگو، روی پیام اتصال (همون عکس) ریپلای کنید.</b>", parse_mode="HTML")
                except Exception: pass
            return False
        await pool.execute("UPDATE jagsal_sessions SET started_at=$2 WHERE session_id=$1 AND started_at IS NULL", int(session["session_id"]), time.time())
        session = await pool.fetchrow("SELECT * FROM jagsal_sessions WHERE session_id=$1", int(session["session_id"]))
    else:
        # پیام عادی گروه به گپ مقابل نمی‌ره؛ فقط ریپلای به پیامِ رسیده از اون‌ور (یا کارت اتصال)
        rt = msg.reply_to_message
        ok = False
        if rt:
            dm = await pool.fetchrow("SELECT origin_message FROM jagsal_dest_msgs WHERE chat_id=$1 AND message_id=$2 AND session_id=$3", int(msg.chat_id), int(rt.message_id), int(session["session_id"]))
            ok = dm is not None
            if ok and dm["origin_message"]: reply_origin = int(dm["origin_message"])
            if not ok:
                anchor = await pool.fetchval("SELECT message_id FROM jagsal_posts WHERE session_id=$1 AND chat_id=$2", int(session["session_id"]), int(msg.chat_id))
                ok = bool(anchor) and int(rt.message_id) == int(anchor)
        if not ok: return False
    if msg.chat_id == int(session["source_chat"]):
        dest = int(session["target_chat"]); group_title = msg.chat.title or str(msg.chat_id)
    elif msg.chat_id == int(session["target_chat"]):
        dest = int(session["source_chat"]); group_title = msg.chat.title or str(msg.chat_id)
    else:
        return False
    if msg.text is not None:
        body = msg.text.strip()
        if not body or re.search(r"[A-Za-z0-9@۰-۹٠-٩]", body):
            return False
    elif msg.caption is not None:
        body = msg.caption.strip()
        if re.search(r"[A-Za-z0-9@۰-۹٠-٩]", body): return False
    else:
        body = "[رسانه]"
    # از بازنشر پیام‌های سیستمی/دستوری جلوگیری می‌شود.
    if msg.text and msg.text.startswith("/"): return False
    await pool.execute("INSERT INTO jagsal_participants(session_id,user_id,chat_id,first_seen) VALUES($1,$2,$3,$4) ON CONFLICT(session_id,user_id) DO NOTHING", int(session["session_id"]), user.id, msg.chat_id, time.time())
    row = await pool.fetchrow(
        "INSERT INTO jagsal_relays(session_id,source_chat,source_message,source_user,source_name,source_group,body,created_at) "
        "VALUES($1,$2,$3,$4,$5,$6,$7,$8) ON CONFLICT(session_id,source_chat,source_message) DO NOTHING RETURNING relay_id",
        int(session["session_id"]), msg.chat_id, msg.message_id, user.id, user.full_name, group_title, body[:4000], time.time())
    if not row: return False
    relay_id = int(row["relay_id"])
    kb = InlineKeyboardMarkup([[btn("گزارش", icon="5447644880824181073", callback_data=f"jgs:report:{relay_id}")]])
    attribution = f'<b>{html.escape(user.full_name)} از گپ {html.escape(group_title)}</b>'
    rp = ReplyParameters(message_id=reply_origin, allow_sending_without_reply=True) if reply_origin else None
    sent_ids = []
    if msg.text:
        payload = f'{attribution}\n<blockquote>{html.escape(body[:3500])}</blockquote>'
        sent_ids.append((await bot.send_message(dest, payload, parse_mode="HTML", reply_markup=kb, reply_parameters=rp)).message_id)
    else:
        sent_ids.append((await bot.send_message(dest, attribution, parse_mode="HTML", reply_markup=kb, reply_parameters=rp)).message_id)
        try:
            sent_ids.append((await bot.copy_message(dest, msg.chat_id, msg.message_id, reply_parameters=rp)).message_id)
        except Exception:
            pass
    for mid in sent_ids:
        await pool.execute("INSERT INTO jagsal_dest_msgs(chat_id,message_id,session_id,origin_chat,origin_message) VALUES($1,$2,$3,$4,$5) ON CONFLICT DO NOTHING", dest, mid, int(session["session_id"]), int(msg.chat_id), int(msg.message_id))
    # ری‌اکشن ⚡ روی پیام اصلی و نسخه‌ی ردشده
    for cid_, mid_ in [(int(msg.chat_id), int(msg.message_id))] + [(dest, m_) for m_ in sent_ids]:
        asyncio.create_task(_jagsal_react(bot, cid_, mid_))
    return True

async def jagsal_nontext(update: Update, context: ContextTypes.DEFAULT_TYPE):
    msg, user = update.effective_message, update.effective_user
    if not msg or not user or user.is_bot or msg.chat.type not in ("group", "supergroup"): return
    # پیام‌های سرویس (پین‌شدن کارت، ورود عضو و ...) رسانه نیستن و نباید ریله بشن
    if not any((msg.photo, msg.video, msg.document, msg.audio, msg.voice, msg.video_note, msg.sticker,
                msg.animation, msg.location, msg.contact, msg.poll)): return
    session = await pool.fetchrow("SELECT * FROM jagsal_sessions WHERE status='connected' AND (source_chat=$1 OR target_chat=$1) ORDER BY session_id DESC LIMIT 1", msg.chat_id)
    if session: await _jagsal_relay_message(context.bot, session, msg, user)

async def _jagsal_end(bot, session, actor_id: int, reason: str):
    sid = int(session["session_id"]); now = time.time()
    async with pool.acquire() as c:
        async with c.transaction():
            r = await c.fetchrow("UPDATE jagsal_sessions SET status='ended',ended_at=$2,ended_by=$3,end_reason=$4 WHERE session_id=$1 AND status IN ('waiting','connected') RETURNING source_chat,target_chat,source_user,target_user", sid, now, actor_id, reason)
            if not r: return False
            for kind, oid in (("chat", int(r["source_chat"])), ("user", int(r["source_user"]))):
                await c.execute("INSERT INTO jagsal_cooldowns(kind,object_id,until_ts) VALUES($1,$2,$3) ON CONFLICT(kind,object_id) DO UPDATE SET until_ts=EXCLUDED.until_ts", kind, oid, now+300)
            if r["target_chat"]:
                await c.execute("INSERT INTO jagsal_cooldowns(kind,object_id,until_ts) VALUES('chat',$1,$2) ON CONFLICT(kind,object_id) DO UPDATE SET until_ts=EXCLUDED.until_ts", int(r["target_chat"]), now+300)
            if r["target_user"]:
                await c.execute("INSERT INTO jagsal_cooldowns(kind,object_id,until_ts) VALUES('user',$1,$2) ON CONFLICT(kind,object_id) DO UPDATE SET until_ts=EXCLUDED.until_ts", int(r["target_user"]), now+300)
            await c.execute("INSERT INTO jagsal_cooldowns(kind,object_id,until_ts) SELECT 'user',user_id,$2 FROM jagsal_participants WHERE session_id=$1 ON CONFLICT(kind,object_id) DO UPDATE SET until_ts=GREATEST(jagsal_cooldowns.until_ts,EXCLUDED.until_ts)", sid, now+300)
    # پرحرف‌ترین فرد این گپ‌ناشناس (بر اساس پیام‌های ردشده)
    try:
        top = await pool.fetchrow("SELECT source_user, MAX(source_name) AS name, COUNT(*) AS cnt FROM jagsal_relays WHERE session_id=$1 GROUP BY source_user ORDER BY cnt DESC, MIN(created_at) LIMIT 1", sid)
    except Exception:
        top = None
    if reason == "admin_disconnect":
        head = '<tg-emoji emoji-id="5330572782528915278">💔</tg-emoji> یکی از ادمین‌ها ارتباط رو قطع کرد.'
    else:
        head = '<tg-emoji emoji-id="5265252136752533810">⏳</tg-emoji> زمان گفت‌وگو تموم شد و ارتباط قطع شد.'
    if top:
        stats = (f'\n\n<tg-emoji emoji-id="5875065225664798722">🔥</tg-emoji> پرحرف‌ترین فرد این گپ‌ناشناس: {html.escape(top["name"] or "ناشناس")}\n'
                 f'<tg-emoji emoji-id="5875483791702630534">🎉</tg-emoji> تعداد پیام‌ها: {int(top["cnt"])}')
    else:
        stats = "\n\nکسی توی این گپ‌ناشناس حرفی نزد."
    end_text = f"<b>{head}{stats}\n\nبرای استفاده دوباره باید ۵ دقیقه صبر کنید.</b>"
    for cid in (int(r["source_chat"]), int(r["target_chat"]) if r["target_chat"] else None):
        if not cid: continue
        post = await pool.fetchval("SELECT message_id FROM jagsal_posts WHERE session_id=$1 AND chat_id=$2", sid, cid)
        if post:
            try: await bot.unpin_chat_message(cid, post)
            except Exception: pass
        try: await _jagsal_photo(bot, cid, end_text)
        except Exception: log.exception("jagsal end card failed in %s", cid)
    return True

async def _jagsal_report_send(bot, relay, reporter):
    await upsert_user(int(relay["source_user"]), relay["source_name"])
    reported_username = await pool.fetchval("SELECT username FROM users WHERE user_id=$1", int(relay["source_user"]))
    async with pool.acquire() as c:
        async with c.transaction():
            rep = await c.fetchrow(
                "INSERT INTO jagsal_reports(relay_id,session_id,reporter_id,reporter_name,reporter_username,reported_id,reported_name,reported_username,created_at) "
                "VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) ON CONFLICT(relay_id) DO NOTHING RETURNING report_id",
                int(relay["relay_id"]), int(relay["session_id"]), reporter.id, reporter.full_name, reporter.username, int(relay["source_user"]), relay["source_name"], reported_username, time.time())
            if not rep: return None
    rid = int(rep["report_id"])
    text = (f"<b>گزارش گپ‌ناشناس #{rid}</b>\nگزارش‌دهنده: {html.escape(reporter.full_name)}"
            f"\nیوزرنیم: @{html.escape(reporter.username or 'ندارد')}\nآیدی: <code>{reporter.id}</code>"
            f"\nگزارش‌شده: {html.escape(relay['source_name'])} (@{html.escape(reported_username or 'ندارد')})\nآیدی: <code>{relay['source_user']}</code>"
            f"\nگپ: {html.escape(relay['source_group'])}\nمتن: <blockquote>{html.escape((relay['body'] or '[رسانه]')[:1800])}</blockquote>")
    kb = InlineKeyboardMarkup([[btn("محرومیت ۱ ساعت", "danger", callback_data=f"jgs:ban:{rid}:1"), btn("محرومیت ۲ ساعت", "danger", callback_data=f"jgs:ban:{rid}:2")], [btn("مدت دلخواه", "primary", callback_data=f"jgs:custom:{rid}"), btn("رد گزارش", callback_data=f"jgs:reject:{rid}")]])
    sent = 0
    for aid in (set(OWNER_IDS) | set(STAFF)):
        try: await bot.send_message(aid, text, parse_mode="HTML", reply_markup=kb); sent += 1
        except Exception: pass
    return rid if sent else rid

async def jagsal_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    q=update.callback_query; parts=(q.data or "").split(":"); uid=q.from_user.id
    try:
        if parts[1] == "open":
            sid=int(parts[2]); chat_id=q.message.chat_id
            await upsert_user(uid, q.from_user.full_name)
            async with pool.acquire() as c:
                async with c.transaction():
                    await c.fetchval("SELECT pg_advisory_xact_lock($1)", int(chat_id))
                    ses=await c.fetchrow("SELECT * FROM jagsal_sessions WHERE session_id=$1 FOR UPDATE", sid)
                    if not ses or ses["status"]!="waiting":
                        await q.answer("این دعوت دیگه فعال نیست.",show_alert=True)
                        try: await q.message.delete()   # کارت دعوت قدیمی نمونه
                        except Exception: pass
                        return
                    if chat_id == int(ses["source_chat"]): await q.answer("این گپ خودش دعوت رو ساخته؛ باید گپ دیگه‌ای در رو باز کنه.",show_alert=True); return
                    if await c.fetchval("SELECT 1 FROM jagsal_sessions WHERE status IN ('waiting','connected') AND (source_chat=$1 OR target_chat=$1) LIMIT 1",chat_id):
                        await q.answer("این گپ در حال حاضر در یک گپ‌ناشناس دیگه فعاله.",show_alert=True); return
                    cd=await c.fetchval("SELECT until_ts FROM jagsal_cooldowns WHERE kind='chat' AND object_id=$1",chat_id)
                    ucd=await c.fetchval("SELECT until_ts FROM jagsal_cooldowns WHERE kind='user' AND object_id=$1",uid)
                    if (cd and float(cd)>time.time()) or (ucd and float(ucd)>time.time()): await q.answer("این گپ یا حساب شما هنوز در زمان استراحته.",show_alert=True); return
                    now_connect = time.time()
                    await c.execute("UPDATE jagsal_sessions SET target_chat=$2,target_user=$3,status='connected',connected_at=$4,expires_at=$5 WHERE session_id=$1",sid,chat_id,uid,now_connect,now_connect+720)
                    ses=await c.fetchrow("SELECT * FROM jagsal_sessions WHERE session_id=$1",sid)
            # اتصال ثبت شد؛ همین‌جا به دکمه جواب می‌دیم تا کلیک بی‌نتیجه به نظر نرسه
            try: await q.answer("در حال اتصال…")
            except Exception: pass
            posted = []
            try:
                posted = await _jagsal_post_cards(context.bot, ses, sid)
            except Exception:
                log.exception("jagsal post cards failed for session %s", sid)
            posted_ids = {int(cid) for cid, _ in posted}
            if len(posted_ids) < 2:
                # کارت اتصال توی هر دو گروه نرسید؛ کارت ناقص برداشته می‌شه تا گپ‌ها گیر نکنن
                for cid, mid in posted:
                    try: await context.bot.delete_message(cid, mid)
                    except Exception: pass
                await pool.execute("DELETE FROM jagsal_posts WHERE session_id=$1", sid)
                if int(ses["source_chat"]) in posted_ids:
                    # فقط گروهی که در رو باز کرد مشکل داشت: دعوت زنده می‌مونه تا گپ دیگه‌ای در رو باز کنه
                    await pool.execute(
                        "UPDATE jagsal_sessions SET status='waiting',target_chat=NULL,target_user=NULL,"
                        "connected_at=NULL,expires_at=NULL,started_at=NULL WHERE session_id=$1 AND status='connected'", sid)
                    note = "<b>اتصال کامل نشد؛ ربات نتونست توی این گپ پیام بفرسته. بررسی کنید ربات عضو گروه باشه و ارسال پیام و عکس براش بسته نباشه.</b>"
                    notify = [chat_id]
                else:
                    # گروه درخواست‌دهنده در دسترس نیست
                    await pool.execute(
                        "UPDATE jagsal_sessions SET status='cancelled',ended_at=$2,end_reason='card_failed' "
                        "WHERE session_id=$1 AND status='connected'", sid, time.time())
                    for x in await pool.fetch("SELECT chat_id,message_id FROM jagsal_invites WHERE session_id=$1", sid):
                        try: await context.bot.delete_message(int(x["chat_id"]), int(x["message_id"]))
                        except Exception: pass
                    note = "<b>اتصال برقرار نشد؛ ربات نتونست توی یکی از گروه‌ها پیام بفرسته. دوباره «گپ‌ناشناس» رو امتحان کنید.</b>"
                    notify = [chat_id, int(ses["source_chat"])]
                for cid in dict.fromkeys(notify):
                    try: await context.bot.send_message(cid, note, parse_mode="HTML")
                    except Exception: pass
                return
            # حالا که اتصال کامل شد، دعوت‌ها (و پیام «در حال اتصال») دیگه قابل استفاده نیستن
            inv = await pool.fetch("SELECT chat_id,message_id FROM jagsal_invites WHERE session_id=$1", sid)
            for x in inv:
                try: await context.bot.delete_message(int(x["chat_id"]), int(x["message_id"]))
                except Exception:
                    try: await context.bot.edit_message_reply_markup(int(x["chat_id"]), int(x["message_id"]), reply_markup=None)
                    except Exception: pass
            return
        if parts[1] == "disconnect":
            sid=int(parts[2]); ses=await pool.fetchrow("SELECT * FROM jagsal_sessions WHERE session_id=$1",sid)
            if not ses or ses["status"]!="connected": await q.answer("این ارتباط فعال نیست.",show_alert=True); return
            if q.message.chat_id not in (int(ses["source_chat"]),int(ses["target_chat"])) or not await _jagsal_is_admin(context.bot,q.message.chat_id,uid):
                await q.answer("فقط ادمین همین گپ می‌تونه ارتباط رو قطع کنه.",show_alert=True); return
            await _jagsal_end(context.bot,ses,uid,"admin_disconnect"); await q.answer("ارتباط قطع شد."); return
        if parts[1] == "sessionreport":
            sid=int(parts[2]); ses=await pool.fetchrow("SELECT * FROM jagsal_sessions WHERE session_id=$1",sid)
            participant=await pool.fetchval("SELECT 1 FROM jagsal_participants WHERE session_id=$1 AND user_id=$2",sid,uid)
            if not ses or not participant or q.message.chat_id not in (int(ses["source_chat"]),int(ses["target_chat"] or 0)):
                await q.answer("فقط کسی که در این گپ‌ناشناس پیام فرستاده می‌تونه گزارش بده.",show_alert=True); return
            if q.message.chat_id == int(ses["source_chat"]):
                partner_id=int(ses["target_user"]); partner_chat=int(ses["target_chat"])
            else:
                partner_id=int(ses["source_user"]); partner_chat=int(ses["source_chat"])
            partner=await pool.fetchrow("SELECT name,username FROM users WHERE user_id=$1",partner_id)
            group=await context.bot.get_chat(partner_chat)
            relay=await pool.fetchrow(
                "INSERT INTO jagsal_relays(session_id,source_chat,source_message,source_user,source_name,source_group,body,created_at) "
                "VALUES($1,$2,$3,$4,$5,$6,'گزارش کل ارتباط',$7) ON CONFLICT(session_id,source_chat,source_message) DO UPDATE SET source_user=EXCLUDED.source_user RETURNING *",
                sid,partner_chat,-sid,partner_id,(partner["name"] if partner else str(partner_id)),(group.title or str(partner_chat)),time.time())
            result=await _jagsal_report_send(context.bot,relay,q.from_user)
            if result is None: await q.answer("این ارتباط قبلاً گزارش شده.",show_alert=True)
            else: await q.answer("گزارش برای پشتیبانی ارسال شد.",show_alert=True)
            return
        if parts[1] == "report":
            rid=int(parts[2]); relay=await pool.fetchrow("SELECT * FROM jagsal_relays WHERE relay_id=$1",rid)
            if not relay: await q.answer("پیام پیدا نشد.",show_alert=True); return
            ses=await pool.fetchrow("SELECT * FROM jagsal_sessions WHERE session_id=$1",int(relay["session_id"]))
            participant = await pool.fetchval("SELECT 1 FROM jagsal_participants WHERE session_id=$1 AND user_id=$2", int(relay["session_id"]), uid)
            if not ses or not participant or q.message.chat_id not in (int(ses["source_chat"]),int(ses["target_chat"] or 0)):
                await q.answer("فقط کسی که در همین گپ‌ناشناس پیام فرستاده می‌تونه گزارش بده.",show_alert=True); return
            report=await _jagsal_report_send(context.bot,relay,q.from_user)
            if report is None: await q.answer("این پیام قبلاً گزارش شده.",show_alert=True)
            else: await q.answer("گزارش برای پشتیبانی ارسال شد.",show_alert=True)
            return
        if parts[1] in ("ban","custom","reject"):
            if uid not in OWNER_IDS and uid not in STAFF: await q.answer("فقط پشتیبانی می‌تونه گزارش رو بررسی کنه.",show_alert=True); return
            rid=int(parts[2]); report=await pool.fetchrow("SELECT * FROM jagsal_reports WHERE report_id=$1 AND status='pending'",rid)
            if not report: await q.answer("این گزارش قبلاً بررسی شده.",show_alert=True); return
            if parts[1]=="custom":
                context.user_data["jagsal_custom_report"]=rid
                await q.answer(); await q.message.reply_text("مدت محرومیت را به ساعت بفرست (مثلاً ۳ یا ۱۲).")
                return
            if parts[1]=="reject":
                await pool.execute("UPDATE jagsal_reports SET status='rejected',reviewer=$2,reviewed_at=$3 WHERE report_id=$1",rid,uid,time.time())
                await q.answer("گزارش رد شد."); await q.edit_message_reply_markup(reply_markup=None); return
            hours=int(parts[3]); await _jagsal_ban_report(context.bot,report,uid,hours)
            await q.answer(f"کاربر {hours} ساعت محروم شد."); await q.edit_message_reply_markup(reply_markup=None); return
    except Exception:
        log.exception("jagsal callback failed")
        try: await q.answer("خطا در انجام عملیات.",show_alert=True)
        except Exception: pass

async def _jagsal_ban_report(bot, report, reviewer: int, hours: float):
    hours=max(0.1,min(float(hours),720)); until=time.time()+hours*3600; uid=int(report["reported_id"])
    await upsert_user(uid, report["reported_name"])
    await pool.execute("UPDATE users SET banned_until=GREATEST(banned_until,$2) WHERE user_id=$1",uid,until)
    BANNED[uid]=max(BANNED.get(uid,0),until)
    await pool.execute("UPDATE jagsal_reports SET status='banned',reviewer=$2,reviewed_at=$3 WHERE report_id=$1",int(report["report_id"]),reviewer,time.time())
    try: await bot.send_message(uid,f"به دلیل گزارش تأییدشده در گپ‌ناشناس، {hours:g} ساعت از ربات محروم شدی.")
    except Exception: pass

async def jagsal_private_custom(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    rid=context.user_data.get("jagsal_custom_report")
    msg=update.effective_message; uid=update.effective_user.id if update.effective_user else 0
    if not rid or not msg or not msg.text: return False
    if uid not in OWNER_IDS and uid not in STAFF: context.user_data.pop("jagsal_custom_report",None); return False
    try: hours=float(msg.text.strip().replace(",","."))
    except ValueError: await msg.reply_text("عدد ساعت معتبر نیست؛ مثلاً ۳ یا ۱۲ بفرست."); return True
    report=await pool.fetchrow("SELECT * FROM jagsal_reports WHERE report_id=$1 AND status='pending'",int(rid))
    context.user_data.pop("jagsal_custom_report",None)
    if not report: await msg.reply_text("این گزارش قبلاً بررسی شده."); return True
    await _jagsal_ban_report(context.bot,report,uid,hours)
    await msg.reply_text(f"کاربر برای {max(0.1,min(hours,720)):g} ساعت محروم شد.")
    return True

# ───────────────────────── تگ شغل کاربرا تو گروه ─────────────────────────
# وقتی ربات تو گروه ادمین باشه (با دسترسی «مدیریت تگ‌ها»)، شغل هر کسی که تو گروه پیام می‌ده رو به‌عنوان تگ عضو می‌ذاره.
# کسی که شغل نداره تگش «بیکار» میشه. تگ‌ها حداکثر ۱۶ حرف و بدون ایموجی‌ان؛ روی ادمین/مالک گروه تگ گذاشته نمیشه.
JOBTAG_ENABLED = True
JOBTAG_UNEMPLOYED = "بیکار"
JOBTAG_CHECK_EVERY = 90         # هر کاربر حداکثر هر ۹۰ ثانیه یه بار چک میشه
JOBTAG_CHAT_COOLDOWN = 600      # ربات ادمین نبود یا دسترسی نداشت: ۱۰ دقیقه بعد دوباره امتحان می‌کنه
JOBTAG_USER_SKIP = 3600         # کسی که تگش قابل تغییر نیست (مثلاً ادمین): یه ساعت رد میشه
_JOBTAG_LAST: dict[tuple, str] = {}
_JOBTAG_CHECKED: dict[tuple, float] = {}
_JOBTAG_SKIP_UNTIL: dict[tuple, float] = {}
_JOBTAG_CHAT_OFF: dict[int, float] = {}
_JOBTAG_CHAT_FAILS: dict[int, int] = {}
_JOBTAG_BOT_ADMIN: dict[int, tuple] = {}
_JOBTAG_TASKS: set = set()
_JOBTAG_SEM = None
_JOBTAG_EMOJI_RE = re.compile("[\U0001F000-\U0001FFFF\u2600-\u27BF\u2B00-\u2BFF\uFE0F\u200D\u20E3]")


def _jobtag_clean(t: str) -> str:
    t = _JOBTAG_EMOJI_RE.sub("", t or "").strip()
    return t[:16].strip()


def _jobtag_for_row(row) -> str:
    try:
        g = row["gender"] if row else None
        if g in JOBS:
            job = current_job(g, int(row["jaghs"] or 0), int(row["work_count"] or 0), _jsel(row))
            if job:
                return _jobtag_clean(job[1]) or JOBTAG_UNEMPLOYED
    except Exception:
        pass
    return JOBTAG_UNEMPLOYED


async def _set_member_tag(bot, chat_id: int, user_id: int, tag: str):
    fn = getattr(bot, "set_chat_member_tag", None)          # نسخه‌های جدید python-telegram-bot
    if fn:
        return await fn(chat_id, user_id, tag)
    dar = getattr(bot, "do_api_request", None)
    if dar:
        return await dar("setChatMemberTag", api_kwargs={"chat_id": chat_id, "user_id": user_id, "tag": tag})

    def _call():                                              # آخرین راه: درخواست مستقیم به API تلگرام
        import urllib.request, urllib.parse, urllib.error
        data = urllib.parse.urlencode({"chat_id": chat_id, "user_id": user_id, "tag": tag}).encode()
        try:
            with urllib.request.urlopen(f"https://api.telegram.org/bot{BOT_TOKEN}/setChatMemberTag", data=data, timeout=15) as r:
                return json.loads(r.read().decode())
        except urllib.error.HTTPError as e:
            try:
                d = json.loads(e.read().decode()).get("description")
            except Exception:
                d = str(e)
            raise RuntimeError(d)
    return await asyncio.to_thread(_call)


async def _jobtag_bot_is_admin(bot, chat_id: int) -> bool:
    now = time.time()
    hit = _JOBTAG_BOT_ADMIN.get(chat_id)
    if hit and now - hit[0] < JOBTAG_CHAT_COOLDOWN:
        return hit[1]
    try:
        me = await bot.get_chat_member(chat_id, bot.id)
        ok = getattr(me, "status", "") in ("administrator", "creator")
    except Exception:
        ok = False
    _JOBTAG_BOT_ADMIN[chat_id] = (now, ok)
    return ok


async def _jobtag_sync(bot, chat_id: int, user_id: int):
    global _JOBTAG_SEM
    key = (chat_id, user_id)
    now = time.time()
    try:
        if not await _jobtag_bot_is_admin(bot, chat_id):
            _JOBTAG_CHAT_OFF[chat_id] = now + JOBTAG_CHAT_COOLDOWN
            return
        tag = _jobtag_for_row(await get_user(user_id))
        if _JOBTAG_LAST.get(key) == tag:
            return
        if _JOBTAG_SEM is None:
            _JOBTAG_SEM = asyncio.Semaphore(2)
        async with _JOBTAG_SEM:
            await _set_member_tag(bot, chat_id, user_id, tag)
        _JOBTAG_LAST[key] = tag
        _JOBTAG_CHAT_FAILS[chat_id] = 0
    except RetryAfter as e:
        ra = getattr(e, "retry_after", 30)
        ra = ra.total_seconds() if hasattr(ra, "total_seconds") else float(ra)
        _JOBTAG_CHAT_OFF[chat_id] = now + ra + 1
    except Exception as e:
        _JOBTAG_SKIP_UNTIL[key] = now + JOBTAG_USER_SKIP
        n = _JOBTAG_CHAT_FAILS.get(chat_id, 0) + 1
        _JOBTAG_CHAT_FAILS[chat_id] = n
        if n >= 5:    # پنج بار پشت‌سرهم شکست = احتمالاً ربات دسترسی «مدیریت تگ‌ها» رو نداره
            _JOBTAG_CHAT_OFF[chat_id] = now + JOBTAG_CHAT_COOLDOWN
            _JOBTAG_CHAT_FAILS[chat_id] = 0
        log.info("jobtag failed chat=%s user=%s: %s", chat_id, user_id, e)


def jobtag_touch(bot, chat_id: int, user_id: int):
    """از on_group_text صدا زده میشه؛ سبکه و کار اصلی تو پس‌زمینه انجام میشه."""
    if not JOBTAG_ENABLED:
        return
    now = time.time()
    key = (chat_id, user_id)
    if now - _JOBTAG_CHECKED.get(key, 0) < JOBTAG_CHECK_EVERY:
        return
    if _JOBTAG_SKIP_UNTIL.get(key, 0) > now or _JOBTAG_CHAT_OFF.get(chat_id, 0) > now:
        return
    if len(_JOBTAG_CHECKED) > 20000:
        _JOBTAG_CHECKED.clear()
    _JOBTAG_CHECKED[key] = now
    t = asyncio.create_task(_jobtag_sync(bot, chat_id, user_id))
    _JOBTAG_TASKS.add(t)
    t.add_done_callback(_JOBTAG_TASKS.discard)


# ───────────────────────── هوش مصنوعی (رایگان، با چند سرویس پشتیبان) ─────────────────────────
# کاربر می‌نویسه «هوش سوالت» (یا روی یه پیام ریپلای می‌کنه و می‌نویسه «هوش ...»).
# کلیدها از متغیرهای Railway خونده میشن: GEMINI_API_KEY (اصلی) / GROQ_API_KEY (پشتیبان) / OPENROUTER_API_KEY (پشتیبان دوم، اختیاری).
# اگه سرویس اول سقفش پر شد یا خطا داد، خودکار میره سراغ بعدی. اگه هیچ کلیدی نباشه، قابلیت غیرفعاله.
AI_WORDS = ("هوش", "ai")
AI_USER_COOLDOWN = 20                                   # فاصله‌ی بین دو سؤال هر نفر (ثانیه)
AI_USER_PER_HOUR = 8                                    # حداکثر سؤال هر نفر در ساعت
AI_DAILY_MAX = int(os.environ.get("AI_DAILY_MAX", "800"))   # سقف کل سؤال‌های ربات در روز (برای اینکه پلن رایگان نسوزه)
AI_MAX_Q = 600                                          # حداکثر طول سؤال
AI_SYSTEM = ("تو یه دستیار بامزه و خودمونی تو یه گروه تلگرامی هستی. کوتاه و مفید جواب بده (حداکثر ۶ جمله). "
             "به زبان فارسی جواب بده مگه اینکه کاربر به زبان دیگه‌ای بنویسه. فحاشی و محتوای مضر نداشته باش.")
_AI_USER_TS: dict[int, list] = {}
_AI_PROV_OFF: dict[str, float] = {}
_AI_DAY = [None, 0]
_AI_LAST_ASK: dict[int, float] = {}


def _ai_providers() -> list:
    out = []
    k = os.environ.get("GEMINI_API_KEY")
    if k:
        out.append(("gemini", "https://generativelanguage.googleapis.com/v1beta/openai/chat/completions",
                    k, os.environ.get("GEMINI_MODEL", "gemini-2.5-flash")))
    k = os.environ.get("GROQ_API_KEY")
    if k:
        out.append(("groq", "https://api.groq.com/openai/v1/chat/completions",
                    k, os.environ.get("GROQ_MODEL", "llama-3.3-70b-versatile")))
    k = os.environ.get("OPENROUTER_API_KEY")
    if k:
        out.append(("openrouter", "https://openrouter.ai/api/v1/chat/completions",
                    k, os.environ.get("OPENROUTER_MODEL", "meta-llama/llama-3.3-70b-instruct:free")))
    return out


async def _ai_post(url: str, key: str, payload: dict) -> tuple:
    """(status_code, json یا None)"""
    headers = {"Authorization": f"Bearer {key}", "Content-Type": "application/json"}
    try:
        import httpx
    except Exception:
        httpx = None
    if httpx:
        async with httpx.AsyncClient(timeout=30) as c:
            r = await c.post(url, headers=headers, json=payload)
        try:
            return r.status_code, r.json()
        except Exception:
            return r.status_code, None

    def _call():
        import urllib.request, urllib.error
        req = urllib.request.Request(url, data=json.dumps(payload).encode(), headers=headers, method="POST")
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return r.status, json.loads(r.read().decode())
        except urllib.error.HTTPError as e:
            try:
                return e.code, json.loads(e.read().decode())
            except Exception:
                return e.code, None
    return await asyncio.to_thread(_call)


async def ai_answer(question: str, ref: str = "", system: str | None = None, history: list | None = None) -> str | None:
    """جواب هوش مصنوعی؛ اگه همه‌ی سرویس‌ها شکست خوردن None برمی‌گردونه."""
    user_msg = question if not ref else f"پیامی که کاربر روش ریپلای کرده: «{ref}»\n\nسؤال کاربر: {question}"
    for name, url, key, model in _ai_providers():
        if _AI_PROV_OFF.get(name, 0) > time.time():
            continue
        _msgs = [{"role": "system", "content": system or AI_SYSTEM}, *(history or []), {"role": "user", "content": user_msg}]
        payload = {"model": model, "max_tokens": 1024, "temperature": 0.8, "messages": _msgs}
        try:
            code, data = await _ai_post(url, key, payload)
            if code == 200 and data:
                txt = (data["choices"][0]["message"].get("content") or "").strip()
                if txt:
                    return txt
            # سقف پر شده یا خطای سرور: چند دقیقه این سرویس رو کنار می‌ذاریم
            _AI_PROV_OFF[name] = time.time() + (120 if code == 429 else 60)
            log.warning("ai provider %s failed: status=%s", name, code)
        except Exception as e:
            _AI_PROV_OFF[name] = time.time() + 60
            log.warning("ai provider %s error: %s", name, e)
    return None


async def ai_text(update: Update, context: ContextTypes.DEFAULT_TYPE, text: str) -> bool:
    msg = update.effective_message
    user = update.effective_user
    parts = text.split(None, 1)
    if not parts or parts[0].strip(":،,").lower() not in AI_WORDS:
        return False
    q = parts[1].strip() if len(parts) > 1 else ""
    ref = ""
    if msg.reply_to_message:
        ref = (msg.reply_to_message.text or msg.reply_to_message.caption or "").strip()[:500]
    if len(parts) == 1 and not ref:
        await msg.reply_text("بنویس: هوش سوالت 🤖\nیا روی یه پیام ریپلای کن و بنویس «هوش» + سوالت.")
        return True
    if not q:
        q = "این پیام رو توضیح بده یا جواب بده."
    if not _ai_providers():
        await msg.reply_text("هوش مصنوعی هنوز تو این ربات فعال نشده.")
        return True
    now = time.time()
    if now - _AI_LAST_ASK.get(user.id, 0) < AI_USER_COOLDOWN:
        await msg.reply_text("چند ثانیه صبر کن، بعد دوباره بپرس ⏳")
        return True
    hist = [t for t in _AI_USER_TS.get(user.id, []) if now - t < 3600]
    if len(hist) >= AI_USER_PER_HOUR:
        await msg.reply_text(f"تو این یه ساعت {AI_USER_PER_HOUR} تا سؤال پرسیدی؛ کم‌کم بعداً دوباره بپرس 🙏")
        _AI_USER_TS[user.id] = hist
        return True
    today = time.strftime("%Y-%m-%d")
    if _AI_DAY[0] != today:
        _AI_DAY[0], _AI_DAY[1] = today, 0
    if _AI_DAY[1] >= AI_DAILY_MAX:
        await msg.reply_text("سهمیه‌ی هوش مصنوعی امروز تموم شد، فردا برگرد 🌙")
        return True
    _AI_LAST_ASK[user.id] = now
    hist.append(now)
    _AI_USER_TS[user.id] = hist
    _AI_DAY[1] += 1
    try:
        await context.bot.send_chat_action(msg.chat_id, "typing")
    except Exception:
        pass
    ans = await ai_answer(q[:AI_MAX_Q], ref)
    if not ans:
        await msg.reply_text("الان هوش مصنوعی در دسترس نیست، یه کم بعد دوباره امتحان کن 😅")
        return True
    await msg.reply_text(ans[:3500])
    return True


# ───────── چت با «جینگو» (شخصیت خوابالو و بی‌حال) ─────────
# کاربر می‌نویسه «جینگو سلام» / «جینگو حالت چطوره» و ربات با لحن خوابالو جواب میده.
# از همون سرویس‌های هوش مصنوعیِ بالا (Gemini/Groq/OpenRouter) استفاده می‌کنه. فقط وقتی فعال میشه که پیام هیچ‌کدوم از
# دستورهای دیگه‌ی ربات (جینگو بت، جینگو سرقت، جینگو اسم پت ...) نباشه؛ برای همین آخرِ on_group_text صدا زده میشه.
JINGO_CHAT_RE = re.compile(r"^(?:ج[یي]نگو|jingo)(?:[\s:،,!؟?.]+(.*))?$", re.S | re.I)
JINGO_USER_COOLDOWN = 6          # فاصله‌ی بین دو پیام هر نفر (ثانیه)؛ تو این فاصله بی‌صدا نادیده گرفته میشه
JINGO_USER_PER_HOUR = 40         # حداکثر پیام هر نفر در ساعت
JINGO_MAX_Q = 500
JINGO_HIST_TURNS = 4             # چند رد و بدل آخر برای ادامه‌ی گفتگو یادش بمونه
JINGO_HIST_TTL = 1800            # ثانیه
JINGO_SYSTEM = (
    "تو «جینگو» هستی؛ یه آدم فوق‌العاده خوابالو، بی‌حال و بی‌جون که تو یه گروه تلگرامی هست. انگار همین الان از خواب بیدارش کردن "
    "یا هر لحظه ممکنه وسط حرف خوابش ببره. با لحن خودمونی و محاوره‌ای فارسی جواب بده. "
    "قواعد: (۱) خیلی کوتاه جواب بده، یک تا سه جمله‌ی کوتاه و بیشتر نه. (۲) لحنت کش‌دار و کند باشه: از «هوووم...»، «آآآه...»، «اوف...»، "
    "«خوابم میاد...»، «چشام باز نمیشه...»، خمیازه (مثلا «هاااا~»)، سه‌نقطه و کش دادن حروف استفاده کن؛ ولی تو هر پیام فقط یکی دو تاش رو بیار، زیاده‌روی نکن. "
    "(۳) هیچ انرژی و هیجانی نداشته باش؛ علامت تعجب زیاد و ایموجی هیجانی نذار؛ حداکثر یه ایموجی خوابالو مثل 😴 یا 🥱 یا 💤 گاهی. "
    "(۴) با اینکه بی‌حالی، به حرف کاربر واقعاً جواب بده؛ اگه سوالی پرسید جواب درست و کوتاه بده ولی با همون حال خواب‌آلود، و می‌تونی "
    "وسطش گله کنی که بیدارت کرده یا بگی بذار بخوابم. (۵) همیشه تو نقش بمون و نگو که هوش مصنوعی یا مدل زبانی هستی؛ اگه پرسیدن کی هستی، بگو جینگو و خوابت میاد. "
    "(۶) فحاشی، توهین، محتوای جنسی یا مضر نداشته باش. اگه چیز نامناسبی ازت خواستن، خوابالو و بی‌حوصله ردش کن. "
    "(۷) اگه کاربر به زبان دیگه‌ای نوشت به همون زبان جواب بده ولی همین شخصیت رو حفظ کن.")
_JG_LAST: dict[int, float] = {}
_JG_USER_TS: dict[int, list] = {}
_JG_HIST: dict[tuple, tuple] = {}   # (chat_id, user_id) -> (آخرین زمان, [پیام‌ها])


async def jingo_chat_text(update: Update, context: ContextTypes.DEFAULT_TYPE, text: str) -> bool:
    msg = update.effective_message
    user = update.effective_user
    m = JINGO_CHAT_RE.match(text.strip())
    if not m or not msg or not user:
        return False
    if _is_bot_text_command(text):   # یکی از دستورهای واقعیِ ربات (مثلا جینگو بت)؛ دست نزن
        return False
    q = (m.group(1) or "").strip()
    ref = ""
    if msg.reply_to_message:
        ref = (msg.reply_to_message.text or msg.reply_to_message.caption or "").strip()[:400]
    if not q:
        q = "(فقط اسمتو صدا زد)"
    if not _ai_providers():
        return False   # هوش مصنوعی فعال نیست؛ مثل قبل ساکت بمون
    now = time.time()
    if now - _JG_LAST.get(user.id, 0) < JINGO_USER_COOLDOWN:
        return True
    hist_ts = [t for t in _JG_USER_TS.get(user.id, []) if now - t < 3600]
    if len(hist_ts) >= JINGO_USER_PER_HOUR:
        _JG_USER_TS[user.id] = hist_ts
        return True
    today = time.strftime("%Y-%m-%d")
    if _AI_DAY[0] != today:
        _AI_DAY[0], _AI_DAY[1] = today, 0
    if _AI_DAY[1] >= AI_DAILY_MAX:
        await msg.reply_text("هوووم... امروز دیگه جون ندارم... برو بخواب 💤")
        return True
    _JG_LAST[user.id] = now
    hist_ts.append(now)
    _JG_USER_TS[user.id] = hist_ts
    _AI_DAY[1] += 1
    try:
        await context.bot.send_chat_action(msg.chat_id, "typing")
    except Exception:
        pass
    key = (msg.chat_id, user.id)
    last_t, hist = _JG_HIST.get(key, (0, []))
    if now - last_t > JINGO_HIST_TTL:
        hist = []
    system = JINGO_SYSTEM + f"\nاسم کسی که باهات حرف می‌زنه: {(user.first_name or user.full_name or '').strip()[:30]}"
    ans = await ai_answer(q[:JINGO_MAX_Q], ref, system=system, history=hist)
    if not ans:
        await msg.reply_text("هاااا... نمی‌کشم الان... بعداً بیا 😴")
        return True
    ans = ans[:900]
    hist = (hist + [{"role": "user", "content": q[:JINGO_MAX_Q]}, {"role": "assistant", "content": ans}])[-2 * JINGO_HIST_TURNS:]
    _JG_HIST[key] = (now, hist)
    if len(_JG_HIST) > 3000:   # جلوگیری از رشد بی‌پایان حافظه
        for k in [k for k, v in _JG_HIST.items() if now - v[0] > JINGO_HIST_TTL]:
            _JG_HIST.pop(k, None)
    await msg.reply_text(ans)
    return True


async def on_group_text(update: Update, context: ContextTypes.DEFAULT_TYPE):
    msg = update.effective_message
    user = update.effective_user
    if not msg or not msg.text or not user or user.is_bot:
        return
    if not msg.sender_chat:
        jobtag_touch(context.bot, msg.chat_id, user.id)   # تگ شغل (فقط وقتی ربات ادمین باشه)
    # حذف فاصله و کاراکترهای نامرئی (کیبوردهای فارسی گاهی نیم‌فاصله اضافه می‌کنن)
    text = "".join(ch for ch in msg.text if ch not in "\u200c\u200d\u200e\u200f\u200b\ufeff").strip()
    log.info("group text from %s: %r", user.id, msg.text)
    if await duel_setup_text(update, context, text):   # مبلغ دوئل درسی
        return
    if await sports_custom_text(update, context, text):   # مبلغ دلخواه میز ورزشی
        return
    if await ai_text(update, context, text):   # هوش مصنوعی: «هوش سوالت»
        return
    if await jagsal_group_text(update, context, text):
        return
    _tm = time.time()
    if len(text) >= 2 and _tm - _TASK_MSG_TS.get(user.id, 0) >= 15:
        _TASK_MSG_TS[user.id] = _tm
        await task_event(context.bot, msg.chat_id, user.id, "msg", name=user.full_name)
    if await event_text(update, context, text):
        return
    if await boss_text(update, context, text):
        return
    if await spy_text(update, context, text):
        return
    if await bodyguard_text(update, context, text):
        return
    if await pet_text(update, context, text):
        return
    if await cafe_text(update, context, text):
        return
    if _word_key(text) in ("تسک", "تسکها", "تسکروزانه", "تسکهفتگی", "tasks"):
        await show_tasks(update, context)
        return
    if norm_word(text) == ME_WORD:
        await show_me(update, context)
        return
    if norm_word(text).replace(" ", "").lower() in JOBS_WORDS:
        await show_jobs(update, context)
        return
    if norm_word(text).replace(" ", "").lower() in EDU_WORDS:
        await show_edu(update, context)
        return
    if norm_word(text).replace(" ", "").lower() in LESSON_WORDS:
        await show_lessons(update, context)
        return
    if norm_word(text).replace(" ", "").lower() in SHIFT_WORDS:
        await show_shift(update, context)
        return
    if _word_key(text) in JM_WORDS:
        await profit_collect(update, context)
        return
    if _word_key(text) in TOP_WORDS:
        await top(update, context)
        return
    panel_key = _word_key(text)
    if panel_key in ("خودمایناروببین", "خودم", "پنلمن", "پنلشخصی") or panel_key.startswith("خودمایناروببین"):
        await show_self_panel(update, context)
        return
    if _word_key(text) in ("دست", "هوش"):
        await show_self_panel(update, context)
        return
    if _word_key(text) == "بانک":
        await show_bank(update, context)
        return
    if _word_key(text) == "خونه" or _word_key(text) == "خانه" or _word_key(text) == "املاک":
        await show_homes(update, context)
        return
    if await heist_text(update, context, text):
        return
    if await marriage_text(update, context, text):
        return
    if await gift_hug_text(update, context, text):
        return
    if await handle_bank_transfer(update, context, text):
        return
    if _word_key(text) in WALLET_WORDS:
        await wallet(update, context)
        return
    if _word_key(text) in CAR_WORDS:
        await show_garage(update, context)
        return
    if norm_word(text).startswith("انتقال"):
        await on_transfer_request(update, context, text)
        return
    if _word_key(text) in ("دوئلدرسی", "دوئلدرس"):
        await duel_request(update, context)
        return
    if await casino_text(update, context, text):
        return
    if await theft_text(update, context, text):
        return
    if _word_key(text) in ("خلاف", "دزدی", "سرقت"):
        await show_robbery_menu(update, context)
        return
    if await jingo_chat_text(update, context, text):   # چت با جینگوی خوابالو: «جینگو سلام»
        return
    # «امتیاز» زدن حذف شد؛ دیگه هیچ پاداشی نداره و ربات به این کلمه جواب نمیده.
    return


async def debug_channels(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/check — نشون میده چک عضویت هر کانال چی برمی‌گردونه (برای عیب‌یابی)."""
    me = await context.bot.get_me()
    uid = update.effective_user.id
    lines = [f"🤖 ربات: @{me.username}\n"]
    for ch in CHANNELS:
        try:
            chat = await context.bot.get_chat(ch)
            m = await context.bot.get_chat_member(ch, uid)
            lines.append(f"✅ {ch} ({chat.type}) → وضعیت شما: {m.status}")
        except Exception as e:
            lines.append(f"❌ {ch} → {type(e).__name__}: {e}")
    await update.message.reply_text(BP("\n".join(lines)), parse_mode="HTML")


def resolve_section(word: str):
    w = word.strip().lower()
    return w if w in SECTIONS else ALIASES.get(word.strip())


def sections_text() -> str:
    lines = []
    for key, (title, names) in SECTIONS.items():
        slots = "، ".join(f"{i}={n}" for i, n in enumerate(names, 1))
        lines.append(f"{title} ({key}): {slots}")
    return "\n".join(lines)


async def show_emojis(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/emojis — ایموجی فعلی هر بخش رو نشون میده."""
    blocks = []
    for key, (title, names) in SECTIONS.items():
        rows = [
            f"{i} ({n}) → " + (ce(key, i, "⭐") if (key, i) in EMOJI_IDS else "تنظیم نشده")
            for i, n in enumerate(names, 1)
        ]
        blocks.append(f"{title} ({key})\n" + "\n".join(rows))
    await update.message.reply_text(B("\n\n".join(blocks)), parse_mode="HTML")


async def emoji_ids(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/eid — توی پی‌وی: «/eid 😀😀» رو با ایموجی‌های پرمیوم بفرست، یا روی پیامی که ایموجی پرمیوم داره ریپلای کن و /eid بزن؛ آیدی‌ها رو میده."""
    msg = update.effective_message
    ids = []
    for m in (msg, msg.reply_to_message):
        if not m:
            continue
        for e in list(m.entities or []) + list(m.caption_entities or []):
            if e.type == "custom_emoji" and e.custom_emoji_id and e.custom_emoji_id not in ids:
                ids.append(e.custom_emoji_id)
    if not ids:
        await msg.reply_text("بعد از /eid ایموجی پرمیوم بفرست (مثلاً /eid ⭐️ با ایموجی پرمیوم)، یا روی پیامی که ایموجی پرمیوم داره ریپلای کن و /eid بزن.")
        return
    lines = [f'<tg-emoji emoji-id="{i}">▫️</tg-emoji> <code>{i}</code>' for i in ids[:40]]
    try:
        await msg.reply_text("\n".join(lines), parse_mode="HTML")
    except Exception:
        await msg.reply_text("\n".join(ids[:40]))


async def support_emoji_code_request(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """پشتیبان روی پیام ایموجی ریپلای می‌کند و «.کدشو میخوام» می‌فرستد."""
    msg = update.effective_message
    user = update.effective_user
    if not msg or not user or msg.chat.type != "private":
        return
    if not (has_perm(user.id, "panel") and has_perm(user.id, "miniapp")):
        return
    target = msg.reply_to_message
    if target is None:
        await msg.reply_text("برای گرفتن کد، روی پیام ایموجی پرمیوم ریپلای کن و بنویس: .کدشو میخوام")
        return
    ids = []
    for entity in list(target.entities or []) + list(target.caption_entities or []):
        if entity.type == "custom_emoji" and entity.custom_emoji_id and entity.custom_emoji_id not in ids:
            ids.append(entity.custom_emoji_id)
    if not ids:
        await msg.reply_text("در پیام ریپلای‌شده ایموجی پرمیوم پیدا نکردم. پیام اصلی را فوروارد کن و دوباره امتحان کن.")
        return
    lines = [f'<tg-emoji emoji-id="{eid}">▫️</tg-emoji> <code>{eid}</code>' for eid in ids[:40]]
    try:
        await msg.reply_text("🧩 کد ایموجی پرمیوم:\n" + "\n".join(lines), parse_mode="HTML")
    except Exception:
        await msg.reply_text("🧩 کد ایموجی پرمیوم:\n" + "\n".join(ids[:40]))


async def emoji_ids_auto(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """هر پیام پی‌وی که ایموجی پرمیوم داره (حتی فورواردشده از پیام‌های ذخیره‌شده) رو فوری با آیدی‌ها جواب میده."""
    ud = context.user_data or {}
    if any(k in ud for k in ("await_jobs", "adm", "support_add_wait", "bank_action", "buy_wait", "gift_order", "acc_transfer")):
        return   # وسط یه جریان دیگه‌ست؛ دخالت نکن
    await emoji_ids(update, context)


async def my_id(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/myid — آیدی عددی خودت رو میده تا بذاری تو ADMIN_IDS."""
    await update.message.reply_text(BP(f"آیدی شما: {update.effective_user.id}"), parse_mode="HTML")


SETEMOJI_HELP = (
    "برای عوض کردن ایموجی‌های یه بخش، اسم بخش + ایموجی‌های پرمیوم رو بفرست:\n\n"
    "/setemoji jagh 🤛💦🔥🏆😐⏳\n"
    "/setemoji top 👑\n"
    "/setemoji wallet 💰\n\n"
    "ایموجی‌ها به ترتیب میرن جای اسلت‌های اون بخش. اگه فقط یکی رو می‌خوای عوض کنی، "
    "شماره‌ی اسلت رو بعد از اسم بخش بنویس:\n"
    "/setemoji jagh 3 🔥  (فقط آتش عوض میشه)\n\n"
    "بخش‌ها و اسلت‌هاشون:\n" + sections_text() + "\n\nبرای دیدن وضعیت فعلی: /emojis"
)


async def set_emoji(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/setemoji <بخش> [شماره‌ی اسلت] <ایموجی‌های پرمیوم> — فقط پشتیبان‌ها (ADMIN_IDS)."""
    msg = update.message
    if not has_perm(update.effective_user.id, "emoji"):
        await msg.reply_text(BP("این دستور فقط برای پشتیبان‌هاست یا دسترسی‌اش بهت داده نشده. آیدی خودت رو با /myid بگیر و به صاحب ربات بده."), parse_mode="HTML")
        return

    args = context.args or []
    ents = sorted(
        (e for e in (msg.entities or []) if e.type == "custom_emoji"), key=lambda e: e.offset
    )
    if not args:
        await msg.reply_text(BP(SETEMOJI_HELP), parse_mode="HTML")
        return

    section = resolve_section(args[0])
    if section is None:
        await msg.reply_text(BP(f"بخشی به اسم «{args[0]}» نداریم.\n\nبخش‌ها:\n" + sections_text()), parse_mode="HTML")
        return
    if not ents:
        await msg.reply_text(BP("ایموجی پرمیوم پیدا نشد. دستور رو همراه ایموجی‌های پرمیوم بفرست.\n\n" + SETEMOJI_HELP), parse_mode="HTML")
        return

    first = int(args[1]) if len(args) > 1 and args[1].isdigit() else 1
    title, names = SECTIONS[section]
    if first < 1 or first + len(ents) - 1 > len(names):
        await msg.reply_text(
            BP(
                f"بخش «{title}» فقط {len(names)} اسلت داره. از اسلت {first} با {len(ents)} ایموجی جا نمیشه.\n\n"
                + sections_text()
            ),
            parse_mode="HTML",
        )
        return

    for i, e in enumerate(ents):
        slot = first + i
        await pool.execute(
            "INSERT INTO emoji_slots (section, slot, emoji_id) VALUES ($1, $2, $3) "
            "ON CONFLICT (section, slot) DO UPDATE SET emoji_id = EXCLUDED.emoji_id",
            section,
            slot,
            e.custom_emoji_id,
        )
        EMOJI_IDS[(section, slot)] = e.custom_emoji_id

    lines = [f"{first + i} ({names[first + i - 1]}) → {ce(section, first + i, '⭐')}" for i in range(len(ents))]
    await msg.reply_text(B(f"✅ بخش «{title}» ذخیره شد:\n" + "\n".join(lines)), parse_mode="HTML")


# ───────────────────────── کاراکتر من ─────────────────────────
def card_text(name: str, gender: str, balance: int, jaghs: int, work_count: int = 0, title_override: str | None = None, job_level: int = 0, msg_total: int = 0, level: int | None = None) -> str:
    # سطح/تصویر کاراکتر با سطحی که برای شغل فعلی در جدول JOBS تعریف شده هماهنگ است.
    job = current_job(gender, jaghs, work_count, job_level) if gender in JOBS else None
    real_lvl = lvl = max(1, min(int(level or 1), len(LEVEL_THRESHOLDS)))   # سطح از واحد درسی و مدرک
    title, tagline = CHARACTERS[gender][lvl - 1]
    if title_override:   # کاراکتر ویژه: اسمش جای اسم شغلی میاد
        title, tagline = title_override, "کاراکتر ویژه ✨"
    lines = [
        f"{ce('me', 1, '🎖')} {html.escape(name)}",
        "",
        f"سطح {real_lvl}: {html.escape(title)} {'' if title_override else char_emojis(gender, lvl)}",
        html.escape(tagline),
        "",
        f"{ce('wallet', 1, '💰')} دارایی: {balance:,} تومن",
        f"💼 کارهای انجام‌شده: {work_count:,}",
        f"💬 پیام‌های گروه: {int(msg_total or 0):,}",
    ]
    _jl = max(0, min(int(job_level or 0), len(JOBS[gender]))) if gender in JOBS else 0
    if gender in JOBS and _jl < len(JOBS[gender]):
        lines.append(f"{ce('me', 2, '⬆️')} شغل بعدی: «{html.escape(JOBS[gender][_jl][0])}» (بنویس «شغل»)")
    else:
        lines.append(f"{ce('top', 1, '👑')} به بالاترین سطح رسیدی!")
    return B("\n".join(lines))



# ───────────── عکس کاراکتر با دارایی کاربر ─────────────
BASE_DIR = Path(__file__).parent
_FA_DIGITS = str.maketrans("0123456789,", "۰۱۲۳۴۵۶۷۸۹،")


def _first_existing(*paths: Path) -> Path | None:
    for p in paths:
        if p.exists():
            return p
    return None


def card_path(gender: str, level: int) -> Path | None:
    """عکس کارت: یا کنار bot.py با اسم m_3.png / f_3.png، یا تو پوشه‌ی chars/m/char_3.png"""
    return _first_existing(
        BASE_DIR / f"{gender}_{level}.png",
        BASE_DIR / "chars" / gender / f"char_{level}.png",
    )



