_EDU_SEEN: dict = {}
EDU_TF = ["✅ درست", "❌ نادرست"]


def _is_tf(options) -> bool:
    return list(options) == EDU_TF


def _m_fa(n: int) -> str:
    """۳۰۰۰۰۰۰ ← «3m»، ۰ ← «رایگان»."""
    n = int(n)
    if n <= 0:
        return "رایگان"
    return f"{n / 1_000_000:g}m" if n >= 1_000_000 else f"{n:,}"


def _jlvl(row) -> int:
    try:
        return int(row["job_level"] or 0)
    except Exception:
        return 0


def _jsel(row) -> int:
    """شمارهٔ شغل فعالِ انتخاب‌شده (۱..job_level)؛ اگه انتخابی نباشه بالاترین شغلی که گرفته."""
    jl = _jlvl(row)
    try:
        s = int(row["job_sel"] or 0)
    except Exception:
        s = 0
    return s if 1 <= s <= jl else jl


def _edeg(row) -> int:
    try:
        return max(0, min(int(row["edu_degree"] or 0), len(EDU_DEGREES)))
    except Exception:
        return 0


def _eunits(row) -> int:
    try:
        return int(row["edu_units"] or 0)
    except Exception:
        return 0


def _deg_name(d: int) -> str:
    return EDU_DEGREES[d - 1][0] if 1 <= d <= len(EDU_DEGREES) else "بدون مدرک"


