def _edu_diff(units: int) -> str:
    return "آسان" if units <= 2 else ("متوسط" if units == 3 else ("سخت" if units == 4 else "خیلی سخت"))


def _edu_progress(row, units: int):
    """(اسم شغل بعدی، واحد فعلی، هدف یا None، متن باقی‌مانده بدون ایموجی)"""
    jobs = JOBS.get(row["gender"], [])
    ji = _jlvl(row)
    if ji >= len(jobs):
        return "شغل بعدی", units, None, "همه‌ی شغل‌ها رو گرفتی"
    name = jobs[ji][0]
    need = JOB_DEGREE_NEED[ji] if ji < len(JOB_DEGREE_NEED) else 0
    if need <= 0 or _edeg(row) >= need:
        return name, units, None, f"برای شغل «{name}» واحد اضافه‌ای لازم نیست؛ مدرک لازم رو داری"
    target = EDU_DEGREES[need - 1][1]
    return name, units, target, f"{max(0, target - units):,} واحد تا «{name}»"


def _edu_cd(row) -> float:
    """فاصله‌ی ثابت بین کلاس‌ها: ۶ دقیقه و ۴۵ ثانیه."""
    return float(EDU_COOLDOWN)


def _units_left_for_next_job(row, units: int) -> tuple[str, str]:
    gender = row["gender"]
    jobs = JOBS.get(gender, [])
    job_index = _jlvl(row)
    if job_index >= len(jobs):
        return "شغل بعدی", "همه‌ی شغل‌ها رو گرفتی 👑"
    job_name = jobs[job_index][0]
    degree_need = JOB_DEGREE_NEED[job_index] if job_index < len(JOB_DEGREE_NEED) else 0
    if degree_need <= 0 or _edeg(row) >= degree_need:
        return job_name, "واحد اضافه‌ای لازم نیست؛ مدرک لازم رو داری ✅"
    required_units = EDU_DEGREES[degree_need - 1][1]
    remaining = max(0, required_units - int(units))
    return job_name, f"{remaining:,} واحد"


def _subj_label(key: str) -> str:
    nm, eid, fb = EDU_SUBJ[key]
    return f'<tg-emoji emoji-id="{eid}">{fb}</tg-emoji> {nm}'


def edu_bar_line(row) -> str:
    """نوار واحد تا مدرک بعدی (مثل نوار سطح)."""
    deg, units = _edeg(row), _eunits(row)
    if deg >= len(EDU_DEGREES):
        pct = 100.0
    else:
        lo = EDU_DEGREES[deg - 1][1] if deg >= 1 else 0
        hi = EDU_DEGREES[deg][1]
        pct = max(0.0, min(100.0, (units - lo) / max(1, hi - lo) * 100))
    return f"{_edu_emoji(EDU_UNIT_EMOJI, '📚')} واحد تا مدرک بعدی\n{_panel_bar('edu', '🟪', '⬜', pct)}"


def edu_rich_html(row) -> str:
    deg = _edeg(row)
    out = ["<table><tr><th>مدرک</th><th>واحد</th><th>شهریه</th><th>وضعیت</th></tr>"]
    for i, (name, units, fee) in enumerate(EDU_DEGREES, 1):
        st = f"{lock_open()} داری ✅" if deg >= i else f"{lock_closed()} نداری ❌"
        out.append(f"<tr><td>🎓 {html.escape(name)}</td><td>{units:,}</td><td>{_m_fa(fee)}</td><td>{st}</td></tr>")
    out.append("</table>")
    return "".join(out)


def edu_text(row) -> str:
    deg = _edeg(row)
    cells = [("مدرک", "واحد", "شهریه", "وضعیت")]
    for i, (name, units, fee) in enumerate(EDU_DEGREES, 1):
        cells.append((name, f"{units:,}", _m_fa(fee), "داری ✅" if deg >= i else "نداری ❌"))
    w = [max(_w(r[c]) for r in cells) for c in range(4)]
    sep = "─┼─".join("─" * w[c] for c in range(4))
    lines = []
    for k, r in enumerate(cells):
        lines.append(" │ ".join(_pad(r[c], w[c]) for c in range(4)))
        if k == 0:
            lines.append(sep)
    return f"{_edu_emoji(EDU_CLASS_EMOJI, '🎓')} <b>تحصیلات</b>\n<pre>{html.escape(chr(10).join(lines))}</pre>"


def edu_panel(row, uid: int):
    """(متن، کیبورد) خلاصه‌ی تحصیل با دکمه‌های درس / گرفتن مدرک / شغل."""
    deg, units = _edeg(row), _eunits(row)
    lines = [f"{_edu_emoji(EDU_UNIT_EMOJI, '📚')} واحدهای تو: <b>{units:,}</b>", f"🎓 مدرک فعلی: <b>{html.escape(_deg_name(deg))}</b>", edu_bar_line(row)]
    rows = [[btn("درس بخون", None, icon=EDU_STUDY_EMOJI, callback_data=f"ed:lessons:{uid}")]]
    if deg < len(EDU_DEGREES):
        name, need, fee = EDU_DEGREES[deg]
        left = max(0, need - units)
        if left > 0:
            lines.append(f"⬆️ مدرک بعدی: <b>{html.escape(name)}</b> — {left:,} واحد دیگه (شهریه {_m_fa(fee)})")
        else:
            lines.append(f"✅ واحدهات برای <b>{html.escape(name)}</b> کافیه! شهریه: {_m_fa(fee)}")
            rows.insert(0, [btn(f"🎓 گرفتن مدرک {name} · {_m_fa(fee)}", "success", callback_data=f"ed:deg:{uid}")])
    else:
        lines.append("👑 بالاترین مدرک رو داری!")
    rows.append([btn("💼 شغل‌ها", "primary", callback_data=f"jb:menu:{uid}")])
    return "\n".join(lines), InlineKeyboardMarkup(rows)


def jobs_rows(gender: str, row):
    """[(ایموجی، اسم، حقوق، مدرک لازم، هزینه)]"""
    rows = []
    for i, (name, _lvl) in enumerate(JOBS[gender]):
        lo, hi = JOB_PAY[i]
        need = JOB_DEGREE_NEED[i]
        rows.append((JOB_GLYPHS.get(name, "💼"), name, lo if lo == hi else f"{lo}-{hi}",
                     _deg_name(need) if need else "ندارد", _m_fa(JOB_FEES[i])))
    return rows


def _tg(eid, fb: str) -> str:
    return f'<tg-emoji emoji-id="{eid}">{fb}</tg-emoji>'


def _job_eid(gender: str, i: int):
    """آیدی ایموجی پرمیومِ شغل شماره‌ی i (از /setemoji job یا جدول فورواردشده)."""
    eid = EMOJI_IDS.get(("job", i + 1))
    if not eid:
        learned = (CUSTOM_JOBS.get(gender) or {}).get("job_emojis") or []
        if i < len(learned):
            eid = learned[i]
    return eid


def jobs_panel(row, uid: int):
    """(متن، کیبورد) شغل فعال + دکمه‌ی انتخاب بین شغل‌هایی که داره (فقط یکی فعاله) + دکمه‌ی خرید شغل بعدی."""
    g = row["gender"]
    jl, deg, sel = _jlvl(row), _edeg(row), _jsel(row)
    cur = JOBS[g][sel - 1][0] if sel >= 1 else "بیکار"
    lines = [f"{ce('me', 1, '🎖')} شغل فعال: <b>{html.escape(cur)}</b>",
             f"{_tg(EID_TROPHY, '🏆')} مدرک: <b>{html.escape(_deg_name(deg))}</b>"]
    rows = []
    if jl:
        lines.append(f"{lock_open()} شغلی که می‌خوای باهاش «کار» کنی رو انتخاب کن (فقط یکی فعاله):")
        btns = []
        for i in range(jl):
            on = (i + 1 == sel)
            btns.append(btn(("✅ " if on else "") + JOBS[g][i][0], "success" if on else "primary",
                            icon=_job_eid(g, i) or LOCK_OPEN_ID, callback_data=f"jb:sel:{uid}:{i + 1}"))
        for k in range(0, len(btns), 2):
            rows.append(btns[k:k + 2])
    if jl < len(JOBS[g]):
        nm, need, fee = JOBS[g][jl][0], JOB_DEGREE_NEED[jl], JOB_FEES[jl]
        need_txt = _deg_name(need) if need else "بدون مدرک"
        lines.append(f"{ce('me', 2, '⬆️')} شغل بعدی: <b>{html.escape(nm)}</b> — مدرک: {need_txt} · هزینه: {_m_fa(fee)}")
        if deg >= need:
            rows.append([btn(f"گرفتن شغل {nm} · {_m_fa(fee)}", "success", icon=EID_MONEY, callback_data=f"jb:take:{uid}")])
        else:
            lines.append(f"{lock_closed()} مدرکش رو نداری؛ از «تحصیل» درس بخون و مدرکش رو بگیر.")
    else:
        lines.append(f"{_tg(EID_TROPHY, '👑')} همه‌ی شغل‌ها رو داری!")
    rows.append([btn("تحصیل و درس", "primary", icon=EDU_CLASS_EMOJI, callback_data=f"ed:menu:{uid}")])
    return "\n".join(lines), InlineKeyboardMarkup(rows)


def jobs_rich_html(gender: str, row) -> str:
    """جدول واقعی (Rich Message تلگرام)، شخصی برای هر کاربر: قفل باز برای شغل‌هایی که گرفته، «فعال» برای شغل انتخاب‌شده."""
    jl, sel = _jlvl(row), _jsel(row)
    out = ["<table><tr><th>شغل</th><th>حقوق</th><th>مدرک</th><th>هزینه</th><th>وضعیت</th></tr>"]
    for i, (glyph, name, pay, need, fee) in enumerate(jobs_rows(gender, row)):
        if i + 1 == sel:
            st = f"{lock_open()} <b>فعال ✅</b>"
        elif i < jl:
            st = f"{lock_open()} داری"
        else:
            st = f"{lock_closed()}"
        out.append(f"<tr><td>{job_glyph(gender, i, name)} {html.escape(name)}</td><td>{pay}</td><td>{need}</td><td>{fee}</td><td>{st}</td></tr>")
    out.append("</table>")
    return "".join(out)


def jobs_text(gender: str, row) -> str:
    """نسخه‌ی جایگزین: جدول مونواسپیس داخل <pre> (اگه Rich Message کار نکرد)."""
    jl, sel = _jlvl(row), _jsel(row)
    cells = [("شغل", "حقوق", "مدرک", "هزینه", "وضعیت")]
    for i, (glyph, name, pay, need, fee) in enumerate(jobs_rows(gender, row)):
        cells.append((name, pay, need, fee, "فعال ✅" if i + 1 == sel else ("داری 🔓" if i < jl else "🔒")))
    w = [max(_w(r[c]) for r in cells) for c in range(5)]
    sep = "─┼─".join("─" * w[c] for c in range(5))
    lines = []
    for k, r in enumerate(cells):
        lines.append(" │ ".join(_pad(r[c], w[c]) for c in range(5)))
        if k == 0:
            lines.append(sep)
    return f"{ce('me', 1, '🎖')} <b>شغل‌ها</b>\n<pre>{html.escape(chr(10).join(lines))}</pre>"


def _rich_panel(rich_html: str, panel_text: str) -> str:
    """جدول + خط‌های وضعیت، همه تو یه پیام."""
    return rich_html + "".join(f"<p>{ln}</p>" for ln in panel_text.split("\n") if ln.strip())


async def _send_table(context, msg, rich_html: str, fallback_text: str, panel_text: str, kb):
    """جدول واقعی تلگرام + دکمه‌ها همه تو یه پیام. اگه Rich کار نکرد جدول مونواسپیس + دکمه‌ها تو یه پیام معمولی."""
    rp = ReplyParameters(message_id=msg.message_id, allow_sending_without_reply=True)
    try:
        await context.bot._post("sendRichMessage", {
            "chat_id": msg.chat_id,
            "rich_message": {"html": _rich_panel(rich_html, panel_text)},
            "reply_parameters": rp.to_dict(),
            "reply_markup": kb.to_dict(),
        })
        return
    except Exception:
        log.warning("sendRichMessage failed, using <pre> table", exc_info=True)
    text = fallback_text + "\n\n" + panel_text
    try:
        await msg.reply_text(B(text), parse_mode="HTML", reply_markup=kb, reply_parameters=rp)
    except Exception:
        log.exception("table message failed, retrying without premium emojis")
        await msg.reply_text(_strip_te(B(text)), parse_mode="HTML", reply_markup=kb, reply_parameters=rp)


async def _table_edit(q, rich_html: str, fallback_text: str, panel_text: str, kb):
    """همون پیامِ جدول رو (با دکمه‌هاش) آپدیت می‌کنه؛ پیام جدید نمیاره."""
    try:
        await q.get_bot()._post("editMessageText", {
            "chat_id": q.message.chat_id, "message_id": q.message.message_id,
            "rich_message": {"html": _rich_panel(rich_html, panel_text)},
            "reply_markup": kb.to_dict(),
        })
        return
    except Exception as e:
        if "not modified" in str(e).lower():
            return
        log.info("rich edit failed, falling back to text edit: %s", e)
    await _edu_edit(q, fallback_text + "\n\n" + panel_text, kb)


async def _jobs_view(q, row, uid: int, head: str = ""):
    text, kb = jobs_panel(row, uid)
    await _table_edit(q, jobs_rich_html(row["gender"], row), jobs_text(row["gender"], row), (head + "\n" if head else "") + text, kb)


async def _edu_view(q, row, uid: int, head: str = ""):
    text, kb = edu_panel(row, uid)
    await _table_edit(q, edu_rich_html(row), edu_text(row), (head + "\n" if head else "") + text, kb)


async def show_jobs(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/jobs یا نوشتن «شغل» / «شغل ها» — جدول شغل‌ها + دکمه‌های انتخاب شغل فعال و گرفتن شغل بعدی، همه تو یه پیام."""
    msg, user = update.effective_message, update.effective_user
    await upsert_user(user.id, user.full_name)
    row = await get_user(user.id)
    if not row["gender"]:
        await ask_gender(update, context)
        return
    panel_text, kb = jobs_panel(row, user.id)
    await _send_table(context, msg, jobs_rich_html(row["gender"], row), jobs_text(row["gender"], row), panel_text, kb)


async def show_edu(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """«تحصیل» / «مدرک» — جدول مدرک‌ها (واحد، شهریه، وضعیت) + دکمه‌ی درس و گرفتن مدرک تو همون پیام."""
    msg, user = update.effective_message, update.effective_user
    await upsert_user(user.id, user.full_name)
    row = await get_user(user.id)
    if not row["gender"]:
        await ask_gender(update, context)
        return
    panel_text, kb = edu_panel(row, user.id)
    await _send_table(context, msg, edu_rich_html(row), edu_text(row), panel_text, kb)


def _lesson_kb(uid: int) -> InlineKeyboardMarkup:
    btns = [btn(EDU_SUBJ[key][0], None, icon=EDU_SUBJ[key][1], callback_data=f"ed:subj:{uid}:{key}") for key in EDU_SUBJECTS]
    rows = [btns[i:i + 2] for i in range(0, len(btns), 2)]
    rows.append([btn("🔙 تحصیل", None, callback_data=f"ed:menu:{uid}")])
    return InlineKeyboardMarkup(rows)


def _lesson_text(row) -> str:
    left = _edu_cd(row) - (time.time() - float(row["edu_last"] or 0))
    t = f"{_edu_emoji(EDU_STUDY_EMOJI, '📚')} <b>کلاس درس</b>\nموضوع کلاس رو انتخاب کن؛ هر پاسخ درست ۲ تا ۴ واحد داره.\n\n{_edu_emoji(EDU_UNIT_EMOJI, '💠')} واحدهای تو: <b>{_eunits(row):,}</b>\n{edu_bar_line(row)}"
    if left > 0:
        t += f"\n⏳ درس بعدی: <b>{_duration_fa(left)}</b> دیگه"
    return t


async def show_lessons(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """«درس» — انتخاب موضوع درس."""
    msg, user = update.effective_message, update.effective_user
    await upsert_user(user.id, user.full_name)
    row = await get_user(user.id)
    if not row["gender"]:
        await ask_gender(update, context)
        return
    rp = ReplyParameters(message_id=msg.message_id, allow_sending_without_reply=True)
    await msg.reply_text(B(_lesson_text(row)), parse_mode="HTML", reply_markup=_lesson_kb(user.id), reply_parameters=rp)


async def _edu_edit(q, text: str, kb=None, bold: bool = True):
    """پیام فعلی رو ادیت می‌کنه (متن معمولی ← بدون ایموجی پرمیوم ← پیام Rich)؛ فقط اگه همه شکست خورد پیام جدید میده."""
    _W = B if bold else (lambda x: x)
    for t_ in (_W(text), _strip_te(_W(text))):
        try:
            await q.edit_message_text(t_, parse_mode="HTML", reply_markup=kb)
            return
        except Exception as e:
            if "not modified" in str(e).lower():
                return
    try:
        paras = "".join(f"<p>{ln}</p>" for ln in text.split("\n") if ln.strip())
        await q.get_bot()._post("editMessageText", {
            "chat_id": q.message.chat_id, "message_id": q.message.message_id,
            "rich_message": {"html": paras}, "reply_markup": kb.to_dict() if kb else None,
        })
        return
    except Exception as e:
        if "not modified" in str(e).lower():
            return
    try:
        await q.message.reply_text(_W(text), parse_mode="HTML", reply_markup=kb)
    except Exception:
        log.warning("edu edit failed", exc_info=True)


async def edu_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    p = q.data.split(":")
    try:
        act, uid = p[1], int(p[2])
    except (IndexError, ValueError):
        await q.answer(); return
    if q.from_user.id != uid:
        await q.answer("این پنل مال شما نیست.", show_alert=True); return
    row = await get_user(uid)
    if not row:
        await q.answer(); return
    now = time.time()
    if act == "menu":
        await q.answer()
        await _edu_view(q, row, uid)
    elif act == "lessons":
        await q.answer()
        await _edu_edit(q, _lesson_text(row), _lesson_kb(uid))
    elif act == "subj":
        key = p[3] if len(p) > 3 else ""
        if key not in EDU_SUBJECTS:
            await q.answer(); return
        label, qs = EDU_SUBJECTS[key]
        seen = _EDU_SEEN.get((uid, key), [])
        avail = [i for i in range(len(qs)) if i not in seen] or list(range(len(qs)))
        if len(avail) == len(qs):
            seen = []
        qi = random.choice(avail)
        ok = await pool.fetchval(
            "UPDATE users SET edu_last=$2::double precision, edu_pending=$3 WHERE user_id=$1 "
            "AND edu_last <= $2::double precision - $4::double precision RETURNING 1",
            uid, now, f"{key}:{qi}", _edu_cd(row))
        if not ok:
            left = _edu_cd(row) - (now - float(row["edu_last"] or 0))
            await q.answer(f"درس بعدی: {_duration_fa(max(left, 1))} دیگه", show_alert=True); return
        _EDU_SEEN[(uid, key)] = (seen + [qi])[-len(qs):]
        if len(_EDU_SEEN) > 20000:
            _EDU_SEEN.clear()
        question, options, _right, units = qs[qi]
        order = list(range(len(options)))
        if not _is_tf(options):   # درست/نادرست همیشه به همین ترتیب؛ بقیه قاطی میشن
            random.shuffle(order)
        _ob = [btn(options[o], None, callback_data=f"ed:ans:{uid}:{key}:{qi}:{o}") for o in order]
        kb = InlineKeyboardMarkup([_ob[i:i + 2] for i in range(0, len(_ob), 2)])
        await q.answer()
        label = _subj_label(key)
        _cur = _eunits(row)
        _jn, _c, _tg_, _rem = _edu_progress(row, _cur)
        if _tg_:
            _pct = max(0.0, min(100.0, _c / max(1, _tg_) * 100)); _cnt = f"{_c:,}/{_tg_:,}"
        else:
            _pct = 100.0; _cnt = f"{_c:,}"
        await _edu_edit(
            q,
            f"{label} · {_edu_diff(units)} · {units} واحد\n"
            f"{_edu_emoji(EDU_UNIT_EMOJI, '💠')} واحدها\n{_panel_bar('edu', '🟪', '⬜', _pct)}\n{_cnt}\n"
            f"<i>{random.choice(EDU_OPEN_LINES)}</i>\n\n<b>{html.escape(question)}</b>", kb, bold=False)
    elif act == "ans":
        try:
            key, qi, oi = p[3], int(p[4]), int(p[5])
            label, qs = EDU_SUBJECTS[key]
            label = _subj_label(key)
            question, options, right, units = qs[qi]
            options[oi]
        except Exception:
            await q.answer("این سوال دیگه معتبر نیست.", show_alert=True); return
        correct = (oi == right)
        gain = units if correct else EDU_WRONG_UNITS
        new_units = await pool.fetchval(
            "UPDATE users SET edu_pending='', edu_units=edu_units+$2 WHERE user_id=$1 AND edu_pending=$3 RETURNING edu_units",
            uid, gain, f"{key}:{qi}")
        if new_units is None:
            await q.answer("این سوال دیگه معتبر نیست.", show_alert=True); return
        await q.answer()
        left = max(0, EDU_COOLDOWN - (time.time() - float(row["edu_last"] or now)))
        _lead = f'<tg-emoji emoji-id="{EDU_RESULT_EID}">⭐</tg-emoji>'
        head = f"{_lead} <b>{random.choice(EDU_PRAISE if correct else EDU_WRONG_PRAISE)}</b>"
        _r2 = dict(row); _r2["edu_units"] = new_units
        _jn, _c, _tg_, _rem = _edu_progress(_r2, int(new_units))
        if _tg_:
            _pct = max(0.0, min(100.0, _c / max(1, _tg_) * 100)); _cnt = f"{_c:,} از {_tg_:,}"
        else:
            _pct = 100.0; _cnt = f"{_c:,}"
        result = (
            f"{head}\n\n"
            f"{_edu_emoji(EDU_UNIT_EMOJI, '💠')} <b>+{gain} واحد</b> · {_cnt}\n"
            f"{_panel_bar('edu', '🟪', '⬜', _pct)}\n\n"
            f"{_rem} · کلاس بعدی {_duration_fa(left)} دیگه"
        )
        _dg = int(row["edu_degree"] or 0)
        _l0, _l1 = edu_level(int(new_units) - gain, _dg), edu_level(int(new_units), _dg)
        if _l1 > _l0:
            await _give(uid, LEVEL_UP_PRIZE)
            result += f"\n\n🎉 <b>سطحت شد {_l1}!</b> {MONEY_CE} جایزه: {LEVEL_UP_PRIZE:,} تومن"
        await _edu_edit(q, result, bold=False)
    elif act == "deg":
        msg_alert = None
        res = None
        async with pool.acquire() as conn:
            async with conn.transaction():
                r = await conn.fetchrow("SELECT balance, edu_units, edu_degree FROM users WHERE user_id=$1 FOR UPDATE", uid)
                d = int(r["edu_degree"] or 0)
                if d >= len(EDU_DEGREES):
                    msg_alert = "بالاترین مدرک رو داری!"
                else:
                    nm, need, fee = EDU_DEGREES[d]
                    if int(r["edu_units"] or 0) < need:
                        msg_alert = f"واحدهات کافی نیست؛ {need - int(r['edu_units'] or 0):,} واحد دیگه لازم داری."
                    elif int(r["balance"] or 0) < fee:
                        msg_alert = f"شهریه {fee:,} تومنه؛ موجودیت کافی نیست."
                    else:
                        await conn.execute("UPDATE users SET balance=balance-$2, edu_degree=$3 WHERE user_id=$1", uid, fee, d + 1)
                        res = (nm, fee, edu_level(int(r["edu_units"] or 0), d), edu_level(int(r["edu_units"] or 0), d + 1))
        if msg_alert:
            await q.answer(msg_alert, show_alert=True); return
        await q.answer("مدرک گرفتی! 🎓", show_alert=True)
        row = await get_user(uid)
        await _edu_view(q, row, uid, f"{_tg(EID_TROPHY, '🎓')} <b>مدرک {html.escape(res[0])} گرفتی!</b> 🎉 شهریه‌ی پرداختی: {res[1]:,} تومان" + (f"\n🎉 سطحت شد {res[3]}!" if res[3] > res[2] else ""))
    else:
        await q.answer()


async def job_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    p = q.data.split(":")
    try:
        act, uid = p[1], int(p[2])
    except (IndexError, ValueError):
        await q.answer(); return
    if q.from_user.id != uid:
        await q.answer("این پنل مال شما نیست.", show_alert=True); return
    row = await get_user(uid)
    if not row or row["gender"] not in JOBS:
        await q.answer("اول جنسیتت رو انتخاب کن (بنویس «شغل»).", show_alert=True); return
    g = row["gender"]
    if act == "menu":
        await q.answer()
        await _jobs_view(q, row, uid)
    elif act == "sel":
        try:
            n = int(p[3])
        except (IndexError, ValueError):
            await q.answer(); return
        jl = _jlvl(row)
        if not 1 <= n <= jl:
            await q.answer("این شغل رو هنوز نگرفتی.", show_alert=True); return
        if n == _jsel(row):
            await q.answer("همین شغل فعاله ✅"); return
        await pool.execute("UPDATE users SET job_sel=$2 WHERE user_id=$1 AND job_level >= $2", uid, n)
        await q.answer(f"شغل فعالت شد: {JOBS[g][n - 1][0]} ✅")
        row = await get_user(uid)
        await _jobs_view(q, row, uid)
    elif act == "take":
        alert = None; res = None
        async with pool.acquire() as conn:
            async with conn.transaction():
                r = await conn.fetchrow("SELECT balance, job_level, edu_degree FROM users WHERE user_id=$1 FOR UPDATE", uid)
                jl = int(r["job_level"] or 0)
                if jl >= len(JOBS[g]):
                    alert = "همه‌ی شغل‌ها رو داری!"
                else:
                    need, fee, name = JOB_DEGREE_NEED[jl], JOB_FEES[jl], JOBS[g][jl][0]
                    if int(r["edu_degree"] or 0) < need:
                        alert = f"برای این شغل مدرک {_deg_name(need)} لازمه."
                    elif int(r["balance"] or 0) < fee:
                        alert = f"هزینه‌ی این شغل {fee:,} تومنه؛ موجودیت کافی نیست."
                    else:
                        if fee:
                            await conn.execute("UPDATE users SET balance=balance-$2 WHERE user_id=$1", uid, fee)
                        await conn.execute("UPDATE users SET job_level=$2, job_sel=$2 WHERE user_id=$1", uid, jl + 1)
                        res = (name, fee, JOB_PAY[jl][0])
        if alert:
            await q.answer(alert, show_alert=True); return
        await q.answer("شغل جدید گرفتی! 💼", show_alert=True)
        row = await get_user(uid)
        cost = f"هزینه: {res[1]:,} تومان" if res[1] else "رایگان بود"
        await _jobs_view(q, row, uid, f"{ce('me', 1, '🎖')} <b>شغل «{html.escape(res[0])}» رو گرفتی!</b> 🎉 {cost} · حقوق هر شیفت: {res[2]} (شغل فعالت شد؛ بنویس «کار»)")
    else:
        await q.answer()


LOCK_OPEN_ID = "6034962180875490251"


def _tge(eid, fb: str) -> str:
    return f'<tg-emoji emoji-id="{eid}">{fb}</tg-emoji>' if eid else fb


def job_glyph(gender: str, i: int, name: str) -> str:
    """ایموجی شغل: اول /setemoji job، بعد ایموجی‌هایی که از جدول فورواردشده یاد گرفتیم، آخرش ایموجی معمولی."""
    fb = JOB_GLYPHS.get(name, "💼")
    eid = EMOJI_IDS.get(("job", i + 1))
    if not eid:
        learned = (CUSTOM_JOBS.get(gender) or {}).get("job_emojis") or []
        if i < len(learned):
            eid = learned[i]
    return _tge(eid, fb)


def lock_closed() -> str:
    return _tge(EMOJI_IDS.get(("lock", 1)) or (CUSTOM_JOBS.get("m") or CUSTOM_JOBS.get("f") or {}).get("lock_closed"), "🔒")


def lock_open() -> str:
    return _tge(EMOJI_IDS.get(("lock", 2)) or LOCK_OPEN_ID, "🔓")


