    if car_row is not None and all(int(car_row[col] or 0) >= CAR_MAX_LEVEL for _l, _i, col in CAR_PARTS.values()):
        return btn("ماشین در آخرین سطح", "success", icon=MAX_LEVEL_EID, callback_data=f"car:upmenu:{uid}:{idx}:0")
