def _gift_glyph(g: dict) -> str:
    return _tge(g["eid"], g["fb"])


def _find_gift(rest: str):
    rest = rest.replace("‌", "")
    for i, g in enumerate(GIFTS):
        if any(a in rest for a in g["al"]):
            return i
    return None


def _mention(uid: int, name: str) -> str:
    return f'<a href="tg://user?id={uid}">{html.escape(name or "کاربر")}</a>'


def _ltr_name(uid: int, name: str) -> str:
    """اسم کاربر داخل ایزوله‌ی راست‌به‌چپ."""
    return f"\u2067{_mention(uid, name)}\u2069"


def _ltr_pair(a_id: int, a_name: str, b_id: int, b_name: str) -> str:
    """«فرستنده ⬅️ گیرنده» از راست به چپ (فرستنده سمت راست، گیرنده سمت چپ)."""
    return f"\u2067{_mention(a_id, a_name)} ⬅️ {_mention(b_id, b_name)}\u2069"


def gifts_rich_html() -> str:
    out = ["<table><tr><th>هدیه</th><th>قیمت (تومن)</th><th>انرژی</th></tr>"]
    for g in GIFTS:
        out.append(f"<tr><td>{_gift_glyph(g)} {html.escape(g['name'])}</td><td>{g['price']:,}</td><td>{_fmt_en(g['energy'])}</td></tr>")
    out.append("</table>")
    out.append("<p><br>" + GIFT_FOOTER.replace("\n", "<br>") + "</p>")  # راهنما تو همون پیام، یکم پایین‌تر از جدول
    return "".join(out)


def gifts_text() -> str:
    rows = [(f"{g['fb']} {g['name']}", f"{g['price']:,}", _fmt_en(g["energy"])) for g in GIFTS]
    table = mono_table(("هدیه", "قیمت", "انرژی"), rows)
    return f"{ce('me', 1, '🎁')} <b>هدیه‌ها</b>\n{table}\n\n{GIFT_FOOTER}"


async def show_gifts(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """«هدیه» / «هدیه ها» — جدول هدیه‌ها (مثل جدول شغل‌ها)؛ راهنمای تک‌فاصله با یکم فاصله زیر همون جدول، تو همون پیام."""
    msg = update.effective_message
    rp = ReplyParameters(message_id=msg.message_id, allow_sending_without_reply=True)
    try:
        await context.bot._post("sendRichMessage", {
            "chat_id": msg.chat_id,
            "rich_message": {"html": gifts_rich_html()},
            "reply_parameters": rp.to_dict(),
        })
        return
    except Exception:
        log.warning("gifts sendRichMessage failed, using <pre> table", exc_info=True)
    text = gifts_text()
    try:
        await msg.reply_text(text, parse_mode="HTML", reply_parameters=rp)
    except Exception:
        log.exception("gifts message failed, retrying without premium emojis")
        await msg.reply_text(re.sub(r"<tg-emoji[^>]*>(.*?)</tg-emoji>", r"\1", text), parse_mode="HTML")


async def gift_request(update: Update, context: ContextTypes.DEFAULT_TYPE, rest: str):
    msg, user = update.effective_message, update.effective_user
    target = msg.reply_to_message.from_user if msg.reply_to_message else None
    if target is None:
        await msg.reply_text("<b>برای فرستادن هدیه روی پیام اون کاربر ریپلای کن و بنویس:</b>\n<code>هدیه گل</code>", parse_mode="HTML")
        return
    if target.is_bot or target.id == user.id:
        await msg.reply_text(BP("نمی‌تونی به خودت یا ربات هدیه بدی 😅"), parse_mode="HTML")
        return
    if (rl := await rift_left(user.id, target.id)) > 0:
        await msg.reply_text(rift_block_html(rl), parse_mode="HTML")
        return
    idx = _find_gift(rest)
    if idx is None:
        await msg.reply_text("<b>این هدیه رو نمی‌شناسم. برای دیدن لیست بنویس:</b>\n<code>هدیه</code>", parse_mode="HTML")
        return
    g = GIFTS[idx]
    await upsert_user(user.id, user.full_name)
    row = await get_user(user.id)
    if int(row["balance"] or 0) < g["price"]:
        await msg.reply_text(B(f"{ce('wallet', 1, '💰')} دارایی‌ت کافی نیست! موجودی: {int(row['balance'] or 0):,} تومن"), parse_mode="HTML")
        return
    kb = InlineKeyboardMarkup([[
        btn("✅ تایید", "success", callback_data=f"gf:ok:{user.id}:{target.id}:{idx}"),
        btn("❌ لغو", "danger", callback_data=f"gf:no:{user.id}:{target.id}:{idx}"),
    ]])
    context.application.bot_data.setdefault("gf_names", {})[(msg.chat_id, target.id)] = target.full_name
    await msg.reply_text(
        f"<b>{_ltr_pair(user.id, user.full_name, target.id, target.full_name)}\n\n"
        f"مطمئنی می‌خوای {_gift_glyph(g)} {html.escape(g['name'])} (<u>{g['price']:,} تومن</u>) بفرستی؟\n\n"
        f"{ce('energy', 1, '⚡')} {_fmt_en(g['energy'])} انرژی برای گیرنده</b>",
        parse_mode="HTML", reply_markup=kb,
        reply_parameters=ReplyParameters(message_id=msg.message_id, allow_sending_without_reply=True),
    )


async def gift_answer(update: Update, context: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    _, act, frm, to, idx = q.data.split(":")
    frm, to, idx = int(frm), int(to), int(idx)
    if q.from_user.id != frm:
        await q.answer("این تایید مال تو نیست 😅", show_alert=True)
        return
    if not 0 <= idx < len(GIFTS):
        await q.answer("هدیه نامعتبره.", show_alert=True)
        return
    key = (q.message.chat_id, q.message.message_id)
    done = context.bot_data.setdefault("gf_done", set())
    if key in done:
        await q.answer("قبلاً انجام شده.", show_alert=True)
        return
    done.add(key)
    if act == "no":
        await q.answer("لغو شد")
        await q.edit_message_text("❌ هدیه لغو شد.")
        return
    try:
        age = time.time() - q.message.date.timestamp()
    except Exception:
        age = 0
    if age > 300:
        await q.answer("زمان تایید تموم شده، دوباره درخواست بده.", show_alert=True)
        await q.edit_message_text("⌛ زمان تایید تموم شد.")
        return
    g = GIFTS[idx]
    if await rift_left(frm, to) > 0:
        await q.answer("با هم قهرید!", show_alert=True)
        await q.edit_message_text("💔 باهم قهرید؛ هدیه فرستاده نشد.")
        return
    try:
        async with pool.acquire() as c:
            async with c.transaction():
                ok = await c.fetchval(
                    "UPDATE users SET balance = balance - $1::bigint WHERE user_id = $2::bigint AND balance >= $1::bigint RETURNING 1",
                    g["price"], frm,
                )
                if not ok:
                    raise ValueError("insufficient")
                await c.execute("INSERT INTO users (user_id, name) VALUES ($1, '') ON CONFLICT (user_id) DO NOTHING", to)
                new_en = await c.fetchval(
                    "UPDATE users SET energy = LEAST(energy + $1::double precision, $3::double precision) WHERE user_id = $2::bigint RETURNING energy",
                    float(g["energy"]), to, ENERGY_MAX,
                )
    except ValueError:
        await q.answer("دارایی‌ت کافی نیست!", show_alert=True)
        await q.edit_message_text("❌ دارایی کافی نبود؛ هدیه فرستاده نشد.")
        return
    except Exception:
        done.discard(key)
        log.exception("gift failed")
        await q.answer("خطا، دوباره امتحان کن.", show_alert=True)
        return
    await q.answer("هدیه فرستاده شد 🎁")
    tname = (context.application.bot_data.get("gf_names", {}).get((q.message.chat_id, to))
             or await pool.fetchval("SELECT name FROM users WHERE user_id = $1", to) or "کاربر")
    await q.edit_message_text(
        f"<b>{_ltr_pair(frm, q.from_user.full_name, to, tname)}\n\n"
        f"{_gift_glyph(g)} {html.escape(g['name'])} فرستاد!\n\n"
        f"«{html.escape(g['line'])}»\n\n"
        f"{ce('energy', 1, '⚡')} +{_fmt_en(g['energy'])} انرژی برای گیرنده\n"
        f"{energy_bar(new_en)} {_fmt_en(float(new_en) / ENERGY_MAX * 100)}٪</b>",
        parse_mode="HTML",
    )
    await task_event(context.bot, q.message.chat_id, frm, "gift", name=q.from_user.full_name)


# ───────────────────────── فرزندخواندگی و شجره‌نامه ─────────────────────────
# زوج‌های متأهل: ریپلای روی کاربر + «جینگو فرزندخواندگی» (یا «فرزندخواندگی»). اگه اون کاربر قبول کنه، فرزندخونده‌ی هر دو نفر میشه.
# تو «خانواده» والدین/فرزندها نشون داده میشه و دکمه‌ی «شجره‌نامه» (یا نوشتن «شجره نامه») عکس درخت خانواده رو می‌فرسته.
ADOPT_WORDS = {"جینگوفرزندخواندگی", "جینگوفرزندخوندگی", "فرزندخواندگی", "فرزندخوندگی",
               "جینگوفرزندخونده", "جینگوفرزندخوانده", "جینگوفرزندخوندهگرفتن", "جینگوفرزندخواندهگرفتن"}
TREE_WORDS = {"شجرهنامه", "شجرهنامهخانواده", "درختخانواده", "جینگوشجرهنامه"}
ADOPT_REQ_TTL = 3600
TREE_MAX_DEPTH = 6


async def _adopt_is_ancestor(anc: int, uid: int) -> bool:
    """آیا anc جزو اجداد (والدین، والدینِ والدین، ...) uid هست؟ (جلوی حلقه‌ی خانوادگی رو می‌گیره)"""
    seen = {uid}
    frontier = [uid]
    for _ in range(12):
        if not frontier:
            return False
        rows = await pool.fetch("SELECT parent1_id, parent2_id FROM adoptions WHERE child_id = ANY($1::bigint[])", frontier)
        nxt = []
        for r in rows:
            for p in (int(r["parent1_id"]), int(r["parent2_id"])):
                if p == anc:
                    return True
                if p not in seen:
                    seen.add(p); nxt.append(p)
        frontier = nxt
    return False


async def adopt_request(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    msg, user = update.effective_message, update.effective_user
    target = msg.reply_to_message.from_user if msg.reply_to_message else None
    if not target or target.is_bot or target.id == user.id:
        await msg.reply_text("برای فرزندخواندگی، روی پیام کاربر موردنظرت ریپلای کن و «جینگو فرزندخواندگی» بنویس."); return True
    await upsert_user(user.id, user.full_name)
    await pool.execute("INSERT INTO users(user_id,name) VALUES($1,$2) ON CONFLICT(user_id) DO NOTHING", target.id, target.full_name)
    me = await get_user(user.id); other = await get_user(target.id)
    if not me or not me["spouse_id"]:
        await msg.reply_text("👶 فقط زوج‌های متأهل می‌تونن فرزندخونده بگیرن؛ اول باید ازدواج کنی."); return True
    spouse_id = int(me["spouse_id"])
    if target.id == spouse_id:
        await msg.reply_text("همسرت رو که نمی‌تونی فرزندخونده کنی 😅"); return True
    if await pool.fetchval("SELECT 1 FROM adoptions WHERE child_id=$1", target.id):
        await msg.reply_text("این کاربر قبلاً فرزندخونده‌ی یه خانواده شده."); return True
    if await _adopt_is_ancestor(target.id, user.id) or await _adopt_is_ancestor(target.id, spouse_id):
        await msg.reply_text("این کاربر جزو اجداد خانواده‌ی شماست؛ نمی‌تونه فرزندخونده‌تون بشه."); return True
    sp = await get_user(spouse_id)
    sp_name = (sp["name"] if sp else None) or "همسر"
    await pool.execute("INSERT INTO adoption_requests(child_id,parent_id,spouse_id,chat_id,created_at) VALUES($1,$2,$3,$4,$5) "
                       "ON CONFLICT(child_id) DO UPDATE SET parent_id=EXCLUDED.parent_id,spouse_id=EXCLUDED.spouse_id,chat_id=EXCLUDED.chat_id,created_at=EXCLUDED.created_at",
                       target.id, user.id, spouse_id, msg.chat_id, time.time())
    kb = InlineKeyboardMarkup([[btn("👶 قبول می‌کنم", "success", callback_data=f"adp:yes:{target.id}:{user.id}"),
                                btn("رد می‌کنم", "danger", callback_data=f"adp:no:{target.id}:{user.id}")]])
    await send_html(context.bot, msg.chat_id,
                    B(f"👶 {_ulink(target.id, target.full_name)}، {_ulink(user.id, user.full_name)} و همسرش {_ulink(spouse_id, sp_name)} می‌خوان تو رو به فرزندخونده‌گی بگیرن!\nقبول می‌کنی؟"),
                    reply_markup=kb, reply_parameters=ReplyParameters(message_id=msg.message_id, allow_sending_without_reply=True))
    return True


async def adopt_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    try:
        _, act, child_s, parent_s = q.data.split(":"); child = int(child_s); parent = int(parent_s)
    except (ValueError, IndexError):
        await q.answer("درخواست نامعتبره.", show_alert=True); return
    if q.from_user.id != child:
        await q.answer("فقط خودِ فرد موردنظر می‌تونه جواب بده.", show_alert=True); return
    req = await pool.fetchrow("SELECT parent_id, spouse_id, created_at FROM adoption_requests WHERE child_id=$1", child)
    if not req or int(req["parent_id"]) != parent or time.time() - float(req["created_at"]) > ADOPT_REQ_TTL:
        await pool.execute("DELETE FROM adoption_requests WHERE child_id=$1", child)
        await q.answer("درخواست منقضی شده.", show_alert=True); return
    if act == "no":
        await pool.execute("DELETE FROM adoption_requests WHERE child_id=$1", child)
        await q.answer("رد شد."); await edit_html(q, B("💔 درخواست فرزندخواندگی رد شد.")); return
    err = None
    async with pool.acquire() as c:
        async with c.transaction():
            rows = await c.fetch("SELECT user_id, spouse_id, name FROM users WHERE user_id=ANY($1::bigint[]) ORDER BY user_id FOR UPDATE", [child, parent])
            by = {int(r["user_id"]): r for r in rows}
            ch, pa = by.get(child), by.get(parent)
            if not ch or not pa or not pa["spouse_id"]:
                err = "والد دیگه متأهل نیست."
            elif await c.fetchval("SELECT 1 FROM adoptions WHERE child_id=$1", child):
                err = "این کاربر قبلاً فرزندخونده شده."
            else:
                sp_id = int(pa["spouse_id"])
                await c.execute("INSERT INTO adoptions(child_id,parent1_id,parent2_id,created_at) VALUES($1,$2,$3,$4)", child, parent, sp_id, time.time())
                await c.execute("DELETE FROM adoption_requests WHERE child_id=$1", child)
    if err:
        await pool.execute("DELETE FROM adoption_requests WHERE child_id=$1", child)
        await q.answer(err, show_alert=True); await edit_html(q, B(f"❌ {html.escape(err)}")); return
    sp = await get_user(sp_id)
    await q.answer("مبارکه! 👶")
    await edit_html(q, B(f"👶 {_ulink(child, q.from_user.full_name)} فرزندخونده‌ی {_ulink(parent, pa['name'] or 'کاربر')} و {_ulink(sp_id, (sp['name'] if sp else None) or 'همسر')} شد!\n"
                         f"با نوشتن «خانواده» و دکمه‌ی «شجره‌نامه» درخت خانواده‌تون رو ببینید 🌳"))


# ───── پنل همسرم ─────
async def spouse_panel(update: Update, context: ContextTypes.DEFAULT_TYPE):
    msg, user = update.effective_message, update.effective_user
    row = await get_user(user.id)
    if not row or not row["spouse_id"]:
        await msg.reply_text("هنوز ازدواج نکردی."); return
    spouse = await get_user(int(row["spouse_id"]))
    if not spouse:
        await msg.reply_text("اطلاعات همسرت پیدا نشد."); return
    rel, _ = await couple_info(user.id, int(spouse["user_id"]))
    text = (f"💍 <b>همسر تو</b>\nهمسر: {_ulink(spouse['user_id'], spouse['name'] or 'همسر')}\n"
            f"{energy_line(spouse['energy'])}\n💞 میزان رابطه: <b>{rel}</b>")
    kb_rows = []
    if update.effective_chat.type != "private":
        kb_rows.append([btn("سکس", "danger", icon=SEX_EIDS[0], callback_data=f"sx:ask:{user.id}"),
                        btn("فروشگاه", "primary", icon=SHOP_EID, callback_data=f"shp:no:{user.id}:condom")])
    kb_rows.append([btn("💔 طلاق", "danger", callback_data=f"fam:div:{user.id}:q"),
                    btn("🌳 شجره‌نامه", "primary", callback_data=f"fam:tree:{user.id}")])
    await send_html(context.bot, msg.chat_id, B(text), reply_markup=InlineKeyboardMarkup(kb_rows),
                    reply_parameters=ReplyParameters(message_id=msg.message_id, allow_sending_without_reply=True))


async def family_divorce_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    try:
        _, _, uid_s, act = q.data.split(":"); uid = int(uid_s)
    except (ValueError, IndexError):
        await q.answer(); return
    if q.from_user.id != uid:
        await q.answer("این دکمه مال تو نیست.", show_alert=True); return
    if act == "q":
        row = await get_user(uid)
        if not row or not row["spouse_id"]:
            await q.answer("تو الان متأهل نیستی.", show_alert=True); return
        await q.answer()
        kb = InlineKeyboardMarkup([[btn("✅ آره، طلاق می‌گیرم", "danger", callback_data=f"fam:div:{uid}:y"),
                                    btn("انصراف", "primary", callback_data=f"fam:div:{uid}:n")]])
        await edit_html(q, B("💔 مطمئنی می‌خوای طلاق بگیری؟\nرابطه‌ی شما پاک می‌شه (هیچ پولی جابه‌جا نمی‌شه)."), kb); return
    if act == "n":
        await q.answer("انصراف داده شد."); await edit_html(q, B("باشه، طلاق نگرفتی ❤️")); return
    sp_id = None
    async with pool.acquire() as c:
        async with c.transaction():
            me = await c.fetchrow("SELECT spouse_id FROM users WHERE user_id=$1 FOR UPDATE", uid)
            if me and me["spouse_id"]:
                sp_id = int(me["spouse_id"])
                await c.execute("UPDATE users SET spouse_id=NULL WHERE user_id IN ($1,$2)", uid, sp_id)
                await c.execute("DELETE FROM couple_relation WHERE pair_key=$1", _pair_key(uid, sp_id))
    if sp_id is None:
        await q.answer("تو الان متأهل نیستی.", show_alert=True)
        await edit_html(q, B("تو الان متأهل نیستی.")); return
    sp = await get_user(sp_id)
    await q.answer("طلاق ثبت شد.")
    await edit_html(q, B(f"💔 {_ulink(uid, q.from_user.full_name)} و {_ulink(sp_id, (sp['name'] if sp else None) or 'همسرش')} از هم جدا شدن. طلاق ثبت شد."))


# ───── پنل خانواده ─────
async def family_panel(update: Update, context: ContextTypes.DEFAULT_TYPE):
    msg, user = update.effective_message, update.effective_user
    row = await get_user(user.id)
    parents = await pool.fetchrow("SELECT parent1_id, parent2_id FROM adoptions WHERE child_id=$1", user.id)
    kids = await pool.fetch("SELECT a.child_id, u.name FROM adoptions a LEFT JOIN users u ON u.user_id=a.child_id "
                            "WHERE a.parent1_id=$1 OR a.parent2_id=$1 ORDER BY a.created_at", user.id)
    spouse = await get_user(int(row["spouse_id"])) if row and row["spouse_id"] else None
    if not spouse and not parents and not kids:
        await msg.reply_text("هنوز خانواده‌ای نداری؛ اول ازدواج کن یا فرزندخونده بگیر."); return
    parts = ["👨‍👩‍👧 <b>خانواده‌ی تو</b>"]
    if spouse:
        parts.append(f"💍 <b>همسر:</b> {_ulink(spouse['user_id'], spouse['name'] or 'همسر')}")
    if parents:
        names = []
        for pid in (int(parents["parent1_id"]), int(parents["parent2_id"])):
            pr = await get_user(pid)
            names.append(_ulink(pid, (pr["name"] if pr else None) or "کاربر"))
        parts.append(f"👶 <b>فرزندخونده</b>\nوالدین: {names[0]} و {names[1]}")
    if kids:
        lst = "، ".join(_ulink(int(k["child_id"]), k["name"] or "کاربر") for k in kids)
        parts.append(f"🍼 <b>فرزندخونده‌ها ({len(kids)}):</b> {lst}")
    row_btns = [btn("🌳 شجره‌نامه", "primary", callback_data=f"fam:tree:{user.id}")]
    if parents:
        row_btns.append(btn("🚪 ترک خانواده", "danger", callback_data=f"fam:leave:{user.id}:q"))
    await send_html(context.bot, msg.chat_id, B("\n\n".join(parts)), reply_markup=InlineKeyboardMarkup([row_btns]),
                    reply_parameters=ReplyParameters(message_id=msg.message_id, allow_sending_without_reply=True))


# ───── شجره‌نامه (عکس) ─────
async def _tree_build(pid: int, visited: set, depth: int) -> dict:
    visited.add(pid)
    row = await get_user(pid)
    partner = int(row["spouse_id"]) if row and row["spouse_id"] else None
    kids = await pool.fetch("SELECT child_id, parent1_id, parent2_id, created_at FROM adoptions WHERE parent1_id=$1 OR parent2_id=$1 ORDER BY created_at", pid)
    if partner is None and kids:   # طلاق گرفته‌ن ولی فرزندها هنوز به هر دو وصلن
        k0 = kids[0]
        partner = int(k0["parent2_id"]) if int(k0["parent1_id"]) == pid else int(k0["parent1_id"])
    people = [pid]
    child_rows = list(kids)
    if partner and partner not in visited:
        people.append(partner); visited.add(partner)
        child_rows += list(await pool.fetch("SELECT child_id, parent1_id, parent2_id, created_at FROM adoptions WHERE parent1_id=$1 OR parent2_id=$1 ORDER BY created_at", partner))
    child_ids, seen_c = [], set()
    for r in sorted(child_rows, key=lambda r: float(r["created_at"])):
        c = int(r["child_id"])
        if c not in seen_c:
            seen_c.add(c); child_ids.append(c)
    children = []
    if depth < TREE_MAX_DEPTH:
        for c in child_ids:
            if c not in visited:
                children.append(await _tree_build(c, visited, depth + 1))
    return {"people": people, "children": children}


async def tree_data(uid: int):
    """(درخت، اطلاعات کاربرها) — از بالاترین جد شروع میشه و تا همه‌ی نوه‌ها پایین میاد."""
    cur = uid
    for _ in range(TREE_MAX_DEPTH):
        par = await pool.fetchrow("SELECT parent1_id, parent2_id FROM adoptions WHERE child_id=$1", cur)
        if not par:
            break
        p1, p2 = int(par["parent1_id"]), int(par["parent2_id"])
        if not await pool.fetchval("SELECT 1 FROM adoptions WHERE child_id=$1", p1) and await pool.fetchval("SELECT 1 FROM adoptions WHERE child_id=$1", p2):
            cur = p2
        else:
            cur = p1
    tree = await _tree_build(cur, set(), 0)
    ids = []
    def walk(n):
        ids.extend(n["people"])
        for c in n["children"]:
            walk(c)
    walk(tree)
    rows = await pool.fetch("SELECT user_id, name, gender FROM users WHERE user_id=ANY($1::bigint[])", ids)
    info = {int(r["user_id"]): (r["name"], r["gender"]) for r in rows}
    return tree, info


