BUY_CARD = "6219861851160068"
BUY_CARD_OWNER = "ظریفی"
# (پول بازی، قیمت به تومن، عنوان)
BUY_PACKAGES = [
    (100_000_000, 100_000, "۱۰۰m"),
    (350_000_000, 347_000, "۳۵۰m"),
    (500_000_000, 489_000, "۵۰۰m"),
    (1_000_000_000, 860_000, "۱ میلیارد"),
]
