# نوار جون غول از ست‌های نوار پروفیت ساخته میشه؛ ست قرمز خواستی این خط رو عوض کن
BAR_SETS["boss"] = BAR_SETS["jm"]
BAR_CAP_KEY["boss"] = "boss"
BOSS_BAR_CELLS = 8
BOSS_SKULL_CE = '<tg-emoji emoji-id="5987616823636401062">🔥</tg-emoji>'
_BOSS_FILE_ID: dict[str, str] = {}
_BOSS_LAST_HIT: dict[tuple, float] = {}
_BOSS_WARNED: dict[tuple, float] = {}
_BOSS_REPLY_TS: dict[int, list] = {}
_BOSS_DIRTY: set[int] = set()
BOSS_MIN_MEMBERS = 21          # غول فقط تو گروه‌هایی میاد که حداقل این‌قدر عضو دارن (۲۱ هم شاملش میشه)
BOSS_MEMBERS_TTL = 600         # تعداد اعضا هر ۱۰ دقیقه یه بار از تلگرام پرسیده میشه
_BOSS_MEMBERS: dict[int, tuple] = {}   # chat_id -> (زمان چک, تعداد اعضا)


async def _boss_member_count(bot, chat_id: int) -> int:
    """تعداد اعضای گروه (کش‌شده). اگه تلگرام جواب نده و قبلاً هم چیزی ثبت نشده باشه 0 برمی‌گردونه تا غول نیاد."""
    now = time.time()
    hit = _BOSS_MEMBERS.get(chat_id)
    if hit and now - hit[0] < BOSS_MEMBERS_TTL:
        return hit[1]
    try:
        n = int(await bot.get_chat_member_count(chat_id))
    except Exception as e:
        log.warning("boss member count failed in %s: %s", chat_id, e)
        return hit[1] if hit else 0
    _BOSS_MEMBERS[chat_id] = (now, n)
    return n


async def boss_group_allowed(bot, chat_id: int) -> bool:
    return await _boss_member_count(bot, chat_id) >= BOSS_MIN_MEMBERS


def _boss_path(fname: str):
    here = Path(__file__).resolve().parent
    for p in (here / fname, here / "boss_media" / fname, here / "assets" / fname):
        if p.exists():
            return p
    return None


_BOSS_IMG_EXT = (".jpg", ".jpeg", ".png", ".webp")


async def _boss_media(bot, chat_id: int, fname: str, caption: str):
    """مدیای غول (ویدیوی انیمیشنی یا عکس) رو می‌فرسته؛ بار اول از فایل، بعدش با file_id (سریع). فایل نبود فقط متن میره."""
    is_img = fname.lower().endswith(_BOSS_IMG_EXT)
    if fname in _BOSS_FILE_ID:
        try:
            if is_img:
                return await bot.send_photo(chat_id, _BOSS_FILE_ID[fname], caption=caption, parse_mode="HTML")
            return await bot.send_animation(chat_id, _BOSS_FILE_ID[fname], caption=caption, parse_mode="HTML")
        except Exception:
            _BOSS_FILE_ID.pop(fname, None)
    p = _boss_path(fname)
    if not p:
        log.warning("boss media missing: %s", fname)
        return await bot.send_message(chat_id, caption, parse_mode="HTML")
    bio = BytesIO(p.read_bytes()); bio.name = fname
    if is_img:
        m = await bot.send_photo(chat_id, bio, caption=caption, parse_mode="HTML")
        try:
            _BOSS_FILE_ID[fname] = m.photo[-1].file_id
        except Exception:
            pass
        return m
    m = await bot.send_animation(chat_id, bio, caption=caption, parse_mode="HTML", width=480, height=720)
    try:
        _BOSS_FILE_ID[fname] = m.animation.file_id
    except Exception:
        pass
    return m


async def boss_init_db():
    await pool.execute("CREATE TABLE IF NOT EXISTS boss_fights (chat_id BIGINT PRIMARY KEY, idx INT NOT NULL, hp BIGINT NOT NULL, hp_max BIGINT NOT NULL, pool BIGINT NOT NULL, msg_id BIGINT NOT NULL DEFAULT 0, started DOUBLE PRECISION NOT NULL, ends_at DOUBLE PRECISION NOT NULL, status TEXT NOT NULL DEFAULT 'active', last_hitter BIGINT NOT NULL DEFAULT 0)")
    await pool.execute("CREATE TABLE IF NOT EXISTS boss_hits (chat_id BIGINT NOT NULL, user_id BIGINT NOT NULL, name TEXT, damage BIGINT NOT NULL DEFAULT 0, hits INT NOT NULL DEFAULT 0, PRIMARY KEY(chat_id, user_id))")
    await pool.execute("CREATE TABLE IF NOT EXISTS boss_sched (chat_id BIGINT PRIMARY KEY, next_spawn DOUBLE PRECISION NOT NULL)")


def _boss_bar(hp: int, hp_max: int) -> str:
    return _custom_bar("boss", 100.0 * hp / max(1, hp_max), BOSS_BAR_CELLS)


async def _boss_caption(chat_id: int, f, state: str = "active", extra: str = "") -> str:
    b = BOSSES[f["idx"]]
    hp, hp_max = int(f["hp"]), int(f["hp_max"])
    top = await pool.fetch("SELECT name, damage FROM boss_hits WHERE chat_id=$1 ORDER BY damage DESC LIMIT 3", chat_id)
    medals = ("🥇", "🥈", "🥉")
    tops = "\n".join(f"{medals[i]} {html.escape(r['name'] or 'ناشناس')} — {int(r['damage']):,}" for i, r in enumerate(top)) or "هنوز کسی شلیک نکرده!"
    pct = 100.0 * hp / max(1, hp_max)
    if state == "active":
        left = max(0, int(f["ends_at"] - time.time()))
        head = f"{BOSS_SKULL_CE} غول «{b['name']}» ظاهر شد! {BOSS_SKULL_CE}"
        foot = (f"{SWORDS_CE} روی همین پیام ریپلای کن و بنویس: «شلیک»\n"
                f"هر نفر هر {BOSS_HIT_CD} ثانیه یه شلیک ({BOSS_ENERGY_COST:g} انرژی)")
        timer = f"{HG_CE} مهلت: {_duration_fa(left)}\n"
    elif state == "dead":
        head = f"☠️ غول «{b['name']}» نابود شد! 🎉"
        foot, timer = "پاداش‌ها به حساب شرکت‌کننده‌ها واریز شد.", ""
    else:
        head = f"💨 غول «{b['name']}» فرار کرد!"
        foot, timer = "این بار نتونستین نابودش کنین؛ دفعه‌ی بعد جدی‌تر!", ""
    return B(f"{head}\n\n{_boss_bar(hp, hp_max)}\n❤️ جون: {pct:.0f}٪ — {hp:,} از {hp_max:,}\n{timer}"
             f"{MONEY_CE} جایزه‌ی کل: {int(f['pool']):,} تومان\n\n{TROPHY_CE} برترین‌ها:\n{tops}\n\n{foot}{extra}")


async def boss_spawn(bot, chat_id: int, force: bool = False) -> bool:
    now = time.time()
    if not await boss_group_allowed(bot, chat_id):   # گروه زیر ۲۱ عضو: اصلاً غول نمیاد
        return False
    cur = await pool.fetchrow("SELECT status, ends_at FROM boss_fights WHERE chat_id=$1", chat_id)
    if cur and cur["status"] == "active" and cur["ends_at"] > now:
        return False
    idx = random.randrange(len(BOSSES))
    b = BOSSES[idx]
    await pool.execute("DELETE FROM boss_hits WHERE chat_id=$1", chat_id)
    await pool.execute(
        "INSERT INTO boss_fights (chat_id, idx, hp, hp_max, pool, msg_id, started, ends_at, status, last_hitter) VALUES ($1,$2,$3,$3,$4,0,$5,$6,'active',0) "
        "ON CONFLICT (chat_id) DO UPDATE SET idx=EXCLUDED.idx, hp=EXCLUDED.hp, hp_max=EXCLUDED.hp_max, pool=EXCLUDED.pool, msg_id=0, started=EXCLUDED.started, ends_at=EXCLUDED.ends_at, status='active', last_hitter=0",
        chat_id, idx, b["hp"], b["pool"], now, now + BOSS_DURATION)
    f = await pool.fetchrow("SELECT * FROM boss_fights WHERE chat_id=$1", chat_id)
    try:
        m = await _boss_media(bot, chat_id, b["file"], await _boss_caption(chat_id, f))
    except Exception:
        log.warning("boss spawn failed in %s", chat_id, exc_info=True)
        await pool.execute("UPDATE boss_fights SET status='cancelled' WHERE chat_id=$1", chat_id)
        return False
    await pool.execute("UPDATE boss_fights SET msg_id=$2 WHERE chat_id=$1", chat_id, m.message_id)
    await pool.execute("INSERT INTO boss_sched (chat_id, next_spawn) VALUES ($1,$2) ON CONFLICT (chat_id) DO UPDATE SET next_spawn=EXCLUDED.next_spawn", chat_id, now + BOSS_EVERY)
    return True


async def _boss_edit(bot, chat_id: int, state: str = "active", extra: str = ""):
    f = await pool.fetchrow("SELECT * FROM boss_fights WHERE chat_id=$1", chat_id)
    if not f or not f["msg_id"]:
        return
    try:
        cap = await _boss_caption(chat_id, f, state, extra)
        try:
            await bot.edit_message_caption(chat_id=chat_id, message_id=f["msg_id"], caption=cap, parse_mode="HTML")
        except BadRequest as e0:
            if "no caption" in str(e0).lower() or "there is no text" in str(e0).lower():
                await bot.edit_message_text(cap, chat_id=chat_id, message_id=f["msg_id"], parse_mode="HTML")
            else:
                raise
    except BadRequest as e:
        if "not modified" not in str(e).lower():
            log.warning("boss caption edit failed: %s", e)
    except RetryAfter:
        pass
    except Exception:
        log.warning("boss caption edit failed", exc_info=True)


async def _boss_finish_kill(bot, chat_id: int, last_uid: int):
    f = await pool.fetchrow("SELECT * FROM boss_fights WHERE chat_id=$1", chat_id)
    hits = await pool.fetch("SELECT user_id, name, damage FROM boss_hits WHERE chat_id=$1 ORDER BY damage DESC", chat_id)
    total = sum(int(h["damage"]) for h in hits) or 1
    P = int(f["pool"])
    pay = {int(h["user_id"]): P * int(h["damage"]) // total for h in hits}
    for uid, frac in zip([int(h["user_id"]) for h in hits[:3]], (0.20, 0.10, 0.05)):
        pay[uid] += int(P * frac)
    pay[last_uid] = pay.get(last_uid, 0) + int(P * 0.05)
    async with pool.acquire() as c:
        async with c.transaction():
            await c.execute("UPDATE boss_fights SET status='dead' WHERE chat_id=$1", chat_id)
            for uid, amt in pay.items():
                await c.execute("UPDATE users SET balance = balance + $1::bigint WHERE user_id = $2::bigint", amt, uid)
    names = {int(h["user_id"]): (h["name"] or "ناشناس") for h in hits}
    medals = ("🥇", "🥈", "🥉")
    lines = [f"{medals[i]} {html.escape(names[int(h['user_id'])])} — {int(h['damage']):,} آسیب | {MONEY_CE} {pay[int(h['user_id'])]:,} تومان" for i, h in enumerate(hits[:3])]
    last_name = html.escape(names.get(last_uid, "ناشناس"))
    text = B(f"☠️ {BOSSES[f['idx']]['name']} نابود شد! {TROPHY_CE}\n\n" + "\n".join(lines) +
             f"\n\n🎯 ضربه‌ی آخر: {last_name} (پاداش ویژه)\n👥 شرکت‌کننده‌ها: {len(hits)} نفر\n{MONEY_CE} همه‌ی پاداش‌ها واریز شد!")
    await _boss_edit(bot, chat_id, "dead")
    try:
        await bot.send_message(chat_id, text, parse_mode="HTML", reply_to_message_id=f["msg_id"] or None)
    except Exception:
        try:
            await bot.send_message(chat_id, text, parse_mode="HTML")
        except Exception:
            log.warning("boss kill msg failed", exc_info=True)


async def boss_hit(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    msg, user = update.effective_message, update.effective_user
    rep = msg.reply_to_message
    if not rep:
        return False
    chat_id = msg.chat_id
    f = await pool.fetchrow("SELECT * FROM boss_fights WHERE chat_id=$1", chat_id)
    if not f or f["status"] != "active" or rep.message_id != f["msg_id"]:
        return False
    now = time.time()
    if f["ends_at"] <= now or f["hp"] <= 0:
        return True
    row = await get_user(user.id)
    if not row or not row["started"]:
        await msg.reply_text(BP("اول ربات رو تو پی‌وی استارت کن بعد بیا شلیک کن!"), parse_mode="HTML")
        return True
    key = (chat_id, user.id)
    wait = BOSS_HIT_CD - (now - _BOSS_LAST_HIT.get(key, 0))
    if wait > 0:
        if now - _BOSS_WARNED.get(key, 0) > BOSS_HIT_CD:
            _BOSS_WARNED[key] = now
            await msg.reply_text(B(f"{HG_CE} تفنگت داغه! {int(wait) + 1} ثانیه صبر کن."), parse_mode="HTML")
        return True
    en = await pool.fetchval("UPDATE users SET energy = energy - $1::double precision WHERE user_id = $2::bigint AND energy >= $1::double precision RETURNING energy", BOSS_ENERGY_COST, user.id)
    if en is None:
        await msg.reply_text(B(f"{ce('energy', 1, '⚡')} انرژیت تموم شده! با بغل، بوس یا هدیه انرژی بگیر."), parse_mode="HTML")
        return True
    _BOSS_LAST_HIT[key] = now
    dmg = random.randint(120, 220) + int(row.get("hand_level", 0) or 0) * 4
    crit = random.random() < 0.12
    if crit:
        dmg *= 2
    new_hp = await pool.fetchval("UPDATE boss_fights SET hp = GREATEST(hp - $2::bigint, 0), last_hitter = $3::bigint WHERE chat_id=$1 AND status='active' AND hp > 0 RETURNING hp", chat_id, dmg, user.id)
    if new_hp is None:
        await pool.execute("UPDATE users SET energy = LEAST(energy + $1::double precision, $2::double precision) WHERE user_id = $3::bigint", BOSS_ENERGY_COST, ENERGY_MAX, user.id)
        return True
    await pool.execute("INSERT INTO boss_hits (chat_id, user_id, name, damage, hits) VALUES ($1,$2,$3,$4,1) ON CONFLICT (chat_id, user_id) DO UPDATE SET damage = boss_hits.damage + $4, hits = boss_hits.hits + 1, name = $3",
                       chat_id, user.id, user.full_name, dmg)
    if new_hp <= 0:
        await _boss_finish_kill(context.bot, chat_id, user.id)
        return True
    _BOSS_DIRTY.add(chat_id)
    recent = [t for t in _BOSS_REPLY_TS.get(chat_id, []) if now - t < 60]
    if len(recent) < 18:   # سقف پیام تو دقیقه تا تلگرام گروه رو محدود نکنه
        recent.append(now)
        _BOSS_REPLY_TS[chat_id] = recent
        boss_name = html.escape(BOSSES[f["idx"]]["name"])
        crit_txt = " (ضربه‌ی بحرانی!)" if crit else ""
        try:
            await msg.reply_text(
                B(f"{html.escape(user.full_name)} به {boss_name} شلیک کرد "
                  f'<tg-emoji emoji-id="5307744619033795130">💥</tg-emoji> {dmg:,} آسیب زد{crit_txt}\n'
                  f'<tg-emoji emoji-id="5255751656208875797">❤️</tg-emoji> جان باقی مانده باس: {int(new_hp):,}'),
                parse_mode="HTML")
        except Exception:
            pass
    return True


# ───────── تجهیزات (قدرت‌ها ← تجهیزات): نارنجک و بمب اتم برای باس‌ها ─────────
# ریپلای روی پیام باس + «جینگو نارنجک» / «جینگو بمب اتم». نارنجک: خرید روزانه تا ۵ تا. بمب اتم: استفاده‌ی روزانه تا ۲ بار؛ هر بار ۲۵ انرژی
# از اعضای همون گروه که تو یک ساعت اخیر کار (شیفت) کردن کم میشه.
GRENADE_EID = "4956691726178715098"
ATOM_EID = "4956215710658331316"
GRENADE_CE = f'<tg-emoji emoji-id="{GRENADE_EID}">💣</tg-emoji>'
ATOM_CE = f'<tg-emoji emoji-id="{ATOM_EID}">☢️</tg-emoji>'
GRENADE_PRICE = 1_000_000
GRENADE_DAILY_BUY = 5
GRENADE_DMG = (600, 1000)
ATOM_PRICE = 500_000_000
ATOM_DAILY_USE = 2
ATOM_DMG = (3500, 4500)
ATOM_ENERGY_HIT = 25.0
ATOM_WORK_WINDOW = 3600


def _eq_row_today(row):
    day = _spy_day_key()
    same = row["eq_day"] == day
    return day, (int(row["gren_bought"] or 0) if same else 0), (int(row["atom_used"] or 0) if same else 0)


def _eq_panel(row, uid: int, qty: int = 1):
    day, bought, used = _eq_row_today(row)
    left = max(0, GRENADE_DAILY_BUY - bought)
    qty = max(1, min(qty, max(left, 1)))
    text = (f"🧰 <b>تجهیزات</b>\n\n"
            f"{GRENADE_CE} <b>نارنجک</b> — {GRENADE_PRICE:,} تومن\nموجودی: <b>{int(row['grenades'] or 0)}</b> | امروز خریدی: <b>{bought}/{GRENADE_DAILY_BUY}</b>\n\n"
            f"{ATOM_CE} <b>بمب اتم</b> — {ATOM_PRICE:,} تومن\nموجودی: <b>{int(row['atoms'] or 0)}</b> | امروز استفاده کردی: <b>{used}/{ATOM_DAILY_USE}</b>\n"
            f"هر بار که استفاده بشه، ۲۵ انرژی از اعضای همون گروه که تو یک ساعت اخیر کار کردن کم میشه.\n\n"
            f"روی پیام باس ریپلای کن و بنویس <code>جینگو نارنجک</code> یا <code>جینگو بمب اتم</code>.")
    rows = [
        [btn("➖", "danger", callback_data=f"eq:q:{uid}:{max(1, qty - 1)}"),
         btn(f"{qty} تا — {qty * GRENADE_PRICE:,}", None, callback_data=f"eq:noop:{uid}"),
         btn("➕", "success", callback_data=f"eq:q:{uid}:{min(max(left, 1), qty + 1)}")],
        [btn("خرید نارنجک", "success", icon=GRENADE_EID, callback_data=f"eq:g:{uid}:{qty}"),
         btn("خرید بمب اتم", "danger", icon=ATOM_EID, callback_data=f"eq:a:{uid}")],
        [btn("🔙 برگشت به قدرت‌ها", "primary", icon=EID_BACK, callback_data=f"sp:powers:{uid}")],
    ]
    return text, InlineKeyboardMarkup(rows)


async def equip_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    p = q.data.split(":")
    try:
        act, uid = p[1], int(p[2])
    except (IndexError, ValueError):
        await q.answer(); return
    if q.from_user.id != uid:
        await q.answer("این پنل مال شما نیست.", show_alert=True); return
    if act == "noop":
        await q.answer(); return
    await upsert_user(uid, q.from_user.full_name)
    alert = None
    qty = 1
    if act == "q":
        try:
            qty = int(p[3])
        except (IndexError, ValueError):
            qty = 1
    elif act in ("g", "a"):
        n = 1
        if act == "g":
            try:
                n = max(1, int(p[3]))
            except (IndexError, ValueError):
                n = 1
        async with pool.acquire() as c:
            async with c.transaction():
                r = await c.fetchrow("SELECT balance, grenades, atoms, eq_day, gren_bought, atom_used FROM users WHERE user_id=$1 FOR UPDATE", uid)
                day, bought, used = _eq_row_today(r)
                if act == "g":
                    left = GRENADE_DAILY_BUY - bought
                    if left <= 0:
                        alert = f"سقف خرید روزانه‌ی نارنجک ({GRENADE_DAILY_BUY} تا) پر شده؛ فردا دوباره بیا."
                    elif n > left:
                        alert = f"امروز فقط {left} نارنجک دیگه می‌تونی بخری."
                    elif int(r["balance"] or 0) < n * GRENADE_PRICE:
                        alert = f"موجودی جیبت کافی نیست؛ {n * GRENADE_PRICE:,} تومن لازمه."
                    else:
                        await c.execute("UPDATE users SET balance=balance-$1, grenades=grenades+$2, eq_day=$3, gren_bought=$4, atom_used=$5 WHERE user_id=$6",
                                        n * GRENADE_PRICE, n, day, bought + n, used, uid)
                        alert = f"{n} نارنجک خریدی! 💣"
                else:
                    if int(r["balance"] or 0) < ATOM_PRICE:
                        alert = f"موجودی جیبت کافی نیست؛ {ATOM_PRICE:,} تومن لازمه."
                    else:
                        await c.execute("UPDATE users SET balance=balance-$1, atoms=atoms+1, eq_day=$2, gren_bought=$3, atom_used=$4 WHERE user_id=$5",
                                        ATOM_PRICE, day, bought, used, uid)
                        alert = "بمب اتم خریدی! ☢️"
        qty = 1
    await q.answer(alert, show_alert=bool(alert)) if alert else await q.answer()
    row = await get_user(uid)
    text, kb = _eq_panel(row, uid, qty)
    try:
        await _sp_edit_text(q, B(text), parse_mode="HTML", reply_markup=kb)
    except Exception as e:
        if "not modified" not in str(e).lower():
            log.warning("equip panel edit failed", exc_info=True)


async def _eq_say(msg, text: str):
    try:
        return await msg.reply_text(B(text), parse_mode="HTML")
    except Exception:
        return await msg.reply_text(B(re.sub(r"<tg-emoji[^>]*>(.*?)</tg-emoji>", r"\1", text)), parse_mode="HTML")


async def boss_equip_use(update: Update, context: ContextTypes.DEFAULT_TYPE, kind: str) -> bool:
    """kind: 'g' نارنجک | 'a' بمب اتم. ریپلای روی پیام باس لازمه."""
    msg, user = update.effective_message, update.effective_user
    chat_id = msg.chat_id
    f = await pool.fetchrow("SELECT * FROM boss_fights WHERE chat_id=$1", chat_id)
    rep = msg.reply_to_message
    if not rep or not f or f["status"] != "active" or rep.message_id != f["msg_id"]:
        await _eq_say(msg, "برای استفاده از تجهیزات باید روی پیام باسِ فعال ریپلای کنی.")
        return True
    now = time.time()
    if f["ends_at"] <= now or f["hp"] <= 0:
        return True
    await upsert_user(user.id, user.full_name)
    day = _spy_day_key()
    reason = None
    async with pool.acquire() as c:
        async with c.transaction():
            r = await c.fetchrow("SELECT grenades, atoms, eq_day, gren_bought, atom_used, started FROM users WHERE user_id=$1 FOR UPDATE", user.id)
            _d, bought, used = _eq_row_today(r)
            if not r["started"]:
                reason = "اول ربات رو تو پی‌وی استارت کن بعد بیا!"
            elif kind == "g":
                if int(r["grenades"] or 0) <= 0:
                    reason = f"نارنجک نداری! از «خودم» ← قدرت‌ها ← تجهیزات بخرش ({GRENADE_PRICE:,} تومن)."
                else:
                    await c.execute("UPDATE users SET grenades=grenades-1, eq_day=$1, gren_bought=$2, atom_used=$3 WHERE user_id=$4", day, bought, used, user.id)
            else:
                if int(r["atoms"] or 0) <= 0:
                    reason = f"بمب اتم نداری! از «خودم» ← قدرت‌ها ← تجهیزات بخرش ({ATOM_PRICE:,} تومن)."
                elif used >= ATOM_DAILY_USE:
                    reason = f"امروز {ATOM_DAILY_USE} بمب اتم استفاده کردی؛ سقف روزانه پر شده."
                else:
                    await c.execute("UPDATE users SET atoms=atoms-1, eq_day=$1, gren_bought=$2, atom_used=$3 WHERE user_id=$4", day, bought, used + 1, user.id)
    if reason:
        await _eq_say(msg, reason)
        return True
    lo, hi = GRENADE_DMG if kind == "g" else ATOM_DMG
    dmg = random.randint(lo, hi)
    new_hp = await pool.fetchval("UPDATE boss_fights SET hp = GREATEST(hp - $2::bigint, 0), last_hitter = $3::bigint WHERE chat_id=$1 AND status='active' AND hp > 0 RETURNING hp", chat_id, dmg, user.id)
    if new_hp is None:   # باس همون لحظه مرد/فرار کرد: تجهیزات برمی‌گرده
        if kind == "g":
            await pool.execute("UPDATE users SET grenades=grenades+1 WHERE user_id=$1", user.id)
        else:
            await pool.execute("UPDATE users SET atoms=atoms+1, atom_used=GREATEST(atom_used-1,0) WHERE user_id=$1", user.id)
        return True
    await pool.execute("INSERT INTO boss_hits (chat_id, user_id, name, damage, hits) VALUES ($1,$2,$3,$4,1) ON CONFLICT (chat_id, user_id) DO UPDATE SET damage = boss_hits.damage + $4, hits = boss_hits.hits + 1, name = $3",
                       chat_id, user.id, user.full_name, dmg)
    boss_name = html.escape(BOSSES[f["idx"]]["name"])
    uname = html.escape(user.full_name)
    if kind == "g":
        text = f"{GRENADE_CE} {uname} یه نارنجک به {boss_name} پرتاب کرد و {dmg:,} آسیب زد!\n❤️ جان باقی مانده باس: {int(new_hp):,}"
    else:
        cand = [int(r["user_id"]) for r in await pool.fetch(
            "SELECT user_id FROM users WHERE last_shift >= $1::double precision AND user_id <> $2::bigint LIMIT 300", now - ATOM_WORK_WINDOW, user.id)]

        async def _is_member(uid_: int) -> bool:   # فقط اعضای همین گروه
            try:
                m_ = await context.bot.get_chat_member(chat_id, uid_)
            except Exception:
                return False
            st_ = str(getattr(m_, "status", ""))
            return st_ in ("creator", "administrator", "member") or (st_ == "restricted" and getattr(m_, "is_member", False))

        flags = await asyncio.gather(*(_is_member(u_) for u_ in cand)) if cand else []
        victims = [u_ for u_, ok_ in zip(cand, flags) if ok_]
        hit_n = 0
        if victims:
            hit_n = await pool.fetchval(
                "WITH u AS (UPDATE users SET energy = GREATEST(energy - $1::double precision, 0) WHERE user_id = ANY($2::bigint[]) RETURNING 1) SELECT count(*) FROM u",
                ATOM_ENERGY_HIT, victims)
        text = (f"{ATOM_CE} {uname} بمب اتم رو روی {boss_name} انداخت و {dmg:,} آسیب زد!\n❤️ جان باقی مانده باس: {int(new_hp):,}\n"
                f"⚡ انفجار {int(ATOM_ENERGY_HIT)} انرژی از {int(hit_n or 0)} نفر که تو یک ساعت اخیر کار کرده بودن کم کرد!")
    await _eq_say(msg, text)
    if new_hp <= 0:
        await _boss_finish_kill(context.bot, chat_id, user.id)
    else:
        _BOSS_DIRTY.add(chat_id)
    return True


async def boss_text(update: Update, context: ContextTypes.DEFAULT_TYPE, text: str) -> bool:
    key = _word_key(text)
    user, msg = update.effective_user, update.effective_message
    if key in ("جینگونارنجک", "جینگوبمباتم", "جینگوبمباتمی"):
        return await boss_equip_use(update, context, "g" if key == "جینگونارنجک" else "a")
    if key in BOSS_SPAWN_WORDS and not msg.reply_to_message and has_perm(user.id, "panel"):
        if not await boss_group_allowed(context.bot, msg.chat_id):
            await msg.reply_text(BP(f"غول فقط تو گروه‌های {BOSS_MIN_MEMBERS} عضو به بالا میاد؛ این گروه کمتر از اینه."), parse_mode="HTML")
            return True
        ok = await boss_spawn(context.bot, msg.chat_id, force=True)
        if not ok:
            await msg.reply_text(BP("الان یه غول فعاله!"), parse_mode="HTML")
        return True
    if key in BOSS_WORDS or key.startswith("شلیک"):
        return await boss_hit(update, context)
    return False


PET_SAVE_EVERY = 1800     # هر ۳۰ دقیقه
PET_SAVE_BASE = 4000      # تومن به‌ازای هر پت × شماره‌ی پت (۱ تا ۵) در هر دور، وقتی شکم و محبوبیت پُر باشه


async def pet_savings_tick():
    """هر پت یکم پول تو پروفیت صاحبش پس‌انداز می‌کنه؛ شکم یا محبوبیت کم باشه کمتر، خالی باشه هیچی."""
    now = time.time()
    rows = await pool.fetch("SELECT user_id, pets_owned, pet_stats FROM users WHERE pets_owned > 0")
    for r in rows:
        total = 0
        for idx in range(1, int(r["pets_owned"]) + 1):
            st_ = _pet_st(r, idx, now)
            belly = st_["belly"] / 100.0
            pop = min(1.0, st_["pop"] / PET_POP_CAP)
            f = belly * (0.3 + 0.7 * pop) if belly > 0.02 else 0.0
            total += int(PET_SAVE_BASE * idx * f)
        if total <= 0:
            continue
        try:
            async with pool.acquire() as c:
                async with c.transaction():
                    await jm_add(c, int(r["user_id"]), total)
        except Exception:
            log.exception("pet savings failed")


async def boss_loop(app: Application):
    """هر چند ثانیه: آپدیت پیام غول‌ها، فرار غول‌های بی‌جواب، و ظاهر شدن غول جدید تو گروه‌های فعال."""
    tick = 0
    last_pet = time.time()
    while True:
        await asyncio.sleep(BOSS_TICK)
        tick += 1
        try:
            bot = app.bot
            if time.time() - last_pet >= PET_SAVE_EVERY:
                last_pet = time.time()
                await pet_savings_tick()
            for cid in list(_BOSS_DIRTY):
                _BOSS_DIRTY.discard(cid)
                await _boss_edit(bot, cid)
            now = time.time()
            for r in await pool.fetch("SELECT chat_id FROM boss_fights WHERE status='active' AND ends_at <= $1::double precision", now):
                cid = int(r["chat_id"])
                await pool.execute("UPDATE boss_fights SET status='fled' WHERE chat_id=$1", cid)
                await _boss_edit(bot, cid, "fled")
            if tick % 15 == 0:   # هر ~۶۰ ثانیه زمان‌بندی ظاهر شدن رو چک کن
                for r in await pool.fetch("SELECT chat_id FROM chats"):
                    cid = int(r["chat_id"])
                    s = await pool.fetchval("SELECT next_spawn FROM boss_sched WHERE chat_id=$1", cid)
                    if s is None:   # گروه جدید: اولین غول چند دقیقه‌ی دیگه (پخش میشه که همه‌ی گروه‌ها یهو شروع نشن)
                        await pool.execute("INSERT INTO boss_sched (chat_id, next_spawn) VALUES ($1,$2) ON CONFLICT DO NOTHING", cid, now + random.randint(600, 2400))
                        continue
                    if s > now:
                        continue
                    active = await pool.fetchval("SELECT 1 FROM group_msgs WHERE chat_id=$1 AND ts > $2::double precision LIMIT 1", cid, now - BOSS_ACTIVE_WINDOW)
                    if not active:
                        await pool.execute("UPDATE boss_sched SET next_spawn=$2 WHERE chat_id=$1", cid, now + 1800)
                        continue
                    if not await boss_group_allowed(bot, cid):   # گروه کوچیک (زیر ۲۱ عضو): بعداً دوباره چک میشه
                        await pool.execute("UPDATE boss_sched SET next_spawn=$2 WHERE chat_id=$1", cid, now + 1800)
                        continue
                    await boss_spawn(bot, cid)
                    await asyncio.sleep(1.5)
        except asyncio.CancelledError:
            raise
        except Exception:
            log.exception("boss loop failed")


# ───────────────────────── کافه جینگو ─────────────────────────
# فقط برای سطح ۳ به بالا (همون «سطح» پنل خودم). منو: «جینگو کافه» یا «کافه جینگو».
# دعوت: ریپلای روی یه نفر + «جینگو دعوت به کافه» ← طرف قبول کنه ← دعوت‌کننده سفارش میده ← پولش از دعوت‌کننده کم میشه
# و انرژیِ سفارش به هر دو نفر میرسه. آب رایگانه (هر ۵ دقیقه یه بار، ۱ انرژی)؛ بقیه‌ی آیتم‌ها گرون‌ان و ۲ تا ۱۵ انرژی میدن.
CAFE_MIN_LEVEL = 3
CAFE_IMG = BASE_DIR / "cafe.jpg"          # عکس کافه؛ کنار bot.py
_CAFE_FID = None
CAFE_WATER_COOLDOWN = 5 * 60              # آب رایگان: هر کاربر هر ۵ دقیقه یه بار
CAFE_INVITE_TTL = 300                     # مهلت جواب به دعوت
CAFE_ORDER_TTL = 600                      # مهلت سفارشِ دعوت‌کننده بعد از قبول شدن
CAFE_EID = "5267453380506177056"
CAFE_CE = f'<tg-emoji emoji-id="{CAFE_EID}">☕</tg-emoji>'
# کلید: (اسم، ایموجی پرمیوم، ایموجی جایگزین، قیمت تومن، کمترین انرژی، بیشترین انرژی)  — به ترتیب قیمت
CAFE_ITEMS = {
    "water":    ("آب",         "6014834907564482606", "💧", 0,         1.0,  1.0),
    "soda":     ("نوشابه",     "5359616893277721113", "🥤", 100_000,   2.0,  4.0),
    "milk":     ("شیر بسکویت", None,                  "🥛", 150_000,   3.0,  6.0),
    "coffee":   ("قهوه",       "5267453380506177056", "☕", 250_000,   4.0,  8.0),
    "espresso": ("اسپرسو",     "5285492870214604805", "☕", 400_000,   6.0,  10.0),
    "latte":    ("آیس لته",    "5368571264434717112", "🧋", 600_000,   8.0,  12.0),
    "beer":     ("آبجو",       "6014787710168894973", "🍺", 900_000,   10.0, 14.0),
    "energy":   ("انرژی‌زا",   "5413878590972372676", "⚡", 1_500_000, 12.0, 15.0),
}
CAFE_MENU_WORDS = {"جینگوکافه", "کافهجینگو"}
CAFE_INVITE_WORDS = {"جینگودعوتبهکافه", "جینگودعوتکافه"}


def _cafe_ce(key: str) -> str:
    _n, eid, fb, *_ = CAFE_ITEMS[key]
    return f'<tg-emoji emoji-id="{eid}">{fb}</tg-emoji>' if eid else fb


def _cafe_short(price: int) -> str:
    if price <= 0:
        return "رایگان"
    return f"{price / 1_000_000:g}m" if price >= 1_000_000 else f"{price // 1000}k"


def _cafe_menu_text() -> str:
    lines = [f"{CAFE_CE} کافه جینگو",
             "هرچی بخوری انرژی می‌گیری؛ با دعوت یه رفیق، هر دو نفر انرژی می‌گیرید 🥂", ""]
    for k, (name, _e, _f, price, lo, hi) in CAFE_ITEMS.items():
        cost = f"رایگان (هر {CAFE_WATER_COOLDOWN // 60} دقیقه)" if price == 0 else f"{price:,} تومن"
        en = _fmt_en(lo) if lo == hi else f"{_fmt_en(lo)} تا {_fmt_en(hi)}"
        lines.append(f"{_cafe_ce(k)} {name} — {cost} · ⚡ {en}")
    lines += ["", "دعوت: ریپلای روی یه نفر + <code>جینگو دعوت به کافه</code>", f"ویژه‌ی لول {CAFE_MIN_LEVEL} به بالا"]
    return B("\n".join(lines))


def _cafe_kb(cb_fn) -> InlineKeyboardMarkup:
    btns = [btn(f"{name} · {_cafe_short(price)}", "success" if price == 0 else "primary", icon=eid, callback_data=cb_fn(k))
            for k, (name, eid, _f, price, _lo, _hi) in CAFE_ITEMS.items()]
    return InlineKeyboardMarkup([btns[i:i + 2] for i in range(0, len(btns), 2)])


async def _cafe_level(uid: int) -> int:
    row = await get_user(uid)
    return row_level(row) if row else 1


async def send_cafe_menu(bot, chat_id: int, uid: int, reply_to: int | None = None):
    """عکس کافه + منو + دکمه‌های سفارش برای خودِ کاربر. اگه عکس نبود/نشد، متنی می‌فرسته."""
    global _CAFE_FID
    text = _cafe_menu_text()
    kb = _cafe_kb(lambda k: f"cf:b:{uid}:{k}")
    rp = ReplyParameters(message_id=reply_to, allow_sending_without_reply=True) if reply_to else None
    for cap in (text, re.sub(r"<tg-emoji[^>]*>(.*?)</tg-emoji>", r"\1", text)):
        try:
            if _CAFE_FID:
                return await bot.send_photo(chat_id, _CAFE_FID, caption=cap, parse_mode="HTML", reply_markup=kb, reply_parameters=rp)
            if CAFE_IMG.exists():
                with open(CAFE_IMG, "rb") as f:
                    m = await bot.send_photo(chat_id, f, caption=cap, parse_mode="HTML", reply_markup=kb, reply_parameters=rp)
                try:
                    _CAFE_FID = m.photo[-1].file_id
                except Exception:
                    pass
                return m
            break
        except Exception:
            log.warning("cafe photo send failed", exc_info=True)
            _CAFE_FID = None
    return await send_html(bot, chat_id, text, reply_markup=kb, reply_parameters=rp)


async def _cafe_order(payer: int, guests: list, key: str):
    """سفارش اتمیک: سطح همه، کولداون آبِ رایگان یا پولِ نقدِ payer، و انرژی برای payer + guests (همه یه مقدار).
    برمی‌گردونه (خطا | None, اطلاعات | None)."""
    _n, _e, _f, price, lo, hi = CAFE_ITEMS[key]
    ids = [payer] + [g for g in guests if g != payer]
    now = time.time()
    async with pool.acquire() as c:
        async with c.transaction():
            rows = await c.fetch("SELECT * FROM users WHERE user_id=ANY($1::bigint[]) ORDER BY user_id FOR UPDATE", ids)
            by = {int(r["user_id"]): r for r in rows}
            if len(by) != len(ids):
                return "کاربر پیدا نشد.", None
            if any(row_level(by[u]) < CAFE_MIN_LEVEL for u in ids):
                return f"کافه فقط برای لول {CAFE_MIN_LEVEL} به بالاست.", None
            if price == 0:
                last = await c.fetchval("SELECT last_ts FROM actor_cooldowns WHERE actor_id=$1 AND kind='cafe_water'", payer) or 0
                left = CAFE_WATER_COOLDOWN - (now - float(last))
                if left > 0:
                    return f"آب رایگان هر {CAFE_WATER_COOLDOWN // 60} دقیقه یه بار؛ {_duration_fa(int(left) + 1)} دیگه.", None
                await c.execute("INSERT INTO actor_cooldowns(actor_id,kind,last_ts) VALUES($1,'cafe_water',$2) "
                                "ON CONFLICT(actor_id,kind) DO UPDATE SET last_ts=EXCLUDED.last_ts", payer, now)
            else:
                paid = await c.fetchval("UPDATE users SET balance=balance-$1 WHERE user_id=$2 AND balance>=$1 RETURNING balance", price, payer)
                if paid is None:
                    return f"پول نقدت (جیب) کافی نیست؛ {CAFE_ITEMS[key][0]} {price:,} تومنه.", None
            gain = round(random.uniform(lo, hi), 1)
            ens = {}
            for u in ids:
                ens[u] = float(await c.fetchval("UPDATE users SET energy=LEAST(energy+$1,$2) WHERE user_id=$3 RETURNING energy", gain, ENERGY_MAX, u))
    return None, {"gain": gain, "price": price, "energy": ens, "names": {u: by[u]["name"] for u in ids}}


def _cafe_result_text(key: str, payer: int, guest, info: dict) -> str:
    RLM = "\u200f"
    name, _e, _f, price, _lo, _hi = CAFE_ITEMS[key]
    pct = lambda u: f"{_fmt_en(info['energy'][u] / ENERGY_MAX * 100)}٪"
    a = _ltr_name(payer, info["names"][payer])
    cost = "رایگان 😎" if price == 0 else f"{price:,} تومن از {a} کم شد"
    en_ce = ce("energy", 1, "⚡")
    if guest is None:
        return (f"{RLM}{CAFE_CE} {a} یه {_cafe_ce(key)} {name} سفارش داد و نوشید\n\n"
                f"{RLM}{en_ce} +{_fmt_en(info['gain'])} انرژی (الان {pct(payer)})\n{RLM}{MONEY_CE} {cost}")
    b = _ltr_name(guest, info["names"][guest])
    return (f"{RLM}{CAFE_CE} {a} برای خودش و {b} {_cafe_ce(key)} {name} سفارش داد 🥂\n\n"
            f"{RLM}{en_ce} هر دو نفر +{_fmt_en(info['gain'])} انرژی گرفتن\n"
            f"{RLM}{a}: {pct(payer)} · {b}: {pct(guest)}\n{RLM}{MONEY_CE} {cost}")


def _cafe_gc(d: dict, ttl: int):
    if len(d) > 500:
        now = time.time()
        for k in [k for k, v in d.items() if now - v > ttl * 2]:
            d.pop(k, None)


async def cafe_text(update: Update, context: ContextTypes.DEFAULT_TYPE, text: str) -> bool:
    """«جینگو کافه» / «کافه جینگو» = منو؛ ریپلای + «جینگو دعوت به کافه» = دعوت."""
    msg, user = update.effective_message, update.effective_user
    key = _word_key(text)
    if key not in CAFE_MENU_WORDS and key not in CAFE_INVITE_WORDS:
        return False
    await upsert_user(user.id, user.full_name)
    lvl = await _cafe_level(user.id)
    if lvl < CAFE_MIN_LEVEL:
        await _eq_say(msg, f"{CAFE_CE} کافه جینگو از لول {CAFE_MIN_LEVEL} باز میشه؛ تو الان لول {lvl} هستی.")
        return True
    if key in CAFE_MENU_WORDS:
        await send_cafe_menu(context.bot, msg.chat_id, user.id, reply_to=msg.message_id)
        return True
    rep = msg.reply_to_message
    target = rep.from_user if rep else None
    if target is None or target.is_bot:
        await _eq_say(msg, "برای دعوت، روی پیام اون نفر ریپلای کن و بنویس: جینگو دعوت به کافه")
        return True
    if target.id == user.id:
        await _eq_say(msg, "خودت رو که نمی‌تونی دعوت کنی 😅")
        return True
    await pool.execute("INSERT INTO users(user_id,name) VALUES($1,$2) ON CONFLICT(user_id) DO NOTHING", target.id, target.full_name)
    if await _cafe_level(target.id) < CAFE_MIN_LEVEL:
        await _eq_say(msg, f"{_ltr_name(target.id, target.full_name)} هنوز لول {CAFE_MIN_LEVEL} نشده؛ کافه فقط برای لول {CAFE_MIN_LEVEL} به بالاست.")
        return True
    a = _ltr_name(user.id, user.full_name)
    b = _ltr_name(target.id, target.full_name)
    kb = InlineKeyboardMarkup([[btn("قبول می‌کنم", "success", icon=CAFE_EID, callback_data=f"cf:y:{user.id}:{target.id}"),
                                btn("نه ممنون", "danger", callback_data=f"cf:n:{user.id}:{target.id}")]])
    m = await send_html(context.bot, msg.chat_id,
                        B(f"{CAFE_CE} {a} {b} رو به کافه جینگو دعوت کرد ✨\n\n{b}، دعوت رو قبول می‌کنی؟ 👇"), reply_markup=kb)
    inv = context.application.bot_data.setdefault("cafe_inv", {})
    _cafe_gc(inv, CAFE_INVITE_TTL)
    inv[(msg.chat_id, m.message_id)] = time.time()
    return True


async def cafe_cb(update: Update, context: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    p = q.data.split(":")
    chat_id = q.message.chat_id
    try:
        act = p[1]
        if act == "b":      # سفارش برای خودم از منوی عکس‌دار
            uid, key = int(p[2]), p[3]
            if key not in CAFE_ITEMS:
                await q.answer(); return
            if q.from_user.id != uid:
                await q.answer("این منو مال تو نیست؛ خودت بنویس «جینگو کافه».", show_alert=True); return
            await upsert_user(uid, q.from_user.full_name)
            err, info = await _cafe_order(uid, [], key)
            if err:
                await q.answer(err[:190], show_alert=True); return
            await q.answer("نوش جان ☕")
            await send_html(context.bot, chat_id, B(_cafe_result_text(key, uid, None, info)))
            return
        a_id, b_id = int(p[2]), int(p[3])
    except (IndexError, ValueError):
        await q.answer("درخواست نامعتبره.", show_alert=True); return
    inv = context.application.bot_data.setdefault("cafe_inv", {})
    ordr = context.application.bot_data.setdefault("cafe_ord", {})
    mk = (chat_id, q.message.message_id)
    if act in ("y", "n"):
        if q.from_user.id != b_id:
            await q.answer("فقط کسی که دعوت شده می‌تونه جواب بده.", show_alert=True); return
        ts = inv.pop(mk, None)
        if ts is None or time.time() - ts > CAFE_INVITE_TTL:
            await q.answer("این دعوت منقضی شده.", show_alert=True)
            await edit_html(q, B("⌛ این دعوت منقضی شد.")); return
        rows = await pool.fetch("SELECT user_id,name FROM users WHERE user_id=ANY($1::bigint[])", [a_id, b_id])
        nm = {int(r["user_id"]): r["name"] for r in rows}
        a = _ltr_name(a_id, nm.get(a_id)); b = _ltr_name(b_id, nm.get(b_id))
        if act == "n":
            await q.answer("رد شد.")
            await edit_html(q, B(f"🚫 {b} دعوت {a} رو به کافه رد کرد 😅")); return
        if await _cafe_level(a_id) < CAFE_MIN_LEVEL or await _cafe_level(b_id) < CAFE_MIN_LEVEL:
            await q.answer(f"کافه فقط برای لول {CAFE_MIN_LEVEL} به بالاست.", show_alert=True)
            await edit_html(q, B("❌ این دعوت دیگه معتبر نیست.")); return
        _cafe_gc(ordr, CAFE_ORDER_TTL)
        ordr[mk] = time.time()
        await q.answer("قبول شد ☕")
        await edit_html(q, B(f"{CAFE_CE} {b} دعوت {a} رو قبول کرد 🎉\n\n{a}، سفارش بده؛ حساب با خودته و انرژیش به هر دو نفرتون می‌رسه 👇"),
                        reply_markup=_cafe_kb(lambda k: f"cf:o:{a_id}:{b_id}:{k}"))
        return
    if act == "o":
        key = p[4] if len(p) > 4 else ""
        if key not in CAFE_ITEMS:
            await q.answer(); return
        if q.from_user.id != a_id:
            await q.answer("فقط کسی که دعوت کرده می‌تونه سفارش بده.", show_alert=True); return
        ts = ordr.get(mk)
        if ts is None or time.time() - ts > CAFE_ORDER_TTL:
            ordr.pop(mk, None)
            await q.answer("این سفارش منقضی شده.", show_alert=True)
            await edit_html(q, B("⌛ مهلت سفارش تموم شد.")); return
        err, info = await _cafe_order(a_id, [b_id], key)
        if err:
            await q.answer(err[:190], show_alert=True); return
        ordr.pop(mk, None)
        await q.answer("نوش جان ☕")
        await edit_html(q, B(_cafe_result_text(key, a_id, b_id, info)))
        return
    await q.answer()


def _make_update_processor():
    """آپدیت‌های کاربرهای مختلف همزمان پردازش میشن؛ آپدیت‌های یک کاربر به ترتیب (تا دو کلیک پشت‌هم با هم قاطی نشن)."""
    try:
        from telegram.ext import SimpleUpdateProcessor
    except Exception:
        return None

    class _PerUserProcessor(SimpleUpdateProcessor):
        def __init__(self, n):
            super().__init__(n)
            self._locks: dict = {}

        async def do_process_update(self, update, coroutine):
            u = getattr(update, "effective_user", None)
            c = getattr(update, "effective_chat", None)
            key = ("u", u.id) if u else (("c", c.id) if c else None)
            if key is None:
                await coroutine
                return
            lock = self._locks.get(key)
            if lock is None:
                if len(self._locks) > 5000:
                    self._locks = {k: v for k, v in self._locks.items() if v.locked()}
                lock = self._locks[key] = asyncio.Lock()
            async with lock:
                await coroutine

    return _PerUserProcessor(128)


